-- Catálogo, parte 3 de 4. Correr en orden, después de 01_esquema.sql.
insert into public.peliculas (tmdb_id, media_type, titulo, titulo_tmdb, titulo_original, anio, direccion, sinopsis, poster_path, backdrop_path, vote_average, trailer_youtube, listas, pagina_libro, donde_ver, cruce, candidatos) values
(3121, 'movie', 'Nashville', 'Nashville', 'Nashville', 1975, 'Robert Altman', 'Drama en torno a la industria discográfica de esta ciudad. En el fondo es una sátira de la sociedad americana a través de la música country.', '/vna9YzXdMC7ju21SAI2cPBdpNpq.jpg', '/lHH8o3YWBjoteijAI8yTxG3qqpX.jpg', 7.3, 'Ty3oclCA-uM', array['1001']::text[], 608, null, 'segura', null),
(51857, 'movie', 'Cría cuervos', 'Cría cuervos', 'Cría cuervos', 1976, 'Carlos Saura', 'Ana, una niña de ocho años que vive en Madrid con su abuela y sus dos hermanas, llora la muerte de su madre.', '/kbe6KjerFbvXaQvLkwa8KCoUlDJ.jpg', '/sc600L1efonWcAm1HDA6WMAAmn0.jpg', 7.5, 'X6WPyYP2N38', array['1001']::text[], 609, null, 'segura', null),
(689, 'movie', 'El viaje de los comediantes', 'El viaje de los comediantes', 'Ο θίασος', 1975, 'Theo Angelopoulos', 'Durante la Segunda Guerra Mundial (1939-1945), Grecia sufre la ocupación de las tropas nazis. En esas circunstancias, una compañía teatral realiza una gira por el país, aunque sus representaciones se ven continuamente interrumpidas por los conflictos políticos. Por otra parte, una de las actrices intenta vengarse de su madre a la que responsabiliza de la muerte de su padre. Su hermano, un partisano, la ayudará a satisfacer sus propósitos.', '/mzRQAdGkV8uOwOu7G7r0wmhQkz6.jpg', '/rlUNDYAjvr1zfAXesT3ScxfBXLc.jpg', 7.2, '9Fa5Ig1eDv0', array['1001']::text[], 610, null, 'segura', null),
(578, 'movie', 'Tiburón', 'Tiburón', 'Jaws', 1975, 'Steven Spielberg', 'En la costa de un pequeño pueblo del Este de Estados Unidos, un enorme tiburón ataca a varias personas. Temiendo las fatales consecuencias que esto puede provocar en el negocio turístico, el alcalde se niega a cerrar las playas y a difundir la noticia. Pero un nuevo ataque del tiburón, en la propia playa, termina con la vida de otro bañista. El terror se ha hecho público, así que un veterano cazador de tiburones, un científico y el jefe de la policía local se unen para dar caza al temible escualo...', '/aCqHb3eFQV8raX30OfGurqPlpjh.jpg', '/i1yf91svRHX45l9BXL8rVFzLoPH.jpg', 7.7, 'IBgwS4JedEw', array['1001']::text[], 612, null, 'segura', null),
(7340, 'movie', 'Carrie', 'Carrie', 'Carrie', 1976, 'Brian De Palma', 'Carrie es una torturada estudiante de secundaria que no encaja en su entorno, sin confianza en sí misma y sin amigos… y sin ser consciente de la amplitud de sus poderes telequinéticos. Pero cuando su psicótica madre y sus sádicos compañeros de clase llegan demasiado lejos, la una vez tímida adolescente se convierte en una máquina desenfrenada y, con ayuda de su «don especial», hace caer el infierno sobre sus cabezas en un frenesí de sangre, fuego y azufre que te llevará a las profundidades del horror… y aún más lejos.', '/6JTL8AQ4jGFmFMTA6H7oVGGKaPp.jpg', '/zwJFfKQdfiptK2GY6N8GkZFrAxJ.jpg', 7.3, 'zbdIXI1s3aU', array['1001']::text[], 613, null, 'segura', null),
(32040, 'movie', 'The Killing of a Chinese Bookie', 'El asesinato de un corredor de apuestas chino', 'The Killing of a Chinese Bookie', 1976, 'John Cassavetes', 'Cosmo Vitelli, un veterano de la Guerra de Corea (1950-1953) con deudas de juego, posee un local de striptease en Las Vegas. Cuando pierde 23.000 dólares en una partida ilegal, sus acreedores le sugieren que pague la deuda con un asesinato.', '/5RGHVHadR3s226PIAxWOX66Fh3C.jpg', '/71oqZMM6dgKvi1WQztOoUHSzDdZ.jpg', 7.0, '1UTPS2iwAX4', array['1001']::text[], 613, null, 'segura', null),
(10747, 'movie', 'El fuera de la ley', 'El fuera de la ley', 'The Outlaw Josey Wales', 1976, 'Clint Eastwood', 'A punto de finalizar la Guerra de Secesión, un grupo de unionistas, liderados por el sádico capitán Terrill, asesina a la familia de un granjero llamado Joseph Wales. Movido por el odio y el deseo de venganza, se une a un grupo de rebeldes. Poco después, finaliza la contienda, el ejército de la Unión ofrece la amnistía a todas las guerrillas y sus compañeros aceptan. La rabia y el dolor siguen vivos dentro de Wales, y no se rendirá tan fácilmente.', '/5TzrWk1mSoavRcdkNEhVpKftICv.jpg', '/nEe0ziWyVhGTtuoXe2msdkz6NlO.jpg', 7.5, 'YvXl6Ij-LhQ', array['1001']::text[], 614, null, 'segura', null),
(891, 'movie', 'Todos los hombres del presidente', 'Todos los hombres del presidente', 'All the President''s Men', 1976, 'Alan J. Pakula', 'En 1972, dos jóvenes periodistas del diario The Washington Post, Bob Woodward y Carl Bernstein, comienzan a investigar el allanamiento del cuartel general del Partido Demócrata en Washington. Sus descubrimientos desencadenan el llamado ''caso Watergate'', que provocó la dimisión del presidente Richard Nixon.', '/wmocd5vF8Nt0oz06qCKMEL1mjBD.jpg', '/aAMn59bq6DZQtWoYqsIOUkVWSgc.jpg', 7.7, 'k5y8SW2KyTY', array['1001']::text[], 614, null, 'segura', null),
(1366, 'movie', 'Rocky', 'Rocky', 'Rocky', 1976, 'John G. Avildsen', 'Rocky Balboa es un desconocido boxeador a quien se le ofrece la posibilidad de pelear por el título mundial de los pesos pesados. Con mucha fuerza de voluntad, Rocky se preparará concienzudamente para este combate, y también para los cambios que producirá en su vida.', '/yyoGappf3WxXRrHz23yNbH2MffI.jpg', '/bacOuUnRBoAO1NjMfsAGX2EKRrS.jpg', 7.8, 'yTqsJT1mFng', array['1001']::text[], 615, null, 'segura', null),
(103, 'movie', 'Taxi Driver', 'Taxi Driver', 'Taxi Driver', 1976, 'Martin Scorsese', 'Un ex marine insomne maneja un taxi de noche por Nueva York y se va hundiendo en el aislamiento y la furia contra la ciudad.', '/9G26DnAeMbA4sp58Gi0Vze6eQv4.jpg', '/9uddYYTNcLWpzUkl5iw1RUYhLhY.jpg', 8.1, 'zdqCqDSTVNI', array['1001','clasicos']::text[], 616, null, 'segura', null),
(10774, 'movie', 'Network, un mundo implacable', 'Network, un mundo implacable', 'Network', 1976, 'Sidney Lumet', 'Tras 25 años trabajando en una cadena, el veterano presentador Howard Beale debe abandonar su puesto por el bajo nivel de audiencia. Su jefe y mejor amigo, Max Schumacher, le da dos semanas para despedirse de los espectadores. Beale, viudo y alcohólico, queda trastocado y decide anunciar durante una emisión que se suicidará en su último programa ante las cámaras. El hecho sin precedentes provoca una gran expectación y los propios compañeros tratarán de convertir la destrucción de este hombre en un negocio rentable.', '/r8CrxsvFK8JIBUpIZX0rBmojsC9.jpg', '/m4Iyzh9YVOh0ra7UwdMoJcrjxkx.jpg', 7.8, 'T-PyQ1gMT6o', array['1001']::text[], 618, null, 'segura', null),
(5879, 'movie', 'El imperio de los sentidos', 'El imperio de los sentidos', '愛のコリーダ', 1976, 'Nagisa Ōshima', 'Una pareja de amantes vive una historia de amor llevada hasta límites inimaginables. La pasión se ha adueñado de ellos. El sexo ha pasado a ser lo único importante de sus vidas. Las ansias de la mujer por poseer a su hombre parecen inagotables y crecen cada día más hasta llegar a confundir el placer con el dolor.', '/qZbSd6bVakhfEbjDhgz7iXjSSAL.jpg', '/g3L6tOvJIRWSkxnhmoEW1SKEvW3.jpg', 6.6, 'w-o8EKjXJPQ', array['1001']::text[], 619, null, 'segura', null),
(50183, 'movie', 'La ascensión', 'La ascensión', 'Восхождение', 1977, 'Лариса Шепитько', 'Durante la Segunda Guerra Mundial, dos partisanos soviéticos se apartan del grupo, que está hambriento, para ir a una pequeña granja a coger provisiones. Pero, como los alemanes han llegado primero, tendrán que seguir recorriendo territorio ocupado para encontrar otro sitio donde abastecerse.', '/lWioTDPDhz0KHlm83FJnv0MIrok.jpg', '/A2IJUMyMJZCowjWq32GWqLcEmg9.jpg', 7.9, '5M7Y_zun-vg', array['1001']::text[], 619, null, 'segura', null),
(3870, 'movie', 'Novecento', 'Novecento', 'Novecento', 1976, 'Bernardo Bertolucci', 'En el año 1901, en una finca en el norte de italia, nacen el mismo día el hijo de un terrateniente y el hijo de un bracero. La película narra la vida de ambos y sus respectivas familias durante ochenta años. La amistad de los protagonistas se verá nublada por sus diferentes actitudes frente al fascismo. Famoso drama que hace un complejo recorrido político y social por la Italia del siglo XX.', '/5BeMiIveAXnmHvuZVkRpCeE0pWR.jpg', '/x5948QrtMqvnf2OBP9ESpdmONQa.jpg', 7.8, 'TY2hneWCiiQ', array['1001']::text[], 620, null, 'segura', null),
(991, 'movie', 'El hombre que cayó a la tierra', 'El hombre que cayó a la Tierra', 'The Man Who Fell to Earth', 1976, 'Nicolas Roeg', 'Un extraterrestre viene a la Tierra con forma humana con la intención de conseguir agua para su propio planeta, que está moribundo. Una vez aquí, y dada su inteligencia superior, el alienígena comienza a escalar social y financieramente para conseguir su propósito.', '/3BESsAVymU5q2emICGNnLWuN2k0.jpg', '/ew3x9p8A28p3sLE8OaHwUsb1mSQ.jpg', 6.5, 'y72dBnyXUho', array['1001']::text[], 621, null, 'segura', null),
(11, 'movie', 'La guerra de las galaxias', 'La guerra de las galaxias', 'Star Wars', 1977, 'George Lucas', 'La princesa Leia, líder del movimiento rebelde que desea reinstaurar la República en la galaxia en los tiempos ominosos del Imperio, es capturada por las malévolas Fuerzas Imperiales, capitaneadas por el implacable Darth Vader, el sirviente más fiel del emperador. El intrépido Luke Skywalker, ayudado por Han Solo, capitán de la nave espacial "El Halcón Milenario", y los androides, R2D2 y C3PO, serán los encargados de luchar contra el enemigo y rescatar a la princesa para volver a instaurar la justicia en el seno de la Galaxia.', '/4hOUzmButYUeON0prG3RpbqS7ag.jpg', '/zqkmTXzjkAgXmEWLRsY4UpTWCeo.jpg', 8.2, 'beAH5vea99k', array['1001']::text[], 622, null, 'segura', null),
(840, 'movie', 'Encuentros en la tercera fase', 'Encuentros en la tercera fase', 'Close Encounters of the Third Kind', 1977, 'Steven Spielberg', 'Una noche, cerca de su casa, en Indiana, Roy Neary (Richard Dreyfuss) observa en el cielo unos misteriosos objetos voladores. Obsesionado por comprender lo que ha visto, se distancia de su esposa (Teri Garr). Neary encuentra apoyo en Jillian Guiler (Melinda Dillon), que también fue testigo de esas visiones nocturnas. Juntos buscan una respuesta a ese misterio que ha alterado sus vidas. Al mismo tiempo, un nutrido grupo de científicos internacionales, bajo la dirección de Claude Lacombe (François Truffaut), empieza a investigar las apariciones de OVNIS y otros extraños fenómenos.', '/btE3LrMhuFa8sfPGxHRC4hGyEjr.jpg', '/yBCekmb7vK70xUhtsRQBcTu65sB.jpg', 7.3, 'dSpQ3G08k48', array['1001']::text[], 624, null, 'segura', null),
(72277, 'movie', 'La última ola', 'La última ola', 'The Last Wave', 1977, 'Peter Weir', 'David Burton es un abogado australiano que vive tranquilamente con su hija y su esposa hasta que unos sueños premonitorios le revelan parte del conocimiento prohibido de los aborígenes. Un asesinato que debe investigar le pondrá en contacto con Chris, integrante de una tribu y conocedor de sus rituales.', '/1AkUEijkFUqDue2PqY9KKKZ9lkc.jpg', '/sPJmwvy9z5IpjdEXoYG6zxd7LO7.jpg', 6.7, 'XKvuUDBHipE', array['1001']::text[], 625, null, 'segura', null),
(703, 'movie', 'Annie Hall', 'Annie Hall', 'Annie Hall', 1977, 'Woody Allen', 'Un comediante neoyorquino repasa su relación con Annie, desde que se conocieron hasta que todo se terminó.', '/8zsJ5bgIjOBc9YGFE7jVffDom0Z.jpg', '/8n9dYsTbXTykzm2Nuy7R2ftapXQ.jpg', 7.7, '5SzZ4GWfCJg', array['1001','clasicos']::text[], 626, null, 'segura', null),
(97030, 'movie', 'Last Chants for a Slow Dance', 'Last Chants for a Slow Dance', 'Last Chants for a Slow Dance', 1977, 'Jon Jost', 'Documento desesperanzado pero ferozmente lúcido de ruptura social y contradicción. El protagonista vagabundea por el paisaje delirando, practicando sexo y matando.', '/oeUAQdO6q4C7FvwY9Uj4kiFCORh.jpg', '/xxQq78WKeRXOPgpcFYB8RDmvkaK.jpg', 6.5, null, array['1001']::text[], 628, null, 'segura', null),
(11698, 'movie', 'Stroszek', 'Stroszek', 'Stroszek', 1977, 'Werner Herzog', 'Cuando Bruno Stroszek sale de prisión, le advierten que debe dejar de beber. Con pocas habilidades y menos expectativas, sobrevive como músico callejero. Precisamente en la calle conoce a Eva, una prostituta, con la que entabla amistad. Después de ser golpeados por el chulo de ella, deciden unirse a Scheitz, un excéntrico vecino de Bruno, que ha decidido emigrar a Wisconsin, en los Estados Unidos.', '/zyfkiigNktpODEygfch0Btua5zw.jpg', '/eM3Kbzk9v03wJc0yoSC0QGEOU9C.jpg', 7.3, '4fM4fL5KK5k', array['1001']::text[], 629, null, 'segura', null),
(224, 'movie', 'El hombre de mármol', 'El hombre de mármol', 'Człowiek z marmuru', 1977, 'Andrzej Wajda', 'En 1976, una joven de Cracovia que está realizando su diplomatura en cine, investiga la vida de un obrero, llamado Birkut, quien en los 50 fue, de manera fugaz, un héroe proletario. Su objetivo es investigar como se originó esa leyenda y que efectos provocó en él.', '/iCAc0Eyxa1Gd3DqsoxfD3Pvl0re.jpg', '/36zif7dloaMlMUzrIW5xf1ymqV2.jpg', 7.1, 'yVKdrnbmQlU', array['1001']::text[], 630, null, 'segura', null),
(11009, 'movie', 'Fiebre del sábado noche', 'Fiebre del sábado noche', 'Saturday Night Fever', 1977, 'John Badham', 'En Nueva York, después de trabajar toda la semana en una tienda de pinturas de Brooklyn, Tony Manero (John Travolta) se prepara esmeradamente para disfrutar de la noche del sábado: se empapa en colonia Brut, se pone una camisa de flores ajustada, pantalones de tela de gabardina y zapatos de plataforma. En la discoteca de moda, Tony deslumbrará a todos con lo que mejor sabe hacer: bailar.', '/qgwWjfpgGvUPoWXdq5kPLii6AOr.jpg', '/iihMna17sTxP3zwlWBsKZbvDiGZ.jpg', 6.7, 'Ze5KdovxqUQ', array['1001']::text[], 631, null, 'segura', null),
(27432, 'movie', 'Killer of Sheep', 'Killer of Sheep', 'Killer of Sheep', 1978, 'Charles Burnett', 'Stan es un hombre común, un trabajador negro de un matadero de Los Ángeles, con una vida llena de dificultades y contradicciones en su ámbito social y familiar. Film grabado durante varios fines de semana, a lo largo de varios años.', '/z1CqJKI6gmdAMprD1NOYSCHVXEv.jpg', '/r763vsubExGcDJypctYuLLJmhB.jpg', 6.6, 'bORJQ8dF9tQ', array['1001']::text[], 632, null, 'segura', null),
(985, 'movie', 'La cabeza borradora', 'Cabeza borradora', 'Eraserhead', 1977, 'David Lynch', 'Henry Spencer y su novia tienen un bebé no humano, más bien un bebé reptil. Henrry pasa todo el día intentando que él bebe deje de hacer travesuras por el apartamento. Todo se tuerce aún más cuando la madre del pequeño abandona a padre e hijo por el aspecto del bebé. De todos modos, Henry es una hombre fuerte y una serie de acontecimientos inesperados harán que se esfuerce aún más, en su condición como padre soltero.', '/j8Z0M4rUmxVFtvpN7bZ2JTASrsy.jpg', '/ApB0mF2d5Oqioi3yxjuogiotSLI.jpg', 7.3, 'mvcAKdsYT58', array['1001']::text[], 634, null, 'segura', null),
(97029, 'movie', 'Ceddo', 'Ceddo', 'Ceddo', 1978, 'Ousmane Sembène', 'The Ceddo people try to preserve their traditional African culture against the onslaught of Islam, Christianity, and the slave trade. When King Demba War sides with the Muslims, the Ceddo kidnap his daughter, Princess Dior Yacine, to protest their forcible conversion to Islam.', '/6wC3jkRFbDxKRjxKUAITCkUq9Lk.jpg', '/x3JHGnvJgffqnsfR18hlSE9XX5g.jpg', 6.7, '2EPMDDZa6hQ', array['1001']::text[], 635, null, 'segura', null),
(11222, 'movie', 'El amigo americano', 'El amigo americano', 'Der amerikanische Freund', 1977, 'Wim Wenders', 'El marchante americano Tom Ripley (Hopper) intenta poner a prueba la integridad de Jonatham Zimmermann, un humilde fabricante de marcos (Bruno Ganz) que padece una enfermedad terminal. Ripley le presenta a un gánster que le ofrece mucho dinero a cambio de que trabaje para él como asesino a sueldo. En un principio rechaza la oferta, pero, al pensar en el precario futuro que espera a su mujer y a su hijo después de su muerte, acaba aceptando el trato.', '/nZzr2oJaqjVrHee4rK4HN0G6pPT.jpg', '/h59F8NcFSlucTK7fUcndD9TB9jg.jpg', 7.1, 'Pd-GKlF7eLs', array['1001']::text[], 635, null, 'segura', null),
(12262, 'movie', 'Las colinas tienen ojos', 'Las colinas tienen ojos', 'The Hills Have Eyes', 1977, 'Wes Craven', 'Camino de California, una típica família de clase media norteamericana sufre una avería en medio del desierto. A partir de ese momento, el viaje se tornará un calvario para ellos, intentando sobrevivir a una siniestra familia de caníbales... (FILMAFFINITY)', '/44S7HItmXezSUHWdlYDQhE892bV.jpg', '/e5ecjQw8AK0e924UIkMOUTxGhMj.jpg', 6.2, 'zFVpBiVymTU', array['1001']::text[], 636, null, 'segura', null),
(633, 'movie', 'Eric, oficial de la reina', 'Eric, oficial de la reina', 'Soldaat van Oranje', 1977, 'Paul Verhoeven', 'Las vidas de Erik Lanshof y cinco de sus amigos más cercanos toman rumbos diferentes cuando el ejército alemán invade los Países Bajos en 1940: lucha y resistencia, miedo y resignación, colaboración y alta traición.', '/w936SEUY7rUqB10JPRYDEqJTT9X.jpg', '/uNhZCcxkXmrmzPfOH0ZxegMs6SL.jpg', 7.1, null, array['1001']::text[], 638, null, 'segura', null),
(11906, 'movie', 'Suspiria', 'Suspiria', 'Suspiria', 1977, 'Dario Argento', 'Una joven (Jessica Harper) ingresa en una exclusiva academia de baile la misma noche en que asesinan a una de las alumnas. La subdirectora del centro es la amable Madame Blank, que brinda a la nueva alumna las comodidades y facilidades necesarias para su aprendizaje. Pero, poco a poco, una atmósfera malsana se va apoderando del lugar, y la estancia de la joven se va convirtiendo en una verdadera pesadilla.', '/ge9EiugwgIR9xorW7sOYPavju5M.jpg', '/9uXGLBPIJkPqmVwiyh3FI0iAe6n.jpg', 7.5, 'x_FfT98QJks', array['1001']::text[], 639, null, 'segura', null),
(13481, 'movie', 'Cinco venenos mortales (Wu Du)', 'Los cinco venenos', '五毒', 1978, '張徹', 'Uno de los grandes clásicos de las películas de artes marciales, que tenía como protagonistas a un grupo de personas, cada una con una habilidad y afín a un tipo de animal venenoso. Quentin Tarantino se inspiró en esta cinta para crear al escuadrón de Kill Bill. (FILMAFFINITY)', '/h1TeRBX0282Ab8LQr3xIezfkZ0N.jpg', '/5kLaqaOeo8GNrImR2zLEpreoQe3.jpg', 6.6, '3aEl8kyCs-4', array['1001']::text[], 640, null, 'segura', null),
(69069, 'movie', 'The Chant of Jimmie Blacksmith', 'The Chant of Jimmie Blacksmith', 'The Chant of Jimmie Blacksmith', 1978, 'Fred Schepisi', 'Jimmie es un joven mestizo educado por un pastor metodista que vive en constante conflicto entre dos mundos muy distintos.', '/rbyEtX16Tk58WMeii5rVEfB1OUm.jpg', '/l8iQQU2EvxTemHWGmS7mLfolNDx.jpg', 6.7, 'hXuX-UwHKwI', array['1001']::text[], 640, null, 'segura', null),
(31542, 'movie', 'El árbol de los zuecos', 'El árbol de los zuecos', 'L''albero degli zoccoli', 1978, 'Ermanno Olmi', 'Relato en tono semidocumental sobre los campesinos bergamascos (Lombardía), que llevan una vida dura y sacrificada, pero llena de gran dignidad. La ambientación es solemne y serena como la música de Bach que le sirve de fondo. Obtuvo excelentes críticas.', '/sRCw7InfepeXhEpWxENJlqd9gXY.jpg', '/viyEqVStJ9bjgyGh71TNMVqOZI.jpg', 7.6, 'v6LAOc3M6b0', array['1001']::text[], 641, null, 'segura', null),
(11778, 'movie', 'El cazador', 'El cazador', 'The Deer Hunter', 1978, 'Michael Cimino', 'Unos amigos de un pequeño pueblo industrial acuden a la llamada del ejército para combatir en la guerra del Vietnam. Michael Cimino divide el film en dos partes: en la primera nos hace partícipes de la humilde vida de los personajes, de sus sueños, juergas y esperanzas; en la segunda nos muestra con dureza los efectos de la guerra y sus penosas consecuencias.', '/qyq9qOvinL9T1QisF0EMC4c34zt.jpg', '/a5zBQfXmLk3qqRYF7AioWpiAxk2.jpg', 8.0, 'g7q1SjVdsNk', array['1001']::text[], 642, null, 'segura', null),
(621, 'movie', 'Brillantina', 'Grease', 'Grease', 1978, 'Randal Kleiser', 'Sandy y Danny han pasado un romántico y maravilloso verano juntos, pero las vacaciones se acabaron y sus caminos se separaron. Al regresar al instituto Rydell, ambos vuelven a encontrarse de manera sorpresiva, pero el problema es que la imagen y actitud de Danny no es la misma que durante el verano: ya no es el encantador y atento chico que encandiló a Sandy, sino alguien engreído e insensible que sólo quiere presumir de duro delante de sus amigos.', '/flSy0dexE82TiS6Si2FtulSHk8o.jpg', '/2SRJMIoJzABzgyGw01U6VbQbvJD.jpg', 7.4, 'THd96gHV7Tg', array['1001']::text[], 644, null, 'probable', '[{"tmdb_id": 621, "titulo": "Grease", "original": "Grease", "anio": 1978, "votos": 7891, "poster_path": "/flSy0dexE82TiS6Si2FtulSHk8o.jpg", "sim": 0.235}, {"tmdb_id": 73932, "titulo": "Brillantina Rock", "original": "Brillantina Rock", "anio": 1979, "votos": 1, "poster_path": "/qDWTDr8msCw6wKiRNiVQzOOxlbQ.jpg", "sim": 0.815}]'::jsonb),
(16642, 'movie', 'Días del cielo', 'Días del cielo', 'Days of Heaven', 1978, 'Terrence Malick', 'Bill y Abby, una joven pareja, deciden abandonar la pobreza y la dura vida que llevan en el Chicago de 1916. Los dos y Linda, la hermana de Bill, viajan hacia las grandes campos de trigo de Texas, donde encuentran trabajo como braceros en una granja. Recogida la cosecha, el joven y apuesto patrón, al que hacen creer que los tres son hermanos, les pide que se queden porque se ha enamorado de Abby.', '/t0omyXIvd4sY4sbsvOc6uqOFpwe.jpg', '/zUqIL6H6d44se9ZOsfvvCuOsbap.jpg', 7.5, '7LAqRFoT97o', array['1001']::text[], 645, null, 'segura', null),
(923, 'movie', 'Zombi', 'Zombi', 'Dawn of the Dead', 1978, 'George A. Romero', 'La epidemia que hace resucitar a los muertos convertidos en seres ávidos de carne humana se ha extendido, llegando al punto en el que varias ciudades han quedado prácticamente desiertas. Los supervivientes deben refugiarse en zonas militares ya que los zombies no dudan en acabar con sus propios familiares…', '/fT7qwRHlDfnIXK4su8DKFxbsiQk.jpg', '/9OKzKuCfcMwpHVp56pjNI7J4xXR.jpg', 7.5, 'Y_EviQj5tvA', array['1001']::text[], 646, null, 'segura', null),
(11455, 'movie', 'Como humo se va', 'Como humo se va', 'Up in Smoke', 1978, 'Lou Adler', 'Cheech y Chong debutan con esta disparatada comedia rokera, ofreciendo toda la locura, estilo de vida y números que les hicieron vender más de diez millones de discos a comienzos de los años 70. El peculiar humor repleto de marihuana de Cheech y Chong, hace que vuelen muy alto y que todo culmine en un final increíble en el Teatro Roxy de Los Ángeles, donde Cheech actúa con tutú rosa y Chong con una enorme túnica roja -información de la distribuidora-.', '/93r1M4Nf9L9vEhfnLYhWnmxDeur.jpg', '/eEG0Wq8TFg11HFuaKnetw0dQNUy.jpg', 6.6, 'zpvv81988v0', array['1001']::text[], 647, null, 'segura', null),
(11841, 'movie', 'La cámara 36 de Shaolin (Shao lin san shih liu fang)', 'Las 36 cámaras de Shaolin', '少林三十六房', 1978, '劉家良', 'Los patriotas anti-Ching, bajo las órdenes de Ho Kuang-han, se refugian en Cantón haciéndose pasar por maestros de escuela. Liu Yu-te, uno de los pupilos de Ho trabaja como mensajero y espía para los anti-Ching. Pero el general Manchurio Tien Ta descubre a los anti-Ching y ordena matar a Ho y al padre de Liu. Liu escapa al templo de Shaolin con la esperanza de aprender artes marciales y vengar la muerte de su padre. Liu es aceptado como alumno y es llamado San Te. Su progreso en las artes marciales es espectacular y por fin, con el consentimiento de los monjes, deja el templo para vengar a su padre y reclutar nuevos alumnos para Shaolin.', '/zt0315MHhD1YqNG6N6QyZpOeqvE.jpg', '/Hn10dZqkUfr18pQZYMKzCFPPCP.jpg', 7.5, 'dx43uPkFwTY', array['1001']::text[], 647, null, 'probable', '[{"tmdb_id": 11841, "titulo": "Las 36 cámaras de Shaolin", "original": "少林三十六房", "anio": 1978, "votos": 530, "poster_path": "/zt0315MHhD1YqNG6N6QyZpOeqvE.jpg", "sim": 0.829}, {"tmdb_id": 48301, "titulo": "Retorno a Shaolin", "original": "少林搭棚大師", "anio": 1980, "votos": 253, "poster_path": "/dg0bCE0a4p9IUGQLB1AMnd7WACq.jpg", "sim": 0.486}, {"tmdb_id": 40829, "titulo": "La cámara de los 36 hombres de madera", "original": "少林木人巷", "anio": 1976, "votos": 149, "poster_path": "/7IcQJ4L12WIyUlDKzjgBWtjBId9.jpg", "sim": 0.519}]'::jsonb),
(948, 'movie', 'La noche de Halloween', 'La noche de Halloween', 'Halloween', 1978, 'John Carpenter', 'Durante la noche de Halloween, Michael, un niño de seis años, asesina a su familia con un cuchillo de cocina. Es internado en un psiquiátrico del que huye quince años más tarde, precisamente la víspera de Halloween. El psicópata vuelve a su pueblo y comete una serie de asesinatos. Mientras, uno de los médicos del psiquiátrico le sigue la pista.', '/6bsDpDL312h6vEGPOPWoweaZWUG.jpg', '/sHI9xlFRWCJ38AIIfOqnGjuEvXz.jpg', 7.6, 'NT0loXUv-ks', array['1001']::text[], 648, null, 'segura', null),
(661, 'movie', 'El matrimonio de María Braun', 'El matrimonio de Maria Braun', 'Die Ehe der Maria Braun', 1979, 'Rainer Werner Fassbinder', 'Maria y Hermann Braun se casan durante un bombardeo, poco antes de que él sea enviado al frente ruso. Al final de la guerra, Hermann figura en las listas de desaparecidos. En la ciudad, entre las ruinas, reina el mercado negro y la prostitución. También Maria, para poder sobrevivir, debe prostituirse. Así se hace amante de Bill, un soldado negro americano, del que queda embarazada; pero su marido reaparece.', '/8Os98kJkiK4S7InGbXohih2qm2p.jpg', '/ejp6CZQ64mEvewfit2fSIpOYxGR.jpg', 7.4, 'pQGznARA69s', array['1001']::text[], 650, null, 'segura', null),
(33250, 'movie', 'Como en la vida real', 'Como en la vida real', 'Real Life', 1979, 'Albert Brooks', 'Albert Brooks se interpreta a sí mismo como un egocéntrico humorista que ha decidido hacer un documental. Basándose en las clásicas series documentales en las que se filma a una familia típica durante un día, Brooks se decide por la familia Yeager.', '/ihN6hpMI8IUGgUvivU5HUT2M16c.jpg', '/7kPoeekpoMzZch04zdGAKX1HOCa.jpg', 6.6, 'DOAihCRr1y4', array['1001']::text[], 651, null, 'segura', null),
(16659, 'movie', 'My Brilliant Career', 'Mi brillante carrera', 'My Brilliant Career', 1979, 'Gillian Armstrong', 'Sybylla, una chica de Australia a finales de siglo XIX, tiene la oportunidad de casarse con un joven hombre, Harry, un pretendiente rico y amigo de la infancia, pero rechaza el fin de mantener su independencia. Después de regresar a casa, de nuevo rechaza otra propuesta de Harry así ella podrá escribir su novela, "My Brilliant Career".', '/s89ZolmE0tD5stOJhy6Jh4V3txZ.jpg', '/kewdBa1MYOZwUhcbOHxxXLIquBI.jpg', 6.2, 'hKA0huXBs80', array['1001']::text[], 651, null, 'segura', null),
(1398, 'movie', 'Stalker', 'Stalker', 'Сталкер', 1979, 'Andréi Tarkovski', 'En un lugar de Rusia llamado "La Zona", hace algunos años se estrelló un meteorito. A pesar de que el acceso a este lugar está prohibido, los "stalkers" se dedican a guiar a quienes se atreven a aventurarse en este inquietante paraje.', '/c6lF6PYnq6rtYTUM8me0D0DCpwa.jpg', '/6yrbWzzrPp7pwz6zHdifspJk8t3.jpg', 8.1, 'JCuwthnCRpg', array['1001']::text[], 652, null, 'segura', null),
(348, 'movie', 'Alien, el octavo pasajero', 'Alien: El octavo pasajero', 'Alien', 1979, 'Ridley Scott', 'De regreso a la Tierra, la nave de carga Nostromo interrumpe su viaje y despierta a sus siete tripulantes. El ordenador central, MADRE, ha detectado la misteriosa transmisión de una forma de vida desconocida, procedente de un planeta cercano aparentemente deshabitado. La nave se dirige entonces al extraño planeta para investigar el origen de la comunicación.', '/pZ9cAe5FxexJjpCaeiETbXzz3Fs.jpg', '/AmR3JG1VQVxU8TfAvljUhfSFUOx.jpg', 8.2, 'D3oC17nILkw', array['1001']::text[], 653, null, 'segura', null),
(20283, 'movie', 'El relevo', 'El relevo', 'Breaking Away', 1979, 'Peter Yates', 'Cyril, Moocher, Mike y Dave son cuatro amigos de Bloomington, una pequeña ciudad de Indiana, que se encuentran en la encrucijada de sus vidas, esa etapa entre la adolescencia y la edad adulta en la que las dudas sobre el futuro no dejan pensar. La obsesión de Dave son las bicicletas, y esa afición le llevará a participar en una carrera que cambiará su vida y la de sus amigos.', '/khS27PoFvgh0ZtFfNeV4DnZBd27.jpg', '/yNjrT8bsr5WR9bmRjLsIwIoZtFR.jpg', 7.2, 'ijT_4EmWETk', array['1001']::text[], 654, null, 'segura', null),
(659, 'movie', 'El tambor de hojalata', 'El tambor de hojalata', 'Die Blechtrommel', 1979, 'Volker Schlöndorff', 'El día de su tercer cumpleaños es una fecha determinante en la vida de Oskar. No sólo es el día en que toma la decisión de dejar de crecer, sino que recibe su primer tambor de hojalata, objeto que habrá de convertirse en compañero inseparable para el resto de sus días... Basada en la más famosa novela del escritor y premio Nobel de literatura Günter Grass.', '/5IAOJ7EQ6JlZODtJvdbpFqKCDj2.jpg', '/xemaeNc6pssgSKcpLhpEfh3AOlH.jpg', 7.0, 'NTKLqhT-tTo', array['1001']::text[], 654, null, 'segura', null),
(16858, 'movie', 'Empieza el espectáculo', 'All That Jazz (Empieza el espectáculo)', 'All That Jazz', 1979, 'Bob Fosse', 'Joe Gideon, un famoso coreógrafo y director de Broadway y Hollywood, vive una vida marcada por los excesos de todas clases. Su corazón le da un primer aviso en forma de infarto y los doctores le previenen de que si no cambia de actitud su cuerpo no aguantará más. Pero Joe solo sabe vivir de una manera.', '/culCEdj4srLljefgn4XKd6k3C5t.jpg', '/wQVkhFgKiej4XdEnTsrXU3isoK0.jpg', 7.5, '8_aIhkKlrwk', array['1001']::text[], 655, null, 'segura', null),
(10322, 'movie', 'Bienvenido, Mr. Chance', 'Bienvenido Mr. Chance', 'Being There', 1979, 'Hal Ashby', 'Chance es un hombre peculiar. Su vida se reduce a cuidar el jardín de la mansión de un hombre adinerado y a ver la televisión el resto del día. Pero, cuando el dueño de la casa muere y Chance es despedido, no está preparado para hacer frente al mundo exterior. Tiene, sin embargo, la suerte de conocer a Eve, una buena mujer que lo acoge en su casa. Lo paradójico es que, poco a poco, este hombre analfabeto conseguirá engañar a muchos haciéndoles creer que es un gran político.', '/vjVUeQluMfAwbP5MFwDVULTKmu5.jpg', '/hddFwpiSpmAsVtCvKuKEUEmXAlr.jpg', 7.6, 'oOOghKacg40', array['1001']::text[], 656, null, 'segura', null),
(12102, 'movie', 'Kramer contra Kramer', 'Kramer contra Kramer', 'Kramer vs. Kramer', 1979, 'Robert Benton', 'El ejecutivo publicitario Ted Kramer consigue la mejor cuenta de la agencia el mismo día en que su mujer decide divorciarse, dejándole solo con su hijo de 7 años. Comienza así una dura etapa en la que tendrá que ejercer de padre soltero de un niño que echa de menos a su madre y, al mismo tiempo, no descuidar su carrera profesional. Cuando tras un tiempo parece que la relación con su hijo va mejorando, la madre aparece para pedir la custodia del pequeño.', '/btdZ6vSOqQ3zI3ftEm2QTF9yiId.jpg', '/9pUh1fC8TqVtYPeKpdfNyVK0qnn.jpg', 7.6, 'TuDnCnr504A', array['1001']::text[], 657, null, 'segura', null),
(583, 'movie', 'La vida de Brian', 'La vida de Brian', 'Life of Brian', 1979, 'Terry Jones', 'Delirante y divertidísima comedia que relata, a golpe de carcajada, la vida de un desastre de hombre, contemporáneo de Jesucristo, que es confundido por el pueblo con un mesías. Que nadie se confunda: "Life of Brian" no es una amalgama de escenas absurdas que hacen reír, es una brillante sátira que desborda con un humor maravillosamente inteligente. Obra capital de los geniales Monty Python, su gozosa visión está llena de memorables gags que la encumbran como una de las mejores parodias de la historia del cine.', '/b4JaQ2ZjPxblj3E3S9ga5ykTita.jpg', '/lOrM3OQhHlzEkpF7Ih3GghecrA8.jpg', 7.8, '1NPlL1zLn00', array['1001']::text[], 657, null, 'segura', null),
(28, 'movie', 'Apocalypse Now', 'Apocalypse Now', 'Apocalypse Now', 1979, 'Francis Ford Coppola', 'Durante la guerra de Vietnam, un capitán remonta un río hacia Camboya con la misión de encontrar y eliminar a un coronel que se volvió loco.', '/zJXRrkJTlcb5x87v4VWN1zZX0Xk.jpg', '/49fzLedFVKgGgFChLMuulDJBY1c.jpg', 8.3, 'h5iZf5kv354', array['1001','clasicos']::text[], 658, null, 'segura', null),
(11176, 'movie', 'The Muppet Movie', 'La película de los Teleñecos', 'The Muppet Movie', 1979, 'James Frawley', 'Después de un accidental encuentro con un cazatalentos, la Rana Gustavo (llamada René en Latinoamérica) se dirige a Hollywood para convertirse en una estrella del espectáculo. A lo largo del camino, se unen a él el fabuloso Fozzie, el gran Gonzo y la deslumbrante cerdita Peggy con la ilusión de convertirse también en grandes estrellas del cine. Pero sus esperanzas se desvanecen cuando Gustavo cae en las garras de un magnate de la comida rápida que pretende promocionar su negocio de ancas de ranas fritas...', '/xNyMdlX8NRaDn3KalO2wu0EHV6s.jpg', '/9mbXZSLINbwNQateHLGRhtaZzZB.jpg', 7.2, 'qDfXXaqfc2k', array['1001']::text[], 660, null, 'segura', null),
(6471, 'movie', 'Un loco anda suelto', 'Un loco anda suelto', 'The Jerk', 1979, 'Carl Reiner', 'Navin Johnson es un chico ingenuo que, al cumplir 18 años, decide recorrer mundo y se instala en Saint Louis. Pero todo el mundo se aprovecha de él, hasta que un invento le hace ganar una fortuna', '/an6kcydnA2rQgVvmd4cXjPdzPxe.jpg', '/llVPUs3j9RywSMstGRepSeS8vSL.jpg', 6.9, 'lduFFNqBFPs', array['1001']::text[], 660, null, 'segura', null),
(696, 'movie', 'Manhattan', 'Manhattan', 'Manhattan', 1979, 'Woody Allen', 'Podría decirse que Isaac Davis, un neoyorquino de mediana edad, lo tiene todo, si por todo entendemos un trabajo que odia, una novia de 17 años a la que no ama y una ex-esposa lesbiana a la que desearía estrangular, porque está escribiendo un libro en el que cuenta las intimidades de su matrimonio. Pero su vida cambia cuando conoce a Mary, la sexy e inteligente amante de su mejor amigo, y se enamora perdidamente de ella. Dejar a su novia, acostarse con Mary y abandonar su trabajo no es más que el comienzo de la búsqueda de sí mismo.', '/k4eT3EvfxW1L9Wmt04UqJqCvCR6.jpg', '/adnSTomHU9YyqV2lx38CgM0UxLS.jpg', 7.7, 'J5c93q3gU3w', array['1001']::text[], 661, null, 'segura', null),
(9659, 'movie', 'Mad Max: Salvajes de autopista', 'Mad Max. Salvajes de la autopista', 'Mad Max', 1979, 'George Miller', 'En las autopistas desiertas de una Australia desconocida, tiene lugar una guerra sin merced entre motoristas forajidos y policías Interceptor, que intentan triunfar sobre la gentuza al volante de coches con motores trucados. En un mundo en plena decadencia, la moral se difuminará en el escenario post apocalíptico donde lo único que tiene valor es el bien más preciado: la gasolina. La depravación, crueldad y salvajismo reinan en las bandas que no dudarán en perseguir y acabar con cualquiera que se ponga entre ellos y su ansia destruir y ser los amos de la carretera. Max se cruzará en su camino y lo que empieza como un acto de justicia no tardará en tornarse una lucha personal para acabar con ellos.', '/vWa1DEwV5RbAOiuAm0WNXD3Aydw.jpg', '/mWQg2INejtX1PCWRAN4vseadA6H.jpg', 6.7, 'caHnaRq8Qlg', array['1001']::text[], 662, null, 'segura', null),
(6404, 'movie', 'Nosferatu', 'Nosferatu. Vampiro de la noche', 'Nosferatu – Phantom der Nacht', 1979, 'Werner Herzog', 'Jonathan Harker viaja desde Wismar a Transilvania, al castillo del legendario conde Drácula, con el fin de venderle una mansión en su ciudad. Atraído por una fotografía de Lucy, la mujer de Harker, Nosferatu parte inmediatamente hacia Wismar, llevando con él muerte y el horror.', '/ej8BnlGwoiWmugLLsNrRUdjCm4t.jpg', '/uHudMff1vp2GDXqHD8QOA78QpNW.jpg', 7.3, 'fnJqLNGBAPc', array['1001']::text[], 663, null, 'probable', '[{"tmdb_id": 6404, "titulo": "Nosferatu the Vampyre", "original": "Nosferatu – Phantom der Nacht", "anio": 1979, "votos": 1148, "poster_path": "/jHKzGYwf7P34vz8MhJBTN6cnaYD.jpg", "sim": 0.6}, {"tmdb_id": 373210, "titulo": "The Making of Nosferatu", "original": "The Making of Nosferatu", "anio": 1979, "votos": 3, "poster_path": "/4ZlBAf3x4U15SUmcuW3OIJpQ7ox.jpg", "sim": 0.643}, {"tmdb_id": 410086, "titulo": "MM 51 Nosferatu", "original": "MM 51 – Ein Stück Filmmusik für Klavier und die Projektion einer Collage von Mauricio Kagel aus F. W. Murnaus Nosferatu", "anio": 1981, "votos": 3, "poster_path": "/5mBT0Te4zwxS1Qj5zz57yAIG4QX.jpg", "sim": 0.75}]'::jsonb),
(16619, 'movie', 'Gente corriente', 'Gente corriente', 'Ordinary People', 1980, 'Robert Redford', 'Conrad acaba de salir del hospital después de haber intentado suicidarse a raíz de la muerte de su hermano en un accidente. Mantiene una relación muy tensa con su madre y vive atormentado por sentimientos de culpa. Aunque visita todas las semanas a un psiquiatra, no se siente a gusto hasta que conoce a una compañera del coro y empiezan a salir juntos.', '/vI626IhqpcwiASA7F5boT0mhxje.jpg', '/81LV5HJ9nUXGCMhrJpFNjwvbEZl.jpg', 7.5, 'vtpsjMEGbaE', array['1001']::text[], 664, null, 'segura', null),
(23954, 'movie', 'Atlantic City', 'Atlantic City', 'Atlantic City', 1980, 'Louis Malle', 'A Lou Pascal, un viejo gángster que consigue algún dinero con las apuestas, lo mantiene en realidad la viuda de su ex jefe. En el mismo edificio que él vive Sally, una atractiva mujer cuyo cuerpo lo tiene obsesionado.', '/j9SSSI89ysSJ9JZ0iHIbLRzU2Ud.jpg', '/27Y0dGVBW0ZowwRjfa6nHbfP2aR.jpg', 6.8, 'fwDjsStvBbA', array['1001']::text[], 665, null, 'segura', null),
(1716, 'movie', 'El último metro', 'El último metro', 'Le Dernier Métro', 1980, 'François Truffaut', 'Durante la ocupación de París por las tropas alemanas, un grupo de actores trata de sacar adelante una obra de teatro. Nadie sospecha que, en el sótano del edificio, se oculta el director del grupo, un hombre de origen judío que desde su escondrijo dirige la obra a través de las indicaciones que da a su mujer, que es la protagonista.', '/yw44YF67vCgacmz12hAnaQgUZbZ.jpg', '/u97pGlftKRNbUn0jOoQgIobSBvb.jpg', 7.2, '0N2BfFD1QTo', array['1001']::text[], 665, null, 'segura', null),
(694, 'movie', 'El resplandor', 'El resplandor', 'The Shining', 1980, 'Stanley Kubrick', 'Jack Torrance se traslada, junto a su mujer y a su hijo, al impresionante hotel Overlook, en Colorado, para encargarse del mantenimiento del mismo durante la temporada invernal, en la que permanece cerrado y aislado por la nieve. Su idea es escribir su novela al tiempo que cuida de las instalaciones durante esos largos y solitarios meses de invierno, pero desde su llegada al hotel, Jack comienza a padecer inquietantes transtornos de personalidad, al mismo tiempo que en el lugar comienzan a suceder diversos fenómenos paranormales.', '/mm003Mj2e9kJRsrxiVdPn2BSBPh.jpg', '/AdKA2F1SzYPhSZdEbjH1Zh75UVQ.jpg', 8.2, 'A3q03BBwMp4', array['1001']::text[], 666, null, 'segura', null),
(1891, 'movie', 'El imperio contraataca', 'El imperio contraataca', 'The Empire Strikes Back', 1980, 'Irvin Kershner', 'Tras un ataque sorpresa de las tropas imperiales a las bases camufladas de la alianza rebelde, Luke Skywalker, en compañía de R2D2, parte hacia el planeta Dagobah en busca de Yoda, el último maestro Jedi, para que le enseñe los secretos de la Fuerza. Mientras, Han Solo, la princesa Leia, Chewbacca, y C3PO esquivan a las fuerzas imperiales y piden refugio al antiguo propietario del Halcón Milenario, Lando Calrissian, en la ciudad minera de Bespin, donde les prepara una trampa urdida por Darth Vader.', '/eU7KcNAOeZj9PBIcGUMSsuJz8qj.jpg', '/k9pshruhCpJAdH9RaGJO6jaWQ4X.jpg', 8.4, 'xr3hPFJAHO4', array['1001']::text[], 668, null, 'segura', null),
(1955, 'movie', 'El hombre elefante', 'El hombre elefante', 'The Elephant Man', 1980, 'David Lynch', 'A finales del siglo XIX, el doctor Frederick Treves descubre en un circo a un hombre llamado John Merrick. Se trata de un ciudadano británico con la cabeza monstruosamente deformada, que vive en una situación de constante humillación y sufrimiento al ser exhibido diariamente como una atracción de feria.', '/8oif8Zz7Nlf0vMVIiqX1rxDLoXl.jpg', '/6huSptAsqYg3wbsi1jbMognSgmp.jpg', 8.0, 'fuN3-e-8P5k', array['1001']::text[], 669, null, 'segura', null),
(39415, 'movie', 'Loulou', 'Loulou', 'Loulou', 1980, 'Maurice Pialat', 'Nelly tiene una aventura con Loulou, un pequeño delincuente cuya vulgaridad y atractivo sexual la seducen. Sin romper con su marido, Nelly planea vivir con Loulou, quien le promete trabajar por el niño que están esperando.', '/cuFnjQgk5CPAf0jLy5RHVQW1fqC.jpg', '/A89qKnhI2UiqdnmbsCd6v1ussvQ.jpg', 6.2, '1VbQhHfBBBQ', array['1001']::text[], 670, null, 'segura', null),
(16121, 'movie', 'Uno rojo: división de choque', 'Uno Rojo, división de choque', 'The Big Red One', 1980, 'Samuel Fuller', 'En el transcurso de la Segunda Guerra Mundial, cinco soldados americanos al mando de un veterano sargento protagonizan dramáticas batallas, en las que sobrevivir es lo más importante, y terribles experiencias que les marcarán profundamente.', '/phEqkt30r5IagJsxLUMlbioZNqu.jpg', '/mpRSzmUX0Lsimgg0M8hZRS2xrDC.jpg', 6.7, 'D911lxh4tm0', array['1001']::text[], 670, null, 'segura', null),
(813, 'movie', 'Aterriza como puedas', 'Aterriza como puedas', 'Airplane!', 1980, 'Jim Abrahams, Jerry Zucker, David Zucker', 'El vuelo 209 de la Trans American sale de Los Ángeles con destino a Chicago. Entre el pasaje se encuentran una serie de curiosos personajes. Entre ellos, un ex-piloto de combate que, en pleno vuelo, se verá obligado a hacerse con el mando del avión comercial, tras quedar los pilotos indispuestos por una comida en mal estado.', '/5ZT6eyz8U3ZeefZh8CqqlOAv2VY.jpg', '/wQyvrsNSTzFVEGgarZbFkFyIciy.jpg', 7.3, 'HMnVs287AJ4', array['1001']::text[], 671, null, 'segura', null),
(1578, 'movie', 'Toro salvaje', 'Toro salvaje', 'Raging Bull', 1980, 'Martin Scorsese', 'Ascenso y caída del boxeador Jake LaMotta, cuya violencia arriba del ring es igual a la que destruye su vida afuera.', '/uTrGbVJMcINTZaMW3J6PJ7kZlV6.jpg', '/tvNuhRlpRozDgsX1zR9gQ2aHv1X.jpg', 7.9, 'G5RHRg6zEhY', array['1001','clasicos']::text[], 672, null, 'segura', null),
(85, 'movie', 'En busca del arca perdida', 'En busca del arca perdida', 'Raiders of the Lost Ark', 1981, 'Steven Spielberg', 'Año 1936, Indiana Jones es un profesor de arqueología, dispuesto a correr peligrosas aventuras con tal de conseguir valiosas reliquias históricas. Después de una infructuosa misión en Sudamérica, el gobierno estadounidense le encarga la búsqueda del Arca de la Alianza, donde se conservan las Tablas de la Ley que Dios entregó a Moisés. Según la leyenda, quien las posea tendrá un poder absoluto, razón por la cual también la buscan los nazis.', '/tECLVwLCMexSkls33RTCwedRZ6d.jpg', '/zPACwR32amTNvzId9qyapCWXYDJ.jpg', 7.9, 'ep1d88NWhVY', array['1001']::text[], 674, null, 'segura', null),
(387, 'movie', 'El submarino', 'El submarino (Das Boot)', 'Das Boot', 1981, 'Wolfgang Petersen', 'Un submarino alemán de la Segunda Guerra Mundial es el escenario en el que un grupo de jóvenes soldados, dispuesto a defender su patria, tendrá que someterse a una dura convivencia, tras descubrir que han sido enviados a realizar una misión probablemente suicida.', '/qXeULeu5uHHXYHRsbITzuLN51EB.jpg', '/zzzhbZnSPMOON9uGt0LsdUJWYoC.jpg', 8.1, 'r37MmBuFoc0', array['1001']::text[], 675, null, 'segura', null),
(9443, 'movie', 'Carros de fuego', 'Carros de fuego', 'Chariots of Fire', 1981, 'Hugh Hudson', 'En Gran Bretaña, 1920. Harold Abrahams y Eric Lidell estaban hechos para correr. No sólo una razón les llevaba a correr más rápido que ningún otro hombre, sus motivos eran tan diferentes como sus pasados. Cada uno tenía su propio Dios, sus propias creencias y su propio empuje hacia el triunfo. Dos jóvenes corredores de diferentes clases sociales que se entrenan con un mismo objetivo: competir en las Olimpiadas de París de 1924.', '/pXgqJhGWRJJCzVfnsSRCDTvxyjL.jpg', '/nEeq7iQDbsj4qRt9E11PvQOWKvQ.jpg', 6.8, 'AawHrbzbuMI', array['1001']::text[], 676, null, 'segura', null),
(11646, 'movie', 'Gallípoli', 'Gallipoli', 'Gallipoli', 1981, 'Peter Weir', 'Primera Guerra Mundial, 1915. Reza la leyenda del filme: "De un lugar del que nunca has oído hablar llega una historia que nunca olvidarás". Dos amigos australianos, ambos atletas, deciden alistarse para ir a la guerra y les toca luchar contra los turcos en la batalla de Gallipoli.', '/2zHdGHtgJqAtlAMhrYUwgPlId6W.jpg', '/cQtEnazTk07zcfcf2MYLCiPRfY.jpg', 7.1, 'CT1JHKpSHXA', array['1001']::text[], 676, null, 'segura', null),
(14412, 'movie', 'Fuego en el cuerpo', 'Fuego en el cuerpo', 'Body Heat', 1981, 'Lawrence Kasdan', 'Ned Racine (William Hurt), un joven abogado de Florida, lleva una vida normal hasta que conoce a Matty Walker (Kathleen Turner), una tentadora y sensual mujer casada con un rico hombre de negocios (Richard Crenna). Ned pronto se da cuenta de que Matty es la clase de mujer por la que un hombre sería capaz de matar.', '/41VIK2UlxXNR28PLVRR1MAWhQ2k.jpg', '/2LZCclEayw1Un46yAmmM0SXAYJt.jpg', 7.0, 'UWnHLgmcwAw', array['1001']::text[], 677, null, 'segura', null),
(18254, 'movie', 'Rojos', 'Rojos', 'Reds', 1981, 'Warren Beatty', 'John Reed (1887-1920) es un legendario periodista y revolucionario americano, pionero del socialismo en Estados Unidos. Corresponsal en la revolución mexicana y la 1ª guerra mundial, es famoso por ser testigo directo de la Revolución de Octubre, que plasmó en su libro ''Diez días que estremecieron al mundo''. Convencido por aquellos acontecimientos, luchó por extender el bolchevismo en EEUU, y trabajó para la Komintern en la Rusia soviética.  En ''Rojos'', Warren Beatty escribe, produce, dirige y protagoniza un drama épico sobre su vida y la de su compañera —también escritora— Louise Bryant (Diane Keaton). Con su romance como excusa, la película es un maravilloso retrato de la América de 1912-19, desde la vida bohemia de los artistas del Greenwich Village de Nueva York, al incipiente sindicalismo revolucionario de la Industrial Workers of the World, el movimiento antibélico o la fundación del comunismo americano, salpicado de un toque documental con entrevistas a testigos de aquella era.', '/kZsJWIKnvqsRkk9kDuj3nKVFmnx.jpg', '/cDdB8JBflT4vBYlftoopSdTf4Wz.jpg', 6.9, 'MLAnTuCs6_g', array['1001']::text[], 678, null, 'segura', null),
(42150, 'movie', 'Tres hermanos', 'Tres hermanos', 'Tre fratelli', 1981, 'Francesco Rosi', 'Una visión de los aspectos más controvertidos de la Italia de los años 80 a través de la historia de tres hermanos y su familia. En una granja del sur de Italia, una anciana muere y su viudo llama a los hijos, que acuden a pasar el duelo a la casa familiar. Son tres hermanos de distinta suerte y problemas. Raffaele Giurana es un juez de Roma que encara un proceso con ramificaciones políticas y que teme ser asesinado. Rocco, muy religioso e idealista, trabaja como consejero en un reformatorio de menores de Nápoles. Nicola es un empleado de una fábrica de Turín, donde está inmerso en un conflicto laboral. Mientras el marido de la fallecida y su nieta viven con aflicción la desaparición del ser querido, los tres hermanos no pueden olvidar sus inquietudes. Raffaele imagina su propia muerte, Rocco sueña con conseguir liberar a los jóvenes a los que asiste de sus problemas con las drogas y el crimen. Nicola se refugia en los recuerdos de su mujer.', '/va71wD7MyY3smHLXgvqbOAzHZDy.jpg', '/yWdlOunLPsqACjLBrZll8fpX2Ok.jpg', 6.3, 'BM6tRuxzJKA', array['1001']::text[], 679, null, 'segura', null),
(814, 'movie', 'Un hombre lobo americano en Londres', 'Un hombre lobo americano en Londres', 'An American Werewolf in London', 1981, 'John Landis', 'Dos mochileros norteamericanos, David Kessler y Jack están de viaje por Europa. Caminando por una zona rural de Inglaterra, la población local los mira mal cuando entran en un bar. Al salir, reciben todo tipo de extrañas advertencias: ''Manténganse en la carretera y aléjense de los pantanos'' y ''Cuidado con la luna''. Aun así, los jóvenes se adentran en la oscuridad y no se dan cuenta que están siendo seguidos por una terrible criatura.', '/9sAJdIZgFZEqz3Kyg97RA97CP9n.jpg', '/4js6VLf6qHWUbW42BpXiQKPBP7t.jpg', 7.4, 'EM9quAtFUH4', array['1001']::text[], 679, null, 'segura', null),
(225, 'movie', 'El hombre de hierro', 'El hombre de hierro', 'Człowiek z żelaza', 1981, 'Andrzej Wajda', 'Narra las jornadas revolucionarias en los astilleros navales de Gdansk (o Danzig) protagonizadas por los obreros del sindicato Solidaridad, en el verano de 1980. Ese mismo año, un periodista radiofónico, más amigo del régimen comunista que de la verdad, debe cumplir una misión de difamación contra un destacado militante del sindicato Solidaridad, que resulta ser el hijo del héroe de "El hombre de mármol" (1977).', '/rFyIsv9cJ6mNYZEoS6QqY2I2cJr.jpg', '/row4sMw5mVzKCWRbyrAQ39zvyLX.jpg', 7.0, 'CGWQfuhefI8', array['1001']::text[], 680, null, 'segura', null),
(13342, 'movie', 'Aquel excitante curso', 'Aquel excitante curso', 'Fast Times at Ridgemont High', 1982, 'Amy Heckerling', 'Un escritor decide matricularse en un instituto con la intención de documentarse para escribir su próxima novela que estará protagonizada por jóvenes estudiantes. Lo primero que comprobará es que el interés de los adolescentes se centra más en ligar que en estudiar. Basada en la experiencia del famoso director Cameron Crowe.', '/AfQAYVcjiGd6XKzMyGHGwCfbhPM.jpg', '/mHbnNX6jxpndW03yGXslHcBOaZv.jpg', 6.8, 'Of5jkwF3J7A', array['1001']::text[], 681, null, 'segura', null),
(97032, 'movie', 'Zu früh, zu spät', 'Demasiado temprano, demasiado tarde', 'Trop tôt, trop tard', 1982, 'Danièle Huillet, Jean-Marie Straub', 'Película dividida en dos partes; la primera en Francia, la segunda en Egipto. Sobre las imágenes de la Bretaña, un texto de Engels es leído, describiendo la miseria de los campesinos en 1789. En Egipto, es un texto del historiador Mahmoud Hussein sobre la lucha de clases en ese país, desde Bonaparte hasta el reino de Sadate.', '/4u0WFuYUagULcnTp11JDlh9jjLa.jpg', '/myaJXaFqaQQ9KVcSbiuTaf1KhJN.jpg', 6.6, '7lyWAQPzczg', array['1001']::text[], 681, null, 'probable', '[{"tmdb_id": 97032, "titulo": "Too Early / Too Late", "original": "Trop tôt, trop tard", "anio": 1982, "votos": 32, "poster_path": "/svhscgSLqNQtFFZoRlS2KiAoVtG.jpg", "sim": 0.364}]'::jsonb),
(601, 'movie', 'E.T. el extraterrestre', 'E.T., el extraterrestre', 'E.T. the Extra-Terrestrial', 1982, 'Steven Spielberg', 'Un pequeño ser de otro planeta se queda abandonado en la Tierra cuando su nave se marcha olvidándose de él. Tiene miedo. Está completamente solo, pero se hará amigo de un niño, que lo esconde en su casa. El niño y sus hermanos intentarán encontrar la forma de que el pequeño extraterrestre regrese a su planeta antes de que los científicos y la policía lo encuentren.', '/ojvKem8WUzRK5PLvO7wTuAFinnz.jpg', '/mXLVA0YL6tcXi6SJSuAh9ONXFj5.jpg', 7.5, 'jzC0c-GWeDQ', array['1001']::text[], 682, null, 'segura', null),
(1091, 'movie', 'La cosa', 'La cosa (El enigma de otro mundo)', 'The Thing', 1982, 'John Carpenter', 'En una estación experimental de la Antártida, un equipo de investigadores descubre a un ente extraño venido del espacio, que según todos los indicios ha permanecido enterrado en la nieve durante más de 100.000 años. Al descongelarse, experimenta una metamorfosis sorprendente...', '/5hkM27bPdkgQli5g5zR5pp9bkNZ.jpg', '/r9leYNa8nTRCceZrZhP1DXkgKVb.jpg', 8.1, 'ySvzHdtCiWE', array['1001']::text[], 683, null, 'probable', '[{"tmdb_id": 1091, "titulo": "La cosa (El enigma de otro mundo)", "original": "The Thing", "anio": 1982, "votos": 8399, "poster_path": "/5hkM27bPdkgQli5g5zR5pp9bkNZ.jpg", "sim": 0.25}, {"tmdb_id": 18502, "titulo": "In-natural (The Stuff)", "original": "The Stuff", "anio": 1985, "votos": 564, "poster_path": "/qxDEPz0JPGK6VS6JeLpNCob9vUn.jpg", "sim": 0.222}, {"tmdb_id": 17918, "titulo": "La cosa del pantano", "original": "Swamp Thing", "anio": 1982, "votos": 501, "poster_path": "/jc7dFysVuObddmvuXdovMeAptRf.jpg", "sim": 0.4}, {"tmdb_id": 30363, "titulo": "El estado de las cosas", "original": "Der Stand der Dinge", "anio": 1982, "votos": 85, "poster_path": "/vB64asO8cEursipyjzCCBWTxEao.jpg", "sim": 0.348}]'::jsonb),
(609, 'movie', 'Poltergeist', 'Poltergeist. Fenómenos extraños', 'Poltergeist', 1982, 'Tobe Hooper', 'Una familia americana de clase media se traslada a vivir e una nueva casa en un aparentemente idílico barrio, pero dentro de la casa comienzan a suceder cosas extrañas, fenómenos paranormales para los que no hay explicación posible.', '/b6JcwPnultjlXSVDGJhtPSAZSEY.jpg', '/bvkPno6U02lLyvPWCnmibq4eIaN.jpg', 7.2, 'RtKn4rHAMAg', array['1001']::text[], 683, null, 'segura', null),
(78, 'movie', 'Blade Runner', 'Blade Runner', 'Blade Runner', 1982, 'Ridley Scott', 'En Los Ángeles de 2019, un policía especializado debe cazar a cuatro replicantes, androides casi humanos, que volvieron a la Tierra.', '/pBA2J6iQMiP5Zd4ewMKdOWfq1HV.jpg', '/2spEHYDcyE9r9mS7AFEscfKVDzO.jpg', 7.9, '4USFH9n8tNk', array['1001','clasicos']::text[], 684, null, 'segura', null),
(764, 'movie', 'Posesión infernal', 'Posesión infernal', 'The Evil Dead', 1983, 'Sam Raimi', 'Cinco chicos van a pasar el fin de semana a una cabaña perdida en un espeso bosque en las montañas de Tennessee. Una vez instalados, y cuando se encuentran cenando, la trampilla que da acceso al sótano se abre de golpe. Extrañados, deciden bajar a investigar. Allí encuentran un magnetófono, un extraño cuchillo ritual y un libro antiquísimo.', '/vgQDogdqPrSk2zRdy2JESq2LGvy.jpg', '/onq6lsJLX8ay5iwxEbKX3qJKeO9.jpg', 7.3, '0cQmKgV0cug', array['1001']::text[], 686, null, 'segura', null),
(9576, 'movie', 'Tootsie', 'Tootsie', 'Tootsie', 1982, 'Sydney Pollack', 'Michael Dorsey es un actor neoyorkino sin éxito. Además, en los círculos artísticos tiene fama de conflictivo. Como su mala racha no se acaba, un día toma una importante decisión: hacerse pasar por una mujer para encontrar trabajo. Consigue un papel, pero su nueva identidad le traerá no pocas complicaciones en su vida diaria.', '/vCX2U9j88qKL7j56OKx6mhhIlLP.jpg', '/dGRGes6Yw0vK1IymLatHBXGvvpS.jpg', 7.2, 'IS-rkKwfuJU', array['1001']::text[], 686, null, 'segura', null),
(1720588, 'movie', 'El camino', 'El Camino', 'El Camino', 1984, 'Pedro Novak', 'The destruction of the cloud forest ecology by the construction of the marginal jungle road.', null, null, null, null, array['1001']::text[], 687, null, 'segura', null),
(13776, 'movie', 'Diner', 'Diner', 'Diner', 1982, 'Barry Levinson', 'En Baltimore, durante el invierno de 1959, cinco veinteañeros pasan su tiempo en Diner. Allí, se refugian en los buenos momentos que han pasado juntos, tratando de eludir complicadas relaciones sentimentales, problemas de juego y matrimonios difíciles que la madurez les exige afrontar.', '/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg', '/teiop9EWCTTlQ833jrhUPKkK5fs.jpg', 6.8, '__Q6_27KKEc', array['1001']::text[], 688, null, 'segura', null),
(9343, 'movie', 'Fitzcarraldo', 'Fitzcarraldo', 'Fitzcarraldo', 1982, 'Werner Herzog', 'Fitzcarraldo es un soñador que planea construir un teatro de ópera en Iquitos, en la Amazonía peruana, así que, para financiar su proyecto, se embarca en una aventura épica para recolectar caucho, un producto muy rentable, en una región remota e inexplorada de la selva.', '/ArN2ltzwfJG0bFuLBQMYuYK3rpk.jpg', '/46iMqI1qzAtnXJxGRNCFwYNYqOo.jpg', 7.6, 'H_OgtTZMSXI', array['1001']::text[], 690, null, 'segura', null),
(783, 'movie', 'Gandhi', 'Gandhi', 'Gandhi', 1982, 'Richard Attenborough', 'Después de defender los derechos de los ciudadanos africanos en Sudáfrica, Gandhi, considerando que también los hindúes son ciudadanos de segunda clase en su propia tierra, los incita a sublevarse contra el Imperio Británico mediante la doctrina de la no-violencia.', '/xkB9dSy7WlQOsOinevVuebXiXvU.jpg', '/gum3tuO1zKHBdElSQPS08PJ1w67.jpg', 7.6, 'vziq3CA_C30', array['1001']::text[], 692, null, 'segura', null),
(96529, 'movie', 'El silencio de Christine M.', 'El silencio de Christine M.', 'De stilte rond Christine M.', 1982, 'Marleen Gorris', 'Inspirada por la noticia de que una mujer de clase obrera ha sido detenida por robar en una tienda, la película se centra en tres mujeres que se conocen, y que matan al gerente de una boutique que se enfrenta desdeñosamente a un ama de casa hecha polvo a la que han pillado con las manos en la masa.', '/u4QFBhIDxxLubz0n9z54m4pd9vj.jpg', '/plzGj1h3TKjRUIg0W3Ls5F0iz3V.jpg', 6.3, 'mO-gVvLQuTE', array['1001']::text[], 693, null, 'segura', null),
(42130, 'movie', 'La noche de San Lorenzo', 'La noche de San Lorenzo', 'La notte di San Lorenzo', 1982, 'Vittorio Taviani, Paolo Taviani', 'Segunda Guerra Mundial (1939-1945). En la noche del 10 de agosto de 1944, día de San Lorenzo, los vecinos de un pueblo toscano huyeron a las montañas para evitar ser bombardeados por las tropas alemanas.', '/lLPEm7QTlM6jPXRmwRUIQVZMhce.jpg', '/oWtUJSIfN4umPrwiHwawhMuDZlL.jpg', 7.1, 'ADIph1-og3o', array['1001']::text[], 693, null, 'segura', null),
(5961, 'movie', 'Fanny y Alexander', 'Fanny y Alexander', 'Fanny och Alexander', 1982, 'Ingmar Bergman', 'Fanny y Alexander son dos hermanos que pertenecen a la pintoresca familia Ekdahl, a principios de siglo XX. Sus padres, Oscar y Emilie, son el director y la actriz principal de la compañía local de teatro, respectivamente. Tras la repentina muerte de Oscar, Emilie se vuelve a casar con un predicador autoritario que les obliga a mantener una vida ascética. "Fanny y Alexander" fue mimada por la crítica y consiguió cuatro Oscars en la edición de 1984: dirección artística, fotografía, vestuario y película de habla no inglesa.', '/heSihYfiOqSNeWcuCRP2GoApZJO.jpg', '/8reX3CMog1QHqGoym2Esvuk5MnK.jpg', 7.8, 'UCXoXFdNa1o', array['1001']::text[], 694, null, 'segura', null),
(17435, 'movie', 'El norte', 'El Norte', 'El Norte', 1983, 'Gregory Nava', 'Rosa y Enrique huyen de su remoto pueblo maya después de la muerte de sus padres a manos de las tropas del ejército, y salen para "el norte" (Estados Unidos) en busca de una vida mejor y más segura.', '/bgpz7gTpWmmBb26CcjVtiPE7Kfo.jpg', '/5G54yKy3A6MFfwzQ5Q6rrYyjvrY.jpg', 7.1, 'jPoqBCvyG9k', array['1001']::text[], 695, null, 'segura', null),
(850, 'movie', 'Historias de Navidad', 'Historias de Navidad', 'A Christmas Story', 1983, 'Bob Clark', 'En los años cuarenta, un niño quiere como regalo de navidad un rifle de aire comprimido. Claro está, los padres piensan que no es una buena idea. Comedia familiar extraordinariamente popular en Estados Unidos que se basa en las historias del humorista Jean Shepherd. Calificada como divertida y conmovedora a partes iguales, una tierna historia con mensaje que encandila tanto a los adultos como a los más jóvenes.', '/6zQwRUJcDvLiLIrUjdTtt1WZUkJ.jpg', '/feCcRTZNGUop3LnWBLTToYhd03S.jpg', 7.2, 'ptbPSR9pAB8', array['1001']::text[], 695, null, 'segura', null),
(837, 'movie', 'Videodrome', 'Videodrome', 'Videodrome', 1983, 'David Cronenberg', 'Max Renn, un aburrido operador de televisión por cable, un día descubre una televisión "real" llamada Videodrome. Una palpitante pesadilla de ciencia-ficción que nos muestra un mundo en el que el vídeo puede controlar y alterar la vida humana. Considerada por Andy Warhol la "Naranja mecánica" de los 80.', '/qqqkiZSU9EBGZ1KiDmfn07S7qvv.jpg', '/eBS1nvaQ7BMdsSlkoLyKapf0FEY.jpg', 7.2, 'v8BUXKcp8zE', array['1001']::text[], 696, null, 'segura', null),
(1892, 'movie', 'El retorno del Jedi', 'El retorno del Jedi', 'Return of the Jedi', 1983, 'Richard Marquand', 'Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.', '/rKMmXzdm7eRgmlwYo7iq3klT7wJ.jpg', '/ziECpBRIyclmBNaFSWlvCfsKbMD.jpg', 7.9, 'yhuKapE-Bio', array['1001']::text[], 697, null, 'segura', null),
(12560, 'movie', 'Reencuentro', 'Reencuentro', 'The Big Chill', 1983, 'Lawrence Kasdan', 'Ocho viejos amigos, compañeros de universidad en la década de los sesenta, vuelven a reunirse un fin de semana con motivo del entierro de uno de los miembros del grupo. El fallecido era un médico brillante que rehusó integrarse en el sistema y que, tras quince años de vagabundeo, acabó por suicidarse en la elegante mansión de uno de sus amigos.', '/gIPdTSNL80qXxy0qNGnZr6qiAkX.jpg', '/rzaoRlc9xzopMvb464kFmotqsES.jpg', 6.8, 'hHUwAZdQFBg', array['1001']::text[], 697, null, 'segura', null),
(12607, 'movie', 'Kamikaze 1989', 'Kamikaze 1989', 'Kamikaze 1989', 1982, 'Wolf Gremm', 'In a futuristic, totalitarian society wherein the government controls all facets of the media, a homicide detective investigates a string of bombings and uncovers more than he bargained for.', '/bVPypYfhkz3OBtJgiUelbZ2AMdq.jpg', '/lF5b0rZzcmY546uBQU8cEEVA91B.jpg', 5.4, 'ptje_US6YpA', array['1001']::text[], 698, null, 'segura', null),
(1563, 'movie', 'Sans soleil', 'Sin sol', 'Sans soleil', 1983, 'Chris Marker', 'Tres niños en una carretera en Islandia, una tripulación somnolienta a bordo de un ferry, un emú en Île de France, un bello rostro de las islas Bijagos, un cementerio de gatos a las afuera de Tokio, vagabundos en Namidabashi, los habitantes de la Isla de Fogo, Cabo Verde, un carnaval en Bissau... Así inicia el relato una mujer desconocida que lee las cartas remitidas por un operador de cámara, Sandor Krasna, que a través del registro de las imágenes de sus viajes se interroga sobre la memoria y la función del recuerdo, "que no es lo contrario del olvido, sino su opuesto", para conformar, como Sei Shônagon, su particular lista de "cosas que hacen latir el corazón".', '/7gZC2ardRuFBB6qyQDw7HaLa921.jpg', '/lns7roobSPQQTF54oSPzkT3qH1q.jpg', 7.5, '0K8j3MU9dw4', array['1001']::text[], 698, null, 'segura', null),
(42112, 'movie', 'El dinero', 'El dinero', 'L''Argent', 1983, 'Robert Bresson', 'Adaptación de un relato breve de Leon Tolstoi: "El billete falso". Yvon es un joven que es injustamente acusado de traficar con dinero falso. A partir de ese error judicial, la adversidad dominará su vida. Durante su estancia en prisión, el ambiente en el que se mueve lo va degradando y corrompiendo hasta convertirlo en una persona sin escrúpulos ni principios morales.', '/7KPq52V27rCukeQUjCflX8DSsZ9.jpg', '/a62YSsCwYd5EyzB5EbaeX2FmM4m.jpg', 6.9, 'jBMLpghqQj4', array['1001']::text[], 699, null, 'segura', null),
(42123, 'movie', 'Utu', 'Utu', 'Utu', 1983, 'Geoff Murphy', 'En Nueva Zelanda, hacia 1860, el pueblo nativo Maorí combatió a los británicos colonialistas para intentar conservar sus tierras amenazadas. Un guerrero, Te Wheke, combatirá por los británicos hasta que es traicionado, buscando entonces "utu", venganza.', '/jSPTs6c9MQrd2rsrnqMJXQ0o3xz.jpg', '/f1B5fksvFtdq1A2DHVaYqWKqaqe.jpg', 7.0, 'CsTqvrgPOHE', array['1001']::text[], 700, null, 'segura', null),
(11050, 'movie', 'La fuerza del cariño', 'La fuerza del cariño', 'Terms of Endearment', 1983, 'James L. Brooks', 'Aurora y Emma son madre e hija que marchan a diferentes ritmos. Comenzando con el matrimonio de Emma, Aurora muestra lo difícil y amorosa que puede ser. La película abarca varios años de su vida y como cada uno encuentra diferentes razones para seguir viviendo y encontrar la alegría. Interludios de Aurora con Garrett Breedlove, el astronauta retirado y vecino de al lado son bastante sorprendentes.', '/iUa8SO1t0d89cXtDKOzYYsSge7M.jpg', '/rZXTcmx7mKysaseyWZHs6wzPAcZ.jpg', 7.1, '7BToOAoehA0', array['1001']::text[], 701, null, 'segura', null),
(29140, 'movie', 'El cuarto hombre', 'El cuarto hombre', 'De vierde man', 1983, 'Paul Verhoeven', 'Un escritor alcohólico comienza a tener visiones que parecen anunciarle un peligro inminente. Un día tiene una aventura con una mujer que ha asistido a la presentación de uno de sus libros y, desde entonces, las visiones se intensifican.', '/6VNnZYi8Gn4v4allwe8UMag8LqH.jpg', '/pDbusBxuQdGw8nmtTYBuxe8yGND.jpg', 6.7, 'O-EW1wufaUE', array['1001']::text[], 702, null, 'segura', null),
(262, 'movie', 'El rey de la comedia', 'El rey de la comedia', 'The King of Comedy', 1982, 'Martin Scorsese', 'Amarga comedia que narra la historia de Rupert Pupkin, un cómico obsesionado con convertirse en el mejor en su campo. Un día Rupert conoce a su ídolo, Jerry Langford, y le suplica la oportunidad de aparecer en su show, pero éste se la niega. Sin embargo no cejará en su empeño, acechando a Jerry hasta que consiga lo que quiere. Finalmente y con la ayuda de su amiga Masha secuestrarán a Langford para poder conseguir sus propósitos.', '/7z5ni7necxkhE2xEodbYB5IyrIP.jpg', '/7Mh1DM4kCMbN93C2MlUavYbH5YM.jpg', 7.8, '0wVhCCo02P4', array['1001']::text[], 702, null, 'segura', null),
(9549, 'movie', 'Elegidos para la gloria', 'Elegidos para la gloria', 'The Right Stuff', 1983, 'Philip Kaufman', 'El libro de Tom Wolfe sobre la historia del programa espacial de los Estados Unidos, se lee como si fuera una novela, y la película mantiene esa misma emocionante apariencia de ficción. Hace un recorrido desde la rotura de la barrera del sonido por Chuck Yeager en la base de la Fuerza Aérea de Edwards hasta los 7 astronautas seleccionados para el programa Mercurio, el primer proyecto de los Estados Unidos para enviar personas al espacio. Muestra que nadie tenía ni idea de cómo desarrollar un programa espacial o cual era la forma de seleccionar a las personas que debían participar en ella. Emocionante, divertido y encantador, todo a la vez.', '/bCM5AF6kaL86aW4udTe22SAqMk6.jpg', '/jPdRlbRBHGl2POLLk6Oylbav7ac.jpg', 7.4, 'G6dFmkvEKGE', array['1001']::text[], 703, null, 'segura', null),
(11314, 'movie', 'Koyaanisqatsi', 'Koyaanisqatsi', 'Koyaanisqatsi', 1983, 'Godfrey Reggio', 'Realizado entre los años 1975 y 1982, "Koyaanisqatsi" -primera parte de lo que sería luego una trilogía formada por Koyaanisqatsi (1982), Powaqqatsi (1988) y Naqoyqatsi (2002)- es un singular documental que refleja la colisión entre dos mundos obligados a convivir: por un lado la vida de los hombres en la sociedad moderna, la vida urbana y occidental, llena de tecnología, ciencia y consumismo. Por otro la naturaleza y el medio ambiente del planeta Tierra. Sin voz humana, tan sólo con el poder de las imágenes y la banda sonora minimalista de Philip Glass, Godfrey Reggio presentó este documental ante 5000 personas el 4 de Octubre de 1982 en el Radio City Hall de Nueva York, convirtiéndose al instante en un documental de culto.', '/iCef19ypS5FpImG6YiJut4Av7QI.jpg', '/g2ULq1sv4rDY7UsLzaiGdb6zjbj.jpg', 7.9, 't7lnVRba6HE', array['1001']::text[], 704, null, 'segura', null),
(311, 'movie', 'Érase una vez en América', 'Érase una vez en América', 'Once Upon a Time in America', 1984, 'Sergio Leone', 'David Aaronson "Noodles", un pobre joven judío, conoce en los suburbios de principios del siglo XX de Manhattan, Nueva York, a Maximilian Bercovicz "Max", otro joven de origen hebreo dispuesto a llegar lejos por cualquier método. Entablan una gran amistad y forman, con los 3 colegas de "Noodles", Patrick Goldberg "Patsy", Philip Stein "Cockeye", y Dominic una banda que prospera rápidamente. Desgraciadamente, son perseguidos por Bugsy, el tipo para el que Noodles y sus amigos trabajaban anteriormente, y en uno de sus asaltos, mata a Dominic. Rápidamente Noodles se tira encima suyo y le mata, por lo que pasará 12 años en prisión. Cuando Noodles sale de prisión le recibe Max, que sigue con su banda junto a los otros 2 amigos, Patsy y Cockeye. Rápidamente, entre los 4, llegan a convertirse, en tiempos de la prohibición, en unos de los mayores gánsteres de todo el país.', '/u4VnqaxINtKVscmdldZsBojU6jm.jpg', '/xlDUjb0Q5Dv6jPQRF5VE4IMjIy.jpg', 8.4, '5vrbUpDihxs', array['1001']::text[], 705, null, 'segura', null),
(111, 'movie', 'El precio del poder (Scarface)', 'El precio del poder', 'Scarface', 1983, 'Brian De Palma', 'Un emigrante cubano frío y sanguinario, Tony Montana, llega de Cuba para instalarse en Miami, donde se propone hacerse con un nombre dentro del crimen organizado de Florida. Junto a su amigo, Manny Rivera, inicia una ascendente carrera delictiva.', '/iDABT5GD9OQmFiXM3wR0DJIxtkY.jpg', '/cCvp5Sni75agCtyJkNOMapORUQV.jpg', 8.2, 'vSp_kLkNdnE', array['1001']::text[], 706, null, 'segura', null),
(279, 'movie', 'Amadeus', 'Amadeus', 'Amadeus', 1984, 'Miloš Forman', 'Antonio Salieri es el músico más destacado de la corte del Emperador José II de Austria. Entregado completamente a la música, le promete a Dios humildad y castidad si, a cambio, conserva sus extraordinarias dotes musicales. Pero, después de la llegada a la corte de un joven llamado Wolfang Amadeus Mozart, Salieri queda relegado a un segundo plano. Irritado por la pérdida de protagonismo, hará todo lo posible para arruinar la carrera del joven músico. Mientras tanto, Mozart, ajeno a las maquinaciones de Salieri, sorprende a todos con su genialidad como músico, pero también con sus excentricidades.', '/nI24KqCadkHbjF4LpVHmUhQRNDn.jpg', '/rnQyWw68dPHPRtvSWMtLSueXf05.jpg', 8.0, 'yE9X2RC0Vj0', array['1001']::text[], 707, null, 'segura', null),
(42113, 'movie', 'La balada de Narayama', 'La balada de Narayama', '楢山節考', 1983, '今村昌平', 'Era una vieja ley del pueblo, de un tiempo tan lejano que ya nadie lo recordaba; Al alcanzar los 70 los ancianos debían abandonar el pueblo para ir a vivir en la cima de la montaña Narayama. Una sentencia de muerte despiadada que sumía en la tristeza y la desesperación a las familias cuando tenían que enviar a sus mayores a la montaña. Orin tiene 69 años y se acerca el momento de partir hacia la montaña, pero todavía tiene que encontrar una mujer a su hijo. Remake de la película "Narayama bushiko", dirigida en 1958 por Keisuke Kinoshita.', '/drZTWC3XxVSqKIfS0VQGgsRa2vz.jpg', '/76phbJ3Brq4VmpOomEOW9bNy8C5.jpg', 7.5, 'Lw08P2VDdgM', array['1001']::text[], 707, null, 'segura', null),
(218, 'movie', 'Terminator', 'Terminator', 'The Terminator', 1984, 'James Cameron', 'Un cyborg ha sido enviado desde el futuro en una misión mortal: eliminar a Sarah Connor, una joven cuya vida tendrá una gran importancia en los próximos años. Sarah tiene sólo un protector —Kyle Reese— también enviado desde el futuro. El Terminator utiliza su inteligencia excepcional y fuerza para encontrar a Sarah, pero ¿hay alguna forma de detener al cyborg aparentemente indestructible?', '/9KI49SBnwAOzGcMw1onIki7vd2.jpg', '/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg', 7.7, 'alLxdt9PLMc', array['1001']::text[], 708, null, 'segura', null),
(655, 'movie', 'París, Texas', 'París, Texas', 'Paris, Texas', 1984, 'Wim Wenders', 'Un hombre aparece andando en el desierto de Texas sin recordar quién es. Su hermano va en su busca, intentando que recuerde su vida cuatro años atrás, cuando abandonó a su mujer y a su hijo. Mientras la memoria va volviendo a él y recupera el contacto con personas de su pasado, descubre la oportunidad de rehacer su vida.', '/ba8edzVOul1uDHaLgDImALqhsN1.jpg', '/fWrq3u16gaBJ6nYNWcR3XaOhQPq.jpg', 8.1, 'Nmvte2r7Z8c', array['1001']::text[], 710, null, 'segura', null),
(377, 'movie', 'Pesadilla en Elm Street', 'Pesadilla en Elm Street', 'A Nightmare on Elm Street', 1984, 'Wes Craven', 'Varios jóvenes de una pequeña localidad tienen habitualmente pesadillas en las que son perseguidos por un hombre deformado por el fuego y que usa un guante terminado en afiladas cuchillas. Algunos de ellos comienzan a ser asesinados mientras duermen por este ser, que resulta ser un asesino al que los padres de estos jóvenes quemaron vivo hace varios años tras descubrir que había asesinado a varios niños.', '/qDmeYxsfNA68Bn7aW8HSkAuVmWf.jpg', '/nzSjTiecdosBfwMGAdpt9CxltCI.jpg', 7.4, 'X2qRCfXzc7g', array['1001']::text[], 711, null, 'segura', null),
(11031, 'movie', 'This Is Spinal Tap', 'Así es Spinal Tap', 'This Is Spinal Tap', 1984, 'Rob Reiner', 'Documental, más bien rockumental, sobre la banda de rock más ruidosa de la historia, el grupo de heavy metal "Spinal Tap". (FILMAFFINITY)', '/b3lllDltoBws5uKZzBYVSjpjjJx.jpg', '/a3FaHEGActk76BeCBingyOvEqnm.jpg', 7.4, '_9leMez8sQ8', array['1001']::text[], 712, null, 'segura', null),
(620, 'movie', 'Cazafantasmas', 'Los Cazafantasmas', 'Ghostbusters', 1984, 'Ivan Reitman', 'Los Drs. Venkman, Stantz y Epengler, son tres doctores en parapsicología que se quedan sin empleo tras quedar excluidos de una beca universitaria de investigación. Entonces deciden formar la empresa Cazafantasmas, dedicada a limpiar Nueva York de ectoplasmas. El aumento repentino de apariciones espectrales en la Gran Manzana será el presagio de la llegada de un peligroso y poderoso demonio.', '/7eZUL4fvjVkmNPbD8IxQT4X9emt.jpg', '/c6yfABGVKuB5cjoOwdX4AJMlzUz.jpg', 7.5, 'msq0hZSgZdM', array['1001']::text[], 713, null, 'segura', null),
(90, 'movie', 'Superdetective en Hollywood', 'Superdetective en Hollywood', 'Beverly Hills Cop', 1984, 'Martin Brest', 'Axel Foley es un impetuoso e inteligente detective de Detroit que sigue la pista del asesino de un amigo suyo hasta los barrios más elegantes de Beverly Hills. Pero antes de que Axel logre su objetivo, va a verse involucrado en una red internacional de contrabandistas y traficantes de droga.', '/q8RtQuLStydGdJmHR4p8jNVssbv.jpg', '/p256RduW9wMC3uhGJTerywmGiiX.jpg', 7.2, 'nfUPsOKywO8', array['1001']::text[], 713, null, 'probable', '[{"tmdb_id": 90, "titulo": "Superdetective en Hollywood", "original": "Beverly Hills Cop", "anio": 1984, "votos": 4812, "poster_path": "/q8RtQuLStydGdJmHR4p8jNVssbv.jpg", "sim": 1.0}, {"tmdb_id": 96, "titulo": "Superdetective en Hollywood II", "original": "Beverly Hills Cop II", "anio": 1987, "votos": 2952, "poster_path": "/19fU9cD8nBp3riUgKZi6nLSMO88.jpg", "sim": 0.947}]'::jsonb),
(15927, 'movie', 'Pasaje a la India', 'Pasaje a la India', 'A Passage to India', 1984, 'David Lean', 'Adaptación de una novela del escritor inglés E.M. Forster. India colonial, años 20. Adela, una joven inglesa, viaja a la India, en compañía de su futura suegra, para contraer matrimonio con un magistrado de Chandrapore. La joven está obsesionada por conocer a fondo la realidad del país y encuentra la oportunidad de satisfacer su deseo gracias al doctor Aziv, un médico hindú. Sin embargo, cuando éste organiza una excursión para mostrarle las cuevas de Marabar, ocurre algo absolutamente impensable.', '/ki58NEeFxHZFvJ4984WjRbaC9nD.jpg', '/vhexJUk3sTEldSl3cI3eRzt6SZ5.jpg', 6.8, '7mIHIofacDg', array['1001']::text[], 714, null, 'segura', null),
(469, 'movie', 'Extraños en el paraíso', 'Extraños En El Paraíso', 'Stranger Than Paradise', 1984, 'Jim Jarmusch', 'Dos amigos y la prima de uno de ellos, que acaba de llegar a Estados Unidos desde Budapest, viven en Florida diversas aventuras. Popular película del cine independiente de los años ochenta. Se rodó en apenas 18 días con un equipo de sólo once personas: tres actores y ocho técnicos.', '/m18vtINPVS2pt46uDqFmk0nhx3c.jpg', '/5KdLollJKNz9Pfy8jL2g9gEPEDw.jpg', 7.1, '0k4s4oEOZMo', array['1001']::text[], 715, null, 'segura', null),
(11393, 'movie', 'El mejor', 'El mejor', 'The Natural', 1984, 'Barry Levinson', 'Nada iba a impedir que Roy Hobbs cumpliese su sueño de ser una estrella del beisbol. Robert Redford protagoniza esta inspiradora historia que empieza cuando Hobbs, con 14 años, hace un bate muy potente de la madera de un roble caído. Muy pronto impresiona a los cazatalentos de las ligas profesionales con su habilidad y queda grabado en la retina del periodista deportivo Max Mercy, el cual acabará siendo clave en la carrera de Hobbs. Sin embargo, un encuentro con una mujer misteriosa da al traste con su sueño. Pasan los años y un Hobbs más mayor reaparece como un novato en los New York Knights. Superando el dolor físico y desafiando a aquellos que les interesa ver perder a los Knights, Hobbs, con su bate de la infancia, tiene la oportunidad de hacer ganar la liga a los Knights y por fin cumplir su sueño.', '/2VYvCnKVaHm70y5zIqzSrqkWLBe.jpg', '/sqZGYcHJWWNHsECBl57FOCfjpFX.jpg', 6.9, 'ihRtZcxghIE', array['1001']::text[], 716, null, 'segura', null),
(625, 'movie', 'Los gritos del silencio', 'Los gritos del silencio', 'The Killing Fields', 1984, 'Roland Joffé', 'Sydney es un periodista del "The New York Times" enviado a Camboya en 1972 como corresponsal de guerra. Una vez allí, conoce a Dith Pran, un nativo que le sirve de guía e intérprete durante la guerra. En 1975, al caer el gobierno camboyano, los EE.UU. se retiran del país, y toda la familia de Pran emigra a Norteamérica excepto él, que decide quedarse con el periodista para seguir ayudándole. Ambos viven refugiados en la embajada francesa, pero cuando deciden abandonar Camboya, el ejército revolucionario prohíbe salir del país a Pran, que es recluido en un campo de concentración.', '/qo5q1bZI1kCPOZroV1Fx5f1ozAU.jpg', '/c7OeJd34rc9bI1DXqd4ucb1wVrf.jpg', 7.5, 'mTfqXmVVjPU', array['1001']::text[], 716, null, 'segura', null),
(2108, 'movie', 'El club de los cinco', 'El club de los cinco', 'The Breakfast Club', 1985, 'John Hughes', 'Cinco estudiantes de distinta educación, formación y gustos son castigados a pasar un sábado en el instituto en el que estudian. Pronto las desavenencias entre ellos aparecen, especialmente cuando el director que les vigila se ausenta del aula... Comedia juvenil de culto de los años ochenta.', '/f0DhsS50Ksn6rBZhwsH9Rgh9xGi.jpg', '/s5HDOmFZaPVQFjk9BxxDrLu1T0g.jpg', 7.7, '8_7UkjKja7w', array['1001']::text[], 717, null, 'segura', null),
(11645, 'movie', 'Ran', 'Ran', '乱', 1985, 'Akira Kurosawa', 'En el Japón medieval, el poderoso señor Hidetora decide abdicar y repartir sus dominios entre sus tres hijos. El menor considera que la idea es absurda y sólo servirá para causar problemas. Su padre, enfurecido, lo deshereda. Muy pronto descubrirá su error: la ambición hará que sus hijos mayores se enfrenten por el poder en una cruenta guerra. Se inspira en el drama de Shakespeare "El rey Lear".', '/feChXPgGQhhRfvkzhzoKVp8RLpQ.jpg', '/vxEfLEdPbUJW8ZD9ymGQ6ZJzuyf.jpg', 8.0, '29ukiH4_GvQ', array['1001']::text[], 718, null, 'segura', null),
(25237, 'movie', 'Masacre: Ven y mira', 'Masacre (Ven y mira)', 'Иди и смотри', 1985, 'Элем Климов', 'Tras encontrar un viejo rifle, un joven se une a las fuerzas de la resistencia soviética, que lucha por expulsar a las fuerzas nazis del frente oriental. Allí, será testigo de algunos los mayores horrores cometidos en la Segunda Guerra Mundial.', '/j2hzNkmwYT184eP9qYdjViiYxCO.jpg', '/3Na31ta8vDuKOgQuPLdSZLs8bCB.jpg', 8.2, '38jQFZ00Cwo', array['1001']::text[], 720, null, 'segura', null),
(606, 'movie', 'Memorias de África', 'Memorias de África', 'Out of Africa', 1985, 'Sydney Pollack', 'A principios del siglo XX Karen Blixen (Streep), una mujer europea de gran coraje, llega a Kenia para dirigir una plantación de café junto a su marido (Brandauer), un mujeriego incorregible con el que no se ha casado por amor. Para su sorpresa, Karen se da cuenta de que poco a poco se está enamorando de la tierra, de sus gentes... y de Denys Finch-Hatton (Redford), un enigmático cazador aventurero.', '/lovoT4KeD7iyKcDMFo8Y8lFtCle.jpg', '/5hCGJLTuRlD5WoscKhVPHVnD4gz.jpg', 7.2, '5RrEv9-ks2Y', array['1001']::text[], 721, null, 'segura', null),
(29263, 'movie', 'La historia oficial', 'La historia oficial', 'La historia oficial', 1985, 'Luis Puenzo', 'Una profesora de historia empieza a sospechar que su hija adoptiva es hija de desaparecidos. Con Norma Aleandro y Héctor Alterio.', '/aUpMovE1AS9UHm893e3YsFLR2aB.jpg', '/qYQmznfMC433HrX5m58MJB0QOlK.jpg', 7.5, 'jZtJRa5XP28', array['1001','cine_argentino']::text[], 721, null, 'segura', null),
(10849, 'movie', 'La rosa púrpura de El Cairo', 'La rosa púrpura de El Cairo', 'The Purple Rose of Cairo', 1985, 'Woody Allen', 'EE.UU., Gran Depresión. Mientras Cecilia trabaja como camarera en Nueva Jersey, su marido se dedica a hacer el vago. Su única vía de escape es el cine, al que acude una y otra vez para evadirse de la realidad y soñar con un mundo de champagne, trajes de noche y fiestas elegantes. Una noche, el protagonista de su película favorita, "La rosa púrpura de El Cairo", se fija en ella y atraviesa la pantalla para conocerla.', '/h14XBPBjdS1Ex4q9zimiCBzU1CD.jpg', '/afbfZtBOZIfxlzzvHCOfauI6pna.jpg', 7.4, 'u9qate1rGAg', array['1001']::text[], 722, null, 'segura', null),
(105, 'movie', 'Regreso al futuro', 'Regreso al futuro', 'Back to the Future', 1985, 'Robert Zemeckis', 'El adolescente Marty McFly es amigo de Doc, un científico al que todos toman por loco. Cuando Doc crea una máquina para viajar en el tiempo, un error fortuito hace que Marty llegue a 1955, año en el que sus futuros padres aún no se habían conocido. Después de impedir su primer encuentro, deberá conseguir que se conozcan y se casen; de lo contrario, su existencia no sería posible.', '/owk40tn1sFJmC7bhamEpmhdZPKa.jpg', '/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg', 8.3, 'xxSo8ZEvzE8', array['1001']::text[], 723, null, 'segura', null),
(45999, 'movie', 'Tiempo para vivir, tiempo para morir (Tong nien wang shi)', 'Tiempo de vivir, tiempo de morir', '童年往事', 1985, 'Hou Hsiao Hsien', 'Film sobre la infancia y la adolescencia, muy influida por la propia niñez del director. Como muchos de sus compatriotas, la familia de Hou se trasladó del continente a Taiwán en 1948 y fue incapaz de volver. La película se centra en el cada vez mayor salto generacional de una familia separada de su herencia cultural.', '/3iHLQboQY6oxJnQNUI8PyTQdGq3.jpg', '/6SO3WcfmoByOt0SBB7tOCmPtkVF.jpg', 7.2, '1aZgpykUmpY', array['1001']::text[], 723, null, 'segura', null),
(68, 'movie', 'Brazil', 'Brazil', 'Brazil', 1985, 'Terry Gilliam', 'En un extraño y deprimente universo futurista donde reinan las máquinas, una mosca cae dentro de un ordenador y cambia el apellido del guerrillero Harry Tuttle por el del tranquilo padre de familia Harry Buttle, que es detenido y asesinado por el aparato represor del Estado. El tranquilo burócrata Sam Lowry es el encargado de devolver un talón a la familia de la víctima, circunstancia que le permite conocer a Jill Layton, la mujer de sus sueños. Y, mientras la persigue, hace amistad con Harry Tuttle y se convierte en su cómplice.', '/x7N8ZbCw7ojT8XbvoeGL0LXTK8E.jpg', '/9IYyCLf5NNAQFK9pNtqzEU9HWzM.jpg', 7.7, 'SRYdjfC7D28', array['1001']::text[], 724, null, 'segura', null),
(11703, 'movie', 'El beso de la mujer araña', 'El beso de la mujer araña', 'Kiss of the Spider Woman', 1985, 'Héctor Babenco', 'En una prisión sudamericana, Molina (William Hurt) y Valentín (Raúl Julia), dos compañeros de celda, se cuentan sus respectivas historias. Molina es un homosexual encarcelado por seducir a un menor. Valentín es un revolucionario que no ha olvidado las torturas a las que ha sido sometido durante los interrogatorios.', '/rHFlpEb1XxCsz5kHE59q8UAdknv.jpg', '/sQSKR3iDCtayRTN2Nr9LiRYy6TT.jpg', 7.0, 'faiLjJOR_YE', array['1001']::text[], 726, null, 'segura', null),
(10176, 'movie', 'El único superviviente', 'El único superviviente', 'The Quiet Earth', 1985, 'Geoff Murphy', 'El científico Zac Hobson experimenta con una fuente de energía de extraordinario poder: un cinturón de fuerza que rodearía todo el planeta. Pero el experimento resulta mal, envía a la casi totalidad de la población a una dimensión desconocida, y el cinturón acaba sin dejar ni rastro de los seres vivos de todo el planeta. Aunque al principio Zac se desespera pensando que es el único hombre que queda vivo sobre la faz de la Tierra, pronto localiza algún superviviente más.', '/3cpB8cLtG2ViNf9XFWgHbSJnFlC.jpg', '/acNTpCRoAHueT1VoJzEQPYXdXy5.jpg', 6.7, 'JnyxaSAY_M0', array['1001']::text[], 727, null, 'segura', null),
(2075, 'movie', 'El honor de los Prizzi', 'El honor de los Prizzi', 'Prizzi''s Honor', 1985, 'John Huston', 'Charley Partanna es un asesino a sueldo al servicio de los Prizzi, una de las familias más poderosas de la mafia. La hija del Don está enamorada de él, aunque entre ellos va a interponerse una bella y enigmática rubia: Irene Walker.', '/5wDBauRrTqrRvwiODk6EYv11HEx.jpg', '/lW4nIRGJAglS6Pt7gTgRIrmSHA2.jpg', 6.4, 'VEz13l-ULX0', array['1001']::text[], 728, null, 'segura', null),
(27064, 'movie', 'Mishima', 'Mishima: Una vida en cuatro capítulos', 'Mishima: A Life in Four Chapters', 1985, 'Paul Schrader', 'Producida por Coppola y Lucas, "Mishima" es un retrato biográfico del consagrado autor japonés Yukio Mishima. La película investiga la inquietud interior y las contradicciones de un hombre que trató de alcanzar una imposible armonía entre sí mismo, el arte y la sociedad. La trama se centra en el día en que Mishima conmocionó al mundo, al hacerse en público el seppuku o harakiri (25 de noviembre de 1970), en el Cuartel General del Ejército. El relato está salpicado de flashbacks para contar diversos episodios de su infancia, sus comienzos como escritor, el posterior triunfo profesional, su tranformación en estrella mediática, sus obsesiones por la belleza física y sus ambiguos gustos sexuales, así como la creación de la "Sociedad del Escudo".', '/6P9jhxgdLGJMxlteZzuIcMQtM96.jpg', '/PnwQJeWhmx9wh9wWM0a0YhLmE.jpg', 7.8, '5nVKJDSrxNg', array['1001']::text[], 728, null, 'probable', '[{"tmdb_id": 27064, "titulo": "Mishima: Una vida en cuatro capítulos", "original": "Mishima: A Life in Four Chapters", "anio": 1985, "votos": 380, "poster_path": "/6P9jhxgdLGJMxlteZzuIcMQtM96.jpg", "sim": 0.368}, {"tmdb_id": 427838, "titulo": "The Strange Case of Yukio Mishima", "original": "The Strange Case of Yukio Mishima", "anio": 1985, "votos": 4, "poster_path": "/iJ53cMfjML8bMUod7eJgDJ3vSpZ.jpg", "sim": 0.389}, {"tmdb_id": 1417771, "titulo": "Inside Mishima", "original": "Inside Mishima", "anio": 1985, "votos": 0, "poster_path": "/53PG6a8XF831UjKA0XsFtiQQDYY.jpg", "sim": 0.667}]'::jsonb),
(44018, 'movie', 'Sin techo ni ley', 'Sin techo ni ley', 'Sans toit ni loi', 1985, 'Agnès Varda', 'Varda hace un lírico réquiem de Mona, una adolescente vagabunda que es encontrada muerta, mostrando en flashback sus últimos meses de vida, su desarraigo social y sus relaciones con la gente que conoció.', '/a42VZYIhgHIyrlvhVpzvLtOAdmf.jpg', '/tKsFh8qpYyi2AMg5O8QTVdChm4k.jpg', 7.4, 'i9pD323U_Hc', array['1001']::text[], 729, null, 'segura', null),
(42044, 'movie', 'Shoah', 'Shoah', 'Shoah', 1985, 'Claude Lanzmann', 'Rodada entre los años 1970 y 1980, investiga las causas y motivos del genocidio desde el nivel de la experiencia: los paisajes de los campos de exterminio y los guetos, las rutinas diarias de los encarcelados, el inexorable trauma de la humillación, el castigo y el exterminio, y los fascinantes y escalofriantes testimonios de aquellos que lo experimentaron de primera mano, salvaguardando para siempre en el tiempo las palabras de aquellos que sobrevivieron. Las imágenes de archivo están desterradas en la obra de Lanzmann y son estas mismas palabras las que ejercen como vehículo y alma de la narración. La obra de un genio, un esfuerzo heróico por humanizar lo inhumano, por narrar lo inarrable y explorar con un detalle sin precedentes los horrores del pasado.', '/psrGGJTUkQ8hh5wJjiiA3lTdlWZ.jpg', '/bJolDsqM8vnlusFJdnCi9rg1nX7.jpg', 8.2, '2g-Lc2ZSutA', array['1001']::text[], 730, null, 'segura', null),
(873, 'movie', 'El color púrpura', 'El color púrpura', 'The Color Purple', 1985, 'Steven Spielberg', 'Principios del siglo XX. Narra la historia de Celie, una adolescente negra de catorce años que está embarazada de su propio padre, un hombre despótico y cruel. A partir de entonces su vida estará llena de dolor y humillaciones.', '/rSjW6AMQJFJF9WhHdKRvz7f6DVH.jpg', '/lh6MbyxwCribn3hdAo81xLdPGoV.jpg', 7.7, '_h-efLS7VV4', array['1001']::text[], 731, null, 'segura', null),
(235, 'movie', 'Cuenta conmigo', 'Cuenta conmigo', 'Stand by Me', 1986, 'Rob Reiner', 'En un pequeño pueblo de Oregon, cuatro jóvenes amigos salen de la ciudad en busca de un chico desaparecido: el sentimental Geordie, el rudo Chris, el extravagante Teddy y el miedoso Vern. Deseando ser vistos como héroes ante ellos mismos y ante los ojos del pueblo, emprenden una inolvidable excursión de dos días que se convierte en una aventura increíble. Fuman a escondidas, cuentan historias, sueltan tacos porque les gusta y hacen causa común cuando las cosas se ponen difíciles. Cuando se encuentran con los matones del pueblo, que armados de cuchillos también buscan el cuerpo, los chicos descubren una fuerza que nunca supieron que tenían.', '/hlUOQHgZ1k4ba34r7vjgYI4r12g.jpg', '/yjGllQUm28R4X9xD9T5xMszirgw.jpg', 7.8, '2rBenGsz23E', array['1001']::text[], 732, null, 'segura', null),
(11454, 'movie', 'Hunter', 'Hunter', 'Manhunter', 1986, 'Michael Mann', 'Will Graham (William Petersen) regresa a la policía persuadido por un compañero. Encargado de la difícil tarea de dar caza a un escurridizo asesino que ataca sólo los días de luna llena, Graham decide emplear métodos poco convencionales. De este modo, recurre al doctor Hannibal Lecter (Brian Cox), otro asesino en serie, para entrar en la mente del asesino, pero esto le llevará a estar expuesto a la inteligencia de un genio poniendo en peligro su salud mental.', '/wmHocNihxPpngL6wJ32ec63SEux.jpg', '/zOO8GRa02x9o1iGOIIAJD50YcMW.jpg', 7.0, 'fywNBuzD2SU', array['1001']::text[], 732, null, 'segura', null),
(793, 'movie', 'Terciopelo azul', 'Terciopelo azul', 'Blue Velvet', 1986, 'David Lynch', 'Una mañana, Jeffrey Beaumont, después de visitar a su padre en el hospital, encuentra entre unos arbustos una oreja humana. La guarda en una bolsa de papel y la lleva a la comisaría de policía, donde le atiende el detective Williams, que es vecino suyo. Comienza así una misteriosa intriga que desvelará extraños sucesos acontecidos en una pequeña localidad de Carolina del Norte.', '/rzcigN8ujeVJiEKGP3y3mJybvii.jpg', '/s1CBwblInR0ZBIv59CSko2QdLD3.jpg', 7.6, 'SECSDOK58Vc', array['1001']::text[], 733, null, 'segura', null),
(5143, 'movie', 'Hannah y sus hermanas', 'Hannah y sus hermanas', 'Hannah and Her Sisters', 1986, 'Woody Allen', 'La hija mayor de una pareja de artistas, Hannah, es una esposa devota, madre cariñosa y actriz de éxito. Defensora leal de sus dos hermanas, Lee y Holly, es también la columna vertebral de una familia que parece casi tan resentida de su estabilidad como depende de ella. Pero cuando la rivalidad fraternal sabotea silenciosamente el mundo perfecto de Hannah, finalmente se da cuenta de que está tan perdida como todos los demás, y para ser capaz de encontrarse tendrá que elegir entre la independencia y... la familia sin la cual no puede vivir.', '/zU7aEciHJrZuuH1QKOifXYbRYqM.jpg', '/jx6jUMCLhRWB05ngVjaGxPpLq5x.jpg', 7.5, '8YPsjtK60ds', array['1001']::text[], 734, null, 'segura', null),
(18499, 'movie', 'El declive del imperio americano', 'El declive del imperio americano', 'Le Déclin de l''empire américain', 1986, 'Denys Arcand', 'Uno de los grandes éxitos del cine canadiense de los años ochenta. El director francófono -natural de Quebec- Denys Arcand retrata dos grupos, uno de hombres y otro de mujeres, que hablan de sexo, de sus fantasías, sus fustraciones, sus intimidades...', '/tfdkiDVj9UiJyZc0j9UFtXzHFeW.jpg', '/yItBvynVmSCTvAkzAm5PllP4oth.jpg', 6.7, 'a7R4YFi_qhA', array['1001']::text[], 735, null, 'segura', null),
(27995, 'movie', 'Nola Darling', 'Nola Darling', 'She''s Gotta Have It', 1986, 'Spike Lee', 'Una joven afroamericana de Brooklyn no acaba de decidirse entre sus tres pretendientes, pero se niega a renunciar a ellos. El primer film de Spike Lee (escrito, dirigido y editado por él), es una brillante comedia de tono semidocumental, filmado en blanco y negro y con algunas escenas en color. Su gran éxito de crítica (declarada mejor película en los Independent Spirit Awards) y público, su tono de comedia sin abandonar las ideas y compromisos, y la práctica ausencia de directores negros, hizo que el joven realizador americano se implantara fulminantemente en el panorama cinematográfico mundial. (FILMAFFINITY)', '/qiJuXvPONqTSSnzhbCBqE7EotV.jpg', '/aqUYYwKMNRzmqvkBvNM1gqRerb1.jpg', 6.6, 'Pd9oTGr_1DA', array['1001']::text[], 735, null, 'segura', null),
(9426, 'movie', 'La mosca', 'La mosca', 'The Fly', 1986, 'David Cronenberg', 'Seth Brundle, un excéntrico y solitario científico que crea uno de los inventos más revolucionarios de la historia: la cabina de teletransportación. En un intento por ponerla a prueba a la vez que ignora todo atisbo de prudencia, decide usarse a sí mismo como cobaya en la primera teletransportación aplicada a un humano, con la mala suerte de que una mosca se introduce junto con él en el artefacto. A partir de allí comenzará para Brundle una gradual pero definitiva transformación, una inquietante metamorfosis que le consumirá poco a poco, poniéndole en peligro a él y a los que le rodean.', '/lotsO2VRhsmeFKzqncMX9xrYMj6.jpg', '/g1FzhbtWYKk9WMJYi1X26kf2Q4Q.jpg', 7.5, 'jak8opma0SM', array['1001']::text[], 736, null, 'segura', null),
(679, 'movie', 'Aliens: el regreso', 'Aliens: El regreso', 'Aliens', 1986, 'James Cameron', 'Alien es un organismo perfecto, una máquina de matar cuya superioridad física sólo puede competir con su agresividad. La oficial Ripley y la tripulación de la nave «Nostromo» se habían enfrentado, en el pasado, a esa monstruosa criatura. Y sólo Ripley sobrevivió a la masacre. Después de vagar por el espacio durante varios años, Ripley fue rescatada. Durante ese tiempo, el planeta de Alien ha sido colonizado. Pero, de repente, se pierde la comunicación con la colonia y, para investigar los motivos, se envía una expedición de marines espaciales, capitaneados por Ripley. Allí les esperan miles de espeluznantes criaturas. Alien se ha reproducido y esta vez la lucha es por la supervivencia de la Humanidad.', '/3QU9EP8BFLnTh6w9ycDSCvhqbRU.jpg', '/4kix6fAblJIH6eMs0Ku2loyZJXK.jpg', 8.0, 'Rgjo6j5eNGk', array['1001']::text[], 737, null, 'segura', null),
(9377, 'movie', 'Todo en un día', 'Todo en un día', 'Ferris Bueller''s Day Off', 1986, 'John Hughes', 'Un joven de 17 años decide disfrutar de unas vacaciones anticipadas aprovechando la ausencia de sus padres. Prepara minuciosamente un día dedicado enteramente a hacer todo lo que normalmente no puede hacer. Para ello contará, por supuesto, con la compañía de su mejor amigo y de su novia.', '/aKUOSTR0WeghsBHHDUlgdluFjNl.jpg', '/jehzP4JKiFzgTWIaASLFOJocJke.jpg', 7.6, 'tx9micq-Ge0', array['1001']::text[], 737, null, 'segura', null),
(1554, 'movie', 'Bajo el peso de la ley', 'Bajo el peso de la ley', 'Down by Law', 1986, 'Jim Jarmusch', 'Tres hombres muy diferentes se conocen al compartir celda en una cárcel de Louisiana. Zack es un DJ; Jack, un chulo de poca monta y Roberto, un turista italiano.', '/yZNFj9E1K2pRsMzY43rxfMyXcND.jpg', '/8kVPLOzuZ1G9EBYxcOrzaHbxCeC.jpg', 7.4, 'IeFU1PJ-APQ', array['1001']::text[], 738, null, 'segura', null),
(1890, 'movie', 'Hijos de un dios menor', 'Hijos de un dios menor', 'Children of a Lesser God', 1986, 'Randa Haines', 'James es el nuevo profesor de dicción en una escuela para sordos. Rápidamente se enamora de Sarah, una alumna que prefiere permanecer en la escuela antes que exponerse al duro mundo exterior. Ella empieza rechazándolo, pero poco a poco irá aceptando su ayuda y acabará abriéndole su corazón.  Un melodrama a la antigua usanza que obtuvo un gran éxito en su día, siendo nominado para los premios Óscar a mejor película, actor principal, actriz principal y secundaria, y guion adaptado. De todos ellos, sólo consiguió la estatuilla la debutante actriz sordomuda Marlee Matlin, en una de las mayores sorpresas que se recuerdan en la historia de estos premios. La intérprete inició así una productiva carrera qe la llevó a protagonizar series como "Dudas razonables" y "Picket Fences", y filmes como "Walker" o "Sombras en el silencio".', '/syJkZ0qLfXROL6Ty8lPrvCxVI8m.jpg', '/fiC5azwRjJmrwI59BlVpLqIegU1.jpg', 6.9, 'cljI6rSK1pc', array['1001']::text[], 739, null, 'segura', null),
(11257, 'movie', 'Una habitación con vistas', 'Una habitación con vistas', 'A Room with a View', 1986, 'James Ivory', 'Lucy Honey Church una joven inglesa de buena familia, se encuentra de viaje en Florencia, acompañada por su prima y dama de compañía Charlotte Bartlett. En la pensión donde se hospedan conocen al excéntrico señor Emerson y a su hijo George, que, amablemente, les ceden sus habitaciones para que las damas disfruten de una ventana con vistas a la ciudad.', '/rZsAkIJMvpRrftbkh40T84JNXRN.jpg', '/7BawlYbO8j434ovY0xTHpaNNE0Y.jpg', 6.9, 'PW6W3EsfZaE', array['1001']::text[], 739, null, 'segura', null),
(792, 'movie', 'Platoon', 'Platoon', 'Platoon', 1986, 'Oliver Stone', 'Chris Taylor es un ingenuo joven estadounidense que, a su llegada a Vietnam, descubre que no sólo debe combatir contra los soldados vietnamitas sino también contra el miedo que le atormenta, el cansancio y la rabia que le invade. Mientras sus dos oficiales al mando libran su propia batalla personal, el conflicto, el caos y el odio hacen mella en Taylor, confundiendo su realidad e insensibilizándole ante el valor más preciado del ser humano... la vida.', '/Aeo2CHf8oWQzxAw4QpB43YfqxEF.jpg', '/5hRvPi8z7XaGQJi1OZ3QKyJiAaA.jpg', 7.7, 'R8weLPF4qBQ', array['1001']::text[], 740, null, 'segura', null),
(20537, 'movie', 'Caravaggio', 'Caravaggio', 'Caravaggio', 1986, 'Derek Jarman', 'El pintor Michelangelo Merisi, nacido en Caravaggio, se está muriendo lejos de su hogar. En el lecho de muerte recuerda los comienzos de su vida como pintor. El niño Michelangelo dejó su Caravaggio natal al quedar huérfano, y se traslada a Milán, donde se inicia como pintor en diferentes talleres, hasta que establece un taller propio, en la Roma de los Papas, ganándose el favor de la Iglesia, que le encarga numerosas obras. Llegan entonces la fama, el dinero, sus amores homosexuales, las intrigas políticas y religiosas, la envidia y el crimen.', '/q2rGfOAJcwAIYUWPi716goAypFD.jpg', '/6srA1KSWjnysZivKIFZmROTzZuI.jpg', 6.1, 'Su6avUbq-1E', array['1001']::text[], 741, null, 'segura', null),
(11830, 'movie', 'Tampopo', 'Tampopo', 'タンポポ', 1985, '伊丹十三', 'Un camionero y su compañero prueban la sopa de una viuda, y al ser de las peores que han probado nunca, la cocinera viuda les pide ayuda para mejorar en la elaboración de la sopa. Durante el proceso surgirá entre ellos el encariñamiento con la dulce viuda. Aclamada comedia japonesa que emula el formato de western (alguien acude al rescate de una viuda que necesita ayuda) y con un toque curioso alrededor del disfrute de la comida. Una cinta que tuvo un notable éxito internacional en su día. El director Itami era un presentador de televisión reconvertido en realizador.', '/3qeVNWVR7UzZ6d9a2cdUSooTITY.jpg', '/oq8HM9TOSbH54Xy0OBJGzYrtUC7.jpg', 7.8, 'sur_pxcpuoE', array['1001']::text[], 741, null, 'segura', null),
(39776, 'movie', 'Peking Opera Blues (Do ma daan)', 'Peking Opera Blues', '刀馬旦', 1986, 'Tsui Hark', 'La película transcurre en la convulsa China de los años 20, cuando los señores de la guerra luchaban entre ellos por el poder, mientras el movimiento de Sun Yat-sen trataba de establecer una república democrática. La película sigue a tres chicas y dos chicos. Una de ellas hurta una caja de joyas durante la confusión producida por la toma de Pekín a cargo de un señor de la guerra. Un desertor se le une, pero las joyas terminan en la Opera de Pekín. Allí conocen a la hija del jefe de la compañía, que sueña con ser actriz. Pero en la ópera china, los papeles femeninos son interpretados por hombres. Pronto, la hija del jefe del señor de la guerra dominante y un agente del movimiento republicano aparecen en la trama.', '/6IcSrruE0hpBvqo40DRfX65nBRX.jpg', '/kUUPHesQLQePqobQNjW7UD6WOdA.jpg', 7.2, '7BeNzmpB0ZM', array['1001']::text[], 742, null, 'segura', null),
(6106, 'movie', 'Salvador', 'Salvador', 'Salvador', 1986, 'Oliver Stone', 'Tragedia sobre las guerras civiles de Centroamérica en los años ochenta. Richard Boyle fue un reportero norteamericano que trabajó en El Salvador en este periodo. La conmoción que experimentó al descubrir por sí mismo ciertos aspectos de la realidad que ignoraba lo impulsó a comprometerse y a tomar partido.', '/tfUPNBXTqp55y7e3eYyUwc6HFug.jpg', '/6DSXD0cSOOQJd9YX7KUekv6bKLr.jpg', 7.0, 'JyRHCEt4JHs', array['1001']::text[], 742, null, 'segura', null),
(744, 'movie', 'Top Gun (Ídolos del aire)', 'Top Gun: Ídolos del aire', 'Top Gun', 1986, 'Tony Scott', 'La Marina de los Estados Unidos ha creado una escuela de élite para pilotos con el fin de sacar una promoción de expertos en técnicas de combate. En la academia, más conocida como Top Gun, a los mejores se les entrena para ser intrépidos y fríos al mismo tiempo, capaces de no perder los nervios en situaciones extremas y de no inmutarse al romper la barrera del sonido a los mandos de un F-14. A la escuela llega el joven Maverick, famoso por su temeraria aunque brillante forma de pilotar.', '/W8QUPhiBOCdj2urJDzc2D9xdQb.jpg', '/dBgxEkWe17R0AJDAvAhpeVELQx2.jpg', 7.1, 'Klc__shdj88', array['1001']::text[], 743, null, 'segura', null),
(41480, 'movie', 'Sherman''s March', 'La marcha de Sherman', 'Sherman''s March', 1986, 'Ross McElwee', 'Ross McElwee se propone hacer un documental sobre los efectos persistentes de la marcha de destrucción del General Sherman por el Sur durante la Guerra Civil, pero se ve continuamente desviado por las mujeres que van y vienen en su vida, sus sueños recurrentes de holocausto nuclear, y Burt Reynolds .', '/55YscDYNXdffYwDGMrpveqnsa9d.jpg', '/ce8iO3sSv4CCoesn3uiSQXofkbM.jpg', 6.3, 'Oy6e2X7a0PU', array['1001']::text[], 744, null, 'segura', null),
(42018, 'movie', 'El ladrón de caballos (Dao ma zei)', 'El ladrón de caballos', '盗马贼', 1986, '田壮壮', 'Norbu, un pobre montañés, se ve obligado a robar un caballo para mantener a su familia. Cuando se descubre que él ha sido el responsable, le expulsan de la tribu en la que convive, librándole de esta forma de cortarle las manos. Su intención de enmendarse y no recaer se ve frustrada ante el nacimiento de otro hijo, lo cual le lleva de nuevo a delinquir... (FILMAFFINITY)', '/s4hIycQ1SAQQEB14R6V9BsKdWMP.jpg', '/3SrVa2yrtj7SeK794vLDl5CI8CZ.jpg', 6.6, null, array['1001']::text[], 745, null, 'segura', null),
(71329, 'movie', 'Yeelen (La luz)', 'La luz', 'Yeelen', 1987, 'Souleymane Cissé', 'Un viejo hechicero africano, representante de una tradición secreta imperante en su etnia, persigue a su hijo para destruirlo -según dice- por no respetar sus mismos preceptos religiosos. En su huida, las diversas peripecias por las que atraviesa el joven se convierten en las pruebas de un penoso proceso de maduración... (FILMAFFINITY)', '/l92AuBmJkI1vDwBbTCbgbWqCr33.jpg', '/qNYWkqaVzgJm2dkGW5TlPMW18eO.jpg', 6.6, 'GRlNG9lJ6rs', array['1001']::text[], 745, null, 'segura', null),
(144, 'movie', 'El cielo sobre Berlín', 'El cielo sobre Berlín', 'Der Himmel über Berlin', 1987, 'Wim Wenders', 'Dos ángeles sobrevuelan Berlín, ciudad dividida por el "muro de la vergüenza". Sólo son visibles para los niños y los hombres de corazón puro. Testigos impotentes que no pueden cambiar el curso de los acontecimientos, sienten una gran compasión por los seres humanos. Uno de ellos, decidido a conocer los sentimientos de los mortales, se enamora de una joven trapecista.', '/3BUvkcxlIjrZN0wlgIK0cB8rAtp.jpg', '/7TlGXrB4WQ3wbpOCUQnBXseCuOl.jpg', 7.8, '0iAzYofuItM', array['1001']::text[], 746, null, 'segura', null),
(null, 'movie', 'El tesoro de China', null, null, null, null, null, null, null, null, null, array['1001']::text[], 748, null, 'dudosa', null),
(378, 'movie', 'Arizona baby', 'Arizona Baby', 'Raising Arizona', 1987, 'Joel Coen', 'H.I. McDonnough y Edwina, un exconvicto y una expolicía, son una pareja que ven sus planes de futuro frustrados al no poder tener hijos, pero están dispuestos a intentar recuperarlos secuestrando al bebé de una familia que acaba de tener quintillizos.', '/iLOKSXqDeVzA2al9f55WU7VAHE0.jpg', '/oSFshBf9Wrv5UcmZYAmy28BwSSh.jpg', 7.1, '9ZS8BMKw-JY', array['1001']::text[], 749, null, 'segura', null),
(11832, 'movie', 'El festín de Babette', 'El festín de Babette', 'Babettes gæstebud', 1987, 'Gabriel Axel', 'Nos situamos en la costa danesa a mediados del siglo XIX,  en una comunidad dominada por la moral y los prejuicios. La religión se sitúa en el centro de todo a través de todas las restricciones que se puedan imaginar. Para escapar de la represión sórdida del municipio rural, Babette (Stéphane Audran, ''El carnicero''), desembarca una tarde de tormenta en la salvaje costa de Jutland. Se convierte en la mujer de servicio de las dos hijas de un pastor muy puritano y se integra fácilmente en la austera comunidad. Pero después de catorce años en el exilio, recibirá fondos inesperados que le permitirán volver a su patria. Antes de su regreso, para agredecer a todos su hospitalidad, propondrá preparar con ese dinero una gran cena francesa para celebrar el centésimo aniversario del nacimiento del difunto pastor.', '/eFfoEZMVGHALJQnTcJBMvUMaz2O.jpg', '/iFl8eN4vWcMNNozmJk8E7cLgeT9.jpg', 7.2, 'AKuuW1jdzlc', array['1001']::text[], 749, null, 'segura', null),
(600, 'movie', 'La chaqueta metálica', 'La chaqueta metálica', 'Full Metal Jacket', 1987, 'Stanley Kubrick', 'Un grupo de reclutas se prepara en Parish Island, centro de entrenamiento de la marina Norteamericana. Allí está el sargento Hartmann, duro e implacable, cuya única misión en la vida es endurecer el cuerpo y el alma de los novatos, para que puedan defenderse del enemigo. Pero no todos los jóvenes soportan igual sus métodos...', '/6CX7BcyD8Xd5AQ7myNs0UE4mu6c.jpg', '/3k2TRmqMjgt7tcwkYwZQdctnty3.jpg', 8.1, '7115nOKRFD8', array['1001']::text[], 750, null, 'segura', null),
(801, 'movie', 'Good Morning, Vietnam', 'Good Morning, Vietnam', 'Good Morning, Vietnam', 1987, 'Barry Levinson', 'Vietnam. 1965. Un pinchadiscos de la radio, Adrian Cronauer, es enviado a Saigón para trabajar en la emisora del ejército norteamericano. En contraste con sus aburridos antecesores, Cronauer es pura dinamita, sus comentarios irreverentes, sus tacos e improperios y sus críticas al vicepresidente, le hacen ganarse el aprecio de las tropas. Sin embargo su superior el teniente Hauk no es de la misma opinión.', '/gsh0fhNQZ6O1ZYsDIt3THtBxoeP.jpg', '/mbgJEkrJ0uBOakLwpufdmW4K8Im.jpg', 7.3, 'JnBXv3W0arQ', array['1001']::text[], 752, null, 'segura', null),
(13446, 'movie', 'Withnail y yo', 'Withnail y yo', 'Withnail & I', 1987, 'Bruce Robinson', 'Dos jóvenes actores, Withnail y Marwood, comparten un miserable apartamento en Londres y buscan trabajo en vano, con poca suerte. Withnail convence a su rico y excéntrico tío Monty para que les preste su casa de campo durante unas semanas; pero encuentran el campo tan frío y antipático como la ciudad. Entonces el tío Monty se une a ellos y se propone inmediatamente seducir a Marwood. Withnail admite que le dijo a su tío que Marwood era gay (no lo es) porque de lo contrario no habrían tenido oportunidad de quedarse con la casa.', '/i18cIp8A10A2JgByrfA9oIC9299.jpg', '/bOgKCymrdPHPHozhRBNr9XhVD87.jpg', 7.2, 'PCJ2gzSeTdE', array['1001']::text[], 752, null, 'segura', null),
(1786, 'movie', 'Adiós muchachos', 'Adiós, muchachos', 'Au revoir les enfants', 1987, 'Louis Malle', 'Au revoir les enfants cuenta una historia desgarradora de amistad y pérdida devastadora de dos niños que viven en la Francia ocupada por los nazis. En un internado católico provincial, los jóvenes precoces disfrutan de una verdadera camaradería, hasta que se revela un secreto. Basada en eventos de la propia infancia del escritor y director Malle, la película es una historia sutil, observada con precisión, de coraje, cobardía y trágico despertar.', '/kRaOBKedKZjl9hPFwR7QmkjQH9N.jpg', '/xaRQqHgXMZCyqLFGZ7E3oDZx0ki.jpg', 7.5, 'qIaTVS7iQQk', array['1001']::text[], 753, null, 'segura', null),
(12626, 'movie', 'Al filo de la noticia', 'Al filo de la noticia', 'Broadcast News', 1987, 'James L. Brooks', 'En la redacción de informativos de una cadena de televisión de Washington, las prisas y los nervios condicionan la vida privada de sus empleados. Jane, la realizadora, vive obsesionada por controlar a todos los que están a su alrededor, incluid Tom, un atractivo locutor recién llegado y algo pretencioso, que representa para Jane todo lo que ella y su amigo Aaron han odiado siempre.', '/fKmrbKPaQtNymDQnk02YoOotbmb.jpg', '/wHSZJ8s0JfWIjoHkRknq6ZtGlZr.jpg', 6.8, 'WXYq-X3E7Ag', array['1001']::text[], 754, null, 'segura', null),
(65501, 'movie', 'Housekeeping', 'Housekeeping', 'Housekeeping', 1987, 'Bill Forsyth', 'In the Pacific Northwest during the 1950s, two young sisters whose mother has abandoned them wind up living with their Aunt Sylvie, whose views of the world and its conventions don''t quite live up to most people''s expectations.', '/chLoHQjsw484y6nUYTtSgr5BKBF.jpg', '/sETDgbocuqM3StaXxY0vamlZLUA.jpg', 6.6, 'Ask1brD5nLA', array['1001']::text[], 755, null, 'segura', null),
(2493, 'movie', 'La princesa prometida', 'La princesa prometida', 'The Princess Bride', 1987, 'Rob Reiner', 'Después de buscar fortuna durante cinco años, Westley retorna a su tierra para casarse con su amada, la bella Buttercup, a la que había jurado amor eterno. Sin embargo, para recuperarla habrá de enfrentarse a Vizzini y sus esbirros. Una vez derrotados éstos, tendrá que superar el peor de los obstáculos: el príncipe Humperdinck pretende desposar a la desdichada Buttercup, pese a que ella no lo ama, ya que sigue enamorada de Westley.', '/nHDpaLB6gMKyD8hMtSthtV7yPt9.jpg', '/onACwa3TjpeaY7EVHSZZbeNkd2q.jpg', 7.7, 'HFv8r4CKwTM', array['1001']::text[], 755, null, 'segura', null),
(2039, 'movie', 'Hechizo de luna', 'Hechizo de luna', 'Moonstruck', 1987, 'Norman Jewison', 'Loretta, una viuda de origen italiano que vive en Nueva York, decide contraer matrimonio con Johnny, un solterón de carácter débil al que maneja a su antojo. De repente, Johnny tiene que ir a Sicilia para visitar a su madre enferma; entonces le pide a Loretta que se encargue de invitar a la boda a su hermano Ronnie, del que está distanciado desde hace tiempo.', '/kb5aX2cyEvtVHKI3b7IBZ1u1311.jpg', '/5RQ5SIcrtKeUYeYeJLRTljR8LcN.jpg', 6.8, 'MN3sPq9RJKM', array['1001']::text[], 756, null, 'segura', null),
(117, 'movie', 'Los intocables de Elliott Ness', 'Los intocables de Eliot Ness', 'The Untouchables', 1987, 'Brian De Palma', 'El joven agente del tesoro Elliot Ness llega a Chicago con la determinación de detener a Al Capone. No va a ser tarea fácil, puesto que Capone tiene a la policía en el bolsillo. Ness conoce a Jimmy Malone, un guardia veterano y probablemente el más honrado de todo el cuerpo, al que Ness pide ayuda en su cruzada contra Capone.', '/pVcWaUbFDL76ObIsReIBQ5ILMHv.jpg', '/i1oWUGVDNBhGBykcCRBlX326udb.jpg', 7.8, 'TsWXoKO5Svw', array['1001']::text[], 756, null, 'probable', null),
(39507, 'movie', 'Dublineses', 'Dublineses', 'The Dead', 1987, 'John Huston', 'Es el día de la Epifanía de 1904 y está a punto de comenzar una de las celebraciones más concurridas de Dublín, la fiesta de las señoritas Morkan. Entre los invitados se encuentra Gabriel Conroy, sobrino de las anfitrionas y marido de Gretta, una de las mujeres más bellas del país. Es una noche maravillosa y los asistentes disfrutan de una magnífica velada. Gabriel, enamorado de su esposa, la contempla detenidamente cuando suena una antigua canción de amor. De vuelta a casa, Gretta le confiesa que aquella canción ha despertado en ella el recuerdo de un amor de juventud, que se vio truncado por la muerte del amado. Nunca antes le había contado a su marido esta historia.', '/FI7H18wlVW753Q54uz26Q4a9hf.jpg', '/dOC74DSvbBnE9117wyJzOdmG9Kz.jpg', 6.9, 'nNgMhgnt4FY', array['1001']::text[], 757, null, 'segura', null),
(42006, 'movie', 'Sorgo rojo', 'Sorgo rojo', '红高粱', 1988, 'Zhang Yimou', 'China, años treinta. Una joven es enviada por su padre para convertirse en la esposa del propietario de una bodega de vino de sorgo, que está enfermo de lepra. Durante el viaje se enamora de uno de los escoltas.', '/aorc2fg07UeKFdAc9frrj5TRf2J.jpg', '/4bjVA2NrkrdNPPpKUt7eR2P3xlf.jpg', 7.4, 'MFppekhfpgQ', array['1001']::text[], 757, null, 'segura', null),
(10998, 'movie', 'Atracción fatal', 'Atracción fatal', 'Fatal Attraction', 1987, 'Adrian Lyne', 'Mientras su mujer y su hija pasan el fin de semana fuera de casa, Dan tiene una aventura con Alex, una compañera de trabajo. Pero lo que para él no es más que una excitante pasatiempo, para ella es mucho más. Por eso, cuando Dan le comunica que quiere dejar de verla, enloquece.', '/1SwLxBkQw6T2XRVa5ZiHJ7tMXwS.jpg', '/2UlBdiveZcOVrlNe5MYcI6TYeA7.jpg', 6.8, 'HXQhUukZqkA', array['1001']::text[], 758, null, 'segura', null),
(30421, 'movie', 'Una historia china de fantasmas', 'Una historia china de fantasmas', '倩女幽魂', 1987, '程小東', 'Un inocente inspector de Hacienda llega a la ciudad donde tiene que recaudar impuestos, pero sólo tropieza con dificultades: la lluvia ha borrado los registros de su libro de cuentas y se ha quedado sin dinero. No tiene más remedio entonces que pasar la noche en una misteriosa casa situada en un bosque encantado. Allí conoce a una hermosa mujer, pero ignora que se trata de un fantasma que está obligado a capturar jóvenes para su cruel y perversa ama. El fantasma y el inspector se enamoran y, con la ayuda de un guerrero experto en el arte de la esgrima, lucharán contra el Señor de la Oscuridad para que el alma de la mujer pueda descansar en paz.', '/zKF9dYOImqMCXZyASVQviAi76JY.jpg', '/qkxMRQvKUsvidg7ewU1pcEbSX4h.jpg', 7.3, '5I1blOtGrck', array['1001']::text[], 758, null, 'segura', null),
(4203, 'movie', 'Mujeres al borde de un ataque de nervios', 'Mujeres al borde de un ataque de nervios', 'Mujeres al borde de un ataque de nervios', 1988, 'Pedro Almodóvar', 'Pepa e Iván son actores de doblaje. Él es un mujeriego empedernido y, después de una larga relación, rompe con Pepa: le deja un mensaje en el contestador pidiéndole que le prepare una maleta con sus cosas. Al quedarse sola, Pepa no soporta vivir en una casa llena de recuerdos y decide alquilarla. Mientras espera que Iván vaya a recoger la maleta, la casa se le va llenando de gente extravagante de la que aprenderá muchas cosas sobre la soledad y la locura.', '/3Mw74Vdc5xpoKQ3exlJuolyGYb6.jpg', '/eRzwmzyz4sSq2QqjXWehWNkU0Us.jpg', 7.4, 'phcJmTvhzus', array['1001']::text[], 759, null, 'segura', null),
(8740, 'movie', 'Desaparecida', 'Desaparecida', 'Spoorloos', 1988, 'George Sluizer', 'Rex y Saskia son una pareja de holandeses de vacaciones en Francia. En una gasolinera, Saskia desaparece sin dejar rastro. Rex dedica tres años de su vida a intentar encontrar a su novia sin éxito. Un día empieza a recibir postales de alguien que promete revelarle qué le pasó a Saskia. El supuesto secuestrador, un tipo llamado Raymond Lemorne, es un personaje escalofriante a quien Rex sigue la corriente en su obsesión de conocer la verdad sobre la desaparición de su amada. Y la verdad, quizá, sea más siniestra de lo que él nunca se atrevió a imaginar...', '/6pBloz1mwz8S0gYjUao6iUoyCng.jpg', '/gcXbxHjkUwLV4HrE2oJcbP7UGTA.jpg', 7.4, 'KlO2oIieI44', array['1001']::text[], 760, null, 'segura', null),
(2, 'movie', 'Ariel', 'Ariel', 'Ariel', 1988, 'Aki Kaurismäki', 'Premiada por la Sociedad de Críticos de Estados Unidos en 1990 como la mejor película extranjera, este filme es una exploración de la realidad finlandesa: desempleo, corrupción y vigilancia policial...', '/60lW3I7dYKgZL6FrY1HvZi24prf.jpg', '/hQ4pYsIbP22TMXOUdSfC2mjWrO0.jpg', 7.1, null, array['1001']::text[], 762, null, 'segura', null),
(287, 'movie', 'Los búfalos de Durham', 'Los búfalos de Durham', 'Bull Durham', 1988, 'Ron Shelton', 'Un novato (Robbins) y una vieja gloria del béisbol (Costner) se disputarán el amor de una madura y atractiva animadora del equipo (Sarandon). Cada primavera, Annie, forofa del equipo de béisbol "Los Búfalos" de Durham, elige a un jugador para "educarle" en la cama y en el campo de juego. Esta temporada tiene dos candidatos: el veterano y el novato. Ambos tienen cualidades pero, como suele suceder, ellas siempre deciden... (FILMAFFINITY)', '/6lvV2HjToCnyxADeeC859gzUy6W.jpg', '/6N852AJyrSV1noX9odRyoZQthcN.jpg', 6.6, 'qnWSvSrb1-I', array['1001']::text[], 762, null, 'segura', null),
(14285, 'movie', 'La delgada línea azul', 'La delgada línea azul', 'The Thin Blue Line', 1988, 'Errol Morris', 'Aclamado y premiado documental basado en hechos reales que relata el arresto y condena de Randall Adams, sentenciado a muerte por el asesinato de un policía de Dallas en 1976. Gracias al documental, se consiguió reabrir el caso de Adams.', '/4w4BJk3l8y9gYwPPLRs6uPHOmGL.jpg', '/9ndhlUu1VQ44pX5dVFo5Y19KqAl.jpg', 7.7, 'MzZROKde8Nc', array['1001']::text[], 763, null, 'segura', null),
(149, 'movie', 'Akira', 'Akira', 'AKIRA', 1988, 'Katsuhiro Otomo', 'Corre el año 2019. Un estado policial, políticos tramposos, sectas religiosas, revolucionarios y un proyecto científico secreto se combinan para causar una atmósfera explosiva en Neo-Tokyo. Todos los grupos rivales quieren controlar a Akira, un chico con extraños poderes psíquicos que ha sido mantenido bajo custodia criogénica por más de 30 años. En medio de esta tensa atmósfera, un joven psíquico llamado Tetsuo libera a Akira.', '/2WvrGAnKtHrb20nHLd38RyhIj0Q.jpg', '/fK40VGYIm7hmKrLJ26fgPQU0qRG.jpg', 7.9, 'SQ_hhKhrABs', array['1001']::text[], 764, null, 'segura', null),
(11216, 'movie', 'Cinema Paradiso', 'Cinema Paradiso', 'Nuovo Cinema Paradiso', 1988, 'Giuseppe Tornatore', 'En un pequeño pueblo siciliano durante los años previos a la llegada de la televisión (justo al finalizar la Segunda Guerra Mundial) el joven Toto vivía fascinado por el cine. Toto trata de entablar amistad con Alfredo, el proyeccionista del cine local, una persona muy irritable pero con un gran corazón. Todos estos hechos se presentan en forma de nostálgicos recuerdos de Toto que ha crecido hasta convertirse en un cineasta de éxito, y que revive a su infancia cuando recibe la noticia de que Alfredo ha muerto.', '/hHwsr3t5n7VVUbPyU8VZswn0jkL.jpg', '/zoVeIgKzGJzpdG6Gwnr7iOYfIMU.jpg', 8.4, 'JMyVSD6OvO8', array['1001']::text[], 765, null, 'segura', null),
(41954, 'movie', 'Hôtel Terminus: Klaus Barbie et son temps', 'Hôtel Terminus', 'Hôtel Terminus: The Life and Times of Klaus Barbie', 1988, 'Marcel Ophüls', 'Documental sobre el proceso contra Klaus Barbie, jefe de la Gestapo de Lyon, y sobre su vida después de la guerra.', '/gyU6I5h7K4M59QxFLCPJTMSzkDC.jpg', '/suxg30jaOoTLHQlvaz5ulUcxJQd.jpg', 7.1, 'cYDugHBkgTo', array['1001']::text[], 765, null, 'segura', null),
(623, 'movie', 'Un pez llamado Wanda', 'Un pez llamado Wanda', 'A Fish Called Wanda', 1988, 'Charles Crichton', 'Un grupo de delincuentes organizan un plan para robar una valiosa colección de diamantes en la joyería Hatton Gardens de Londres. Entre ellas se encuentra la encantadora Wanda, que va a intentar un doble juego para quedarse ella con el botín. Lo malo es que sólo George, el jefe de la banda, sabe dónde están escondidas las joyas, pero ha sido encarcelado.', '/urEkjQEOH3MgvdgQDaJIZHMaMzu.jpg', '/nNLOEK9HGhhZIOgdVUO9F7ndTIw.jpg', 7.2, '0WTwVpEEMps', array['1001']::text[], 766, null, 'segura', null),
(37136, 'movie', 'Agárralo como puedas', 'Agárralo como puedas', 'The Naked Gun: From the Files of Police Squad!', 1988, 'David Zucker', 'Después de que su compañero Nordberg fuera tiroteado por una banda de narcotraficantes, el incompetente teniente Frank Drebin busca al jefe de la organización para vengarse. Sospecha del magnate naviero Vincent Ludwig, pero no tiene pruebas para inculparlo. Tendrá incluso que enfrentarse a una alcaldesa, que trata de obstaculizar su investigación. Sin embargo, Drebin consigue la inesperada ayuda de Jane Spencer, una antigua novia de Ludwig.', '/eykTYCLnPW4quK6rqOHtc5PR8qy.jpg', '/qpjuVCGZvNsbDa4UyxrbAa4Dno3.jpg', 7.3, 'PACTQutbow4', array['1001']::text[], 767, null, 'segura', null),
(2280, 'movie', 'Big', 'Big', 'Big', 1988, 'Penny Marshall', 'Josh Baskin tiene trece años pero, cansado de que las chicas no le hagan caso y de que sus padres le traten como a un niño, desea ser mayor. Una noche, encuentra, en una feria, una vieja máquina que concede un deseo a cambio de una moneda. Josh, sin dudarlo un instante, pide hacerse mayor. A la mañana siguiente, descubre en el espejo un cuerpo de adulto. La otra cara de la moneda serán los problemas y responsabilidades que debe asumir sin ninguna experiencia previa.', '/ri6DEF9rul9Z0nOkPdTWHilZgJd.jpg', '/bi9ihIMB9DoXs7odkS5oKkHoK2o.jpg', 7.2, 'YM8zgY7sG_g', array['1001']::text[], 767, null, 'segura', null),
(12477, 'movie', 'La tumba de las luciérnagas (Hotaru no haka)', 'La tumba de las luciérnagas', '火垂るの墓', 1988, '高畑勲', 'Verano de 1945. La aviación estadounidense somete las ciudades japonesas a continuos ataques aéreos. En uno de ellos, una incursión con bombas incendiarias convierte la ciudad de Kōbe en un infierno humeante, para los dos protagonistas (Seita, de 14 años, y su hermanita Setsuko, de 5). El joven Seita y su pequeña hermana Setsuko son hijos de un oficial de la marina japonesa. Durante la Segunda Guerra Mundial, ambos viven con su madre, pero un día, tras un bombardeo, ellos se retrasan y no consiguen llegar al búnker donde ella los espera.', '/xTPa9c7Bgdq1BlZee24QeIx0jyR.jpg', '/aHaqZpOL7UyVu0nKqp3SMz0o2E1.jpg', 8.5, '3YeP-UMHVaE', array['1001']::text[], 768, null, 'segura', null),
(859, 'movie', 'Las amistades peligrosas', 'Las amistades peligrosas', 'Dangerous Liaisons', 1988, 'Stephen Frears', 'Francia, siglo XVIII. La perversa y fascinante Marquesa de Merteuil planea vengarse de su último amante con la ayuda de su viejo amigo el Vizconde de Valmont, un seductor tan amoral y depravado como ella. Una virtuosa mujer casada, Madame de Tourvel, de la que Valmont se enamora, se verá involucrada en las insidiosas maquinaciones de la marquesa.', '/oLuTwurVSb7X8t13SEhKo4Rfrvt.jpg', '/xH9mjObdAatWoHpT912DDK8hEYG.jpg', 7.2, 'i_odB2FsJ4w', array['1001']::text[], 768, null, 'segura', null),
(47795, 'movie', 'Paisaje en la niebla', 'Paisaje en la niebla', 'Τοπίο στην ομίχλη', 1988, 'Theo Angelopoulos', 'Dos niños griegos que buscan a su padre emprenden un viaje hacia Alemania, durante el cual encontrarán el bien y el mal, la verdad y la mentira, el amor y la muerte, el silencio y el verbo.', '/bmDckGwHHMZsohPadQxWJirsgHD.jpg', '/aU5eWmxfzuNIFJFOZZI0uwTUzDa.jpg', 7.6, '7TdoJWHnaLM', array['1001']::text[], 769, null, 'segura', null),
(118662, 'movie', 'Dekalog, Jeden', 'Decálogo 1', 'Dekalog, jeden', 1989, 'Krzysztof Kieślowski', '"Amarás a Dios sobre todas las cosas". Después de haberse separado de su mujer, un profesor universitario vive con su hijo Pavel al que procura transmitir su racionalidad y ateísmo. También le ha parecido conveniente enseñarle a usar el ordenador. Primero de los diez mediometrajes realizados por el director Krzysztof Kieslowski y el guionista Krzysztof Piesiewicz. Primera parte del "Decálogo", que se inspira en cada uno de los Diez Mandamientos.', '/h3kJ2UXkZSUzfQAAjcRwl6qNIpc.jpg', '/aldfhBj8nq2GLYr8qozR1u0G2NY.jpg', 8.1, null, array['1001']::text[], 770, null, 'segura', null),
(562, 'movie', 'La jungla de cristal', 'Jungla de cristal', 'Die Hard', 1988, 'John McTiernan', 'John McClane, un duro policía neoyorquino, acude a Los Angeles para pasar unos días de vacaciones con sus hijos y su esposa Holly. En el transcurso de la fiesta navideña que la empresa de Holly da en el moderno edificio Nakatoni, éste es asaltado por un supuesto grupo terrorista liderado por un megalómano llamado Hans Gruber.', '/m54tK4wKjc1w2dp7QInG0munGao.jpg', '/bvk2AAH64lP2YZs02Q3jskfHT8j.jpg', 7.8, '4Wi28Vsi_ZU', array['1001']::text[], 771, null, 'segura', null),
(97035, 'movie', 'histoire de vent, Une', 'Une histoire de vent', 'Une histoire de vent', 1989, 'Joris Ivens, Marceline Loridan-Ivens', 'It is an autobiographical fiction starring Ivens as an old man who has spent his life trying to "tame the wind and harness the sea" by capturing them on film.', '/7239j9sBDsKF35gaUZURkFeXjVd.jpg', '/sVnCg03eTCQIN2aSblm8oinbakG.jpg', 6.5, null, array['1001']::text[], 772, null, 'probable', '[{"tmdb_id": 97035, "titulo": "Une histoire de vent", "original": "Une histoire de vent", "anio": 1989, "votos": 36, "poster_path": "/7239j9sBDsKF35gaUZURkFeXjVd.jpg", "sim": 0.8}]'::jsonb),
(856, 'movie', '¿Quién engañó a Roger Rabbit?', '¿Quién engañó a Roger Rabbit?', 'Who Framed Roger Rabbit', 1988, 'Robert Zemeckis', 'Hollywood, 1947. Eddie Valiant, un detective de poca monta, ha sido contratado para encontrar pruebas que demuestren que Marvin Acme, magnate del negocio de los artículos de broma y dueño de Toontown, está rondando a Jessica Rabbit, mujer fatal y esposa de la superestrella del Marron Cartoon, Roger Rabbit. Cuando Acme aparece asesinado, todas las pruebas apuntan a Roger, y el siniestro y ambicioso Juez Doom está decidido a condenarlo como sea. Roger suplica a Valiant que le ayude a encontrar al verdadero culpable, pero el asunto se irá complicando a medida que Eddie va descubriendo, escándalo tras escándalo, que la propia existencia de Toontown corre peligro.', '/nXqhkF0tJ1K2fglVMgimVZd5kMH.jpg', '/udIE8Cdon9wnYmVIOFYrBPfA2Mq.jpg', 7.5, 'XEIJpS26aAw', array['1001']::text[], 773, null, 'segura', null),
(380, 'movie', 'Rain Man', 'Rain Man', 'Rain Man', 1988, 'Barry Levinson', 'Charlie Babbitt, un joven sin corazón, espera recibir una considerable herencia tras la muerte de su padre, del que estaba distanciado. Sin embargo, alguien a quien Charlie no ha tenido en absoluto en cuenta, su hermano mayor Raymond, recluido en una institución medica, recibe toda la fortuna del testamento. Raymond es un autista con capacidad mental limitada en algunos aspectos, pero con dotes de genio en otros.', '/mPX2v7MbalB9FbGsUylKW91J68E.jpg', '/b3tos7Tsd6lsTe52Nn4TMrEQg65.jpg', 7.7, 'wwmctS4nldM', array['1001']::text[], 774, null, 'segura', null),
(41975, 'movie', 'Asunto de mujeres', 'Asunto de mujeres', 'Une affaire de femmes', 1988, 'Claude Chabrol', 'Segunda Guerra Mundial (1939-1945). La vida en la Francia ocupada es muy difícil. Marie Latour, una mujer casada, decide ayudar a una vecina a interrumpir un embarazo no deseado. Poco a poco empiezan a requerir sus servicios otras mujeres encintas, bien porque han sido violadas, bien porque sus maridos están en el frente. Mientras tanto, el marido de Marie, que permanece en casa debido a una herida de guerra, contempla sorprendido cómo mejora la economía familiar.', '/xmyvvgC7EDZU2ISjfDqmhDz3F6k.jpg', '/uVyHoOtk7N1e3aEoHIuJbT6IBJg.jpg', 7.3, 'lyUi4u541ro', array['1001']::text[], 775, null, 'segura', null),
(27362, 'movie', 'Conspiración de mujeres', 'Conspiración de mujeres', 'Drowning by Numbers', 1988, 'Peter Greenaway', 'Narra la historia de tres generaciones de mujeres que, además de compartir el mismo nombre, Cissie Colpitts, también tuvieron las tres que lidiar con sus problemas matrimoniales. La primera Cissie Colpitts decidió acabar con su adúltero marido ahogándolo en una bañera. El forense local la encubre certificando un suicidio a condición de que la mujer se case con él, pero ella no está dispuesta a acceder. Tiempo después, la acción de la abuela tendrá sus consecuencias en su hija y nieta.', '/9gUlctisXf7LrLNLk1OQ9pl3VwE.jpg', '/8HiCwYGET0rHwAQnMridjgPD2uk.jpg', 7.0, '5tBxhzpFO1M', array['1001']::text[], 775, null, 'segura', null),
(18917, 'movie', 'Alice (Neco z Alenky)', 'Alice', 'Něco z Alenky', 1988, 'Jan Švankmajer', 'Después de haber leído el cuento de Lewis Carroll, Alicia se queda dormida en su cuarto rodeada de sus juguetes, y en sueños es transportada al País de las Maravillas. A medida que persigue al escurridizo Conejo Blanco, vive peligrosas aventuras en las profundidades del Reino de la Niñez, que culminan con el juicio a que es sometida en la corte del Rey y la Reina de Corazones. (FILMAFFINITY)', '/n2ADoAKoqBZiPDKTiTgliXlW9ro.jpg', '/jExkMK7bByCh4AjpEa4eOixtnUt.jpg', 7.4, 'Nxugr1jEYj8', array['1001']::text[], 776, null, 'segura', null),
(268, 'movie', 'Batman', 'Batman', 'Batman', 1989, 'Tim Burton', 'Atormentado por haber visto morir a sus padres delante suyo, Bruce Wayne se enfunda cada noche en el traje de Batman, adopta la terrorífica forma de un murciélago y surca los tejados de Gotham City combatiendo el crimen y manteniendo a raya la corrupción de su ciudad. Pero esta vez Batman tendrá que enfrentarse a su más terrible enemigo, El Joker, que pretende someter a toda la ciudad bajo los deseos de su mente perturbada.', '/fpY5cNPIbKYpdBtukCMtBMMt1s3.jpg', '/rhc7OF7tC9HPu0X8DBKQJzaGRbu.jpg', 7.2, 'EtI74GCT3IU', array['1001']::text[], 776, null, 'segura', null),
(639, 'movie', 'Cuando Harry encontró a Sally', 'Cuando Harry encontró a Sally', 'When Harry Met Sally...', 1989, 'Rob Reiner', 'Harry Burns y Sally Albright se conocen fortuitamente cuando ella se ofrece para llevarle en su coche hasta la ciudad, entablan una conversación sobre la amistad entre personas de diferente sexo; la conversación acaba en discusión, pero entre ellos nace algo muy especial. Son un hombre y una mujer que se han pasado mucho tiempo intentando averiguar cómo seguir siendo amigos. Sin embargo, Harry tiene una firme creencia: que dos personas de sexo opuesto no pueden ser simplemente amigos, la relación siempre acaba en la cama o en el altar.', '/dHUhjAPViRGTU9CFBt4JoANWHiK.jpg', '/xd5SYDUhNVGLUeK2epbEjnVBpPN.jpg', 7.4, 'Lv8W7PPpkdo', array['1001']::text[], 777, null, 'segura', null),
(11562, 'movie', 'Delitos y faltas', 'Delitos y faltas', 'Crimes and Misdemeanors', 1989, 'Woody Allen', 'Un médico neoyorquino decide tomar medidas desesperadas cuando su amante le amenaza con sacar a la luz su aventura si no se casa con ella. Cuando su hermano se ofrece para eliminar el problema, se enfrenta a un dilema moral. Paralelamente, a Clifford Stern le encargan hacer un documental sobre su cuñado Lester, un famoso productor de televisión que personaliza todo lo que Clifford desprecia.', '/ptBljoTY9KrAIOZcULsIs2J3fGc.jpg', '/xDPaSuwaOizRNPitEvNiuY7i6iE.jpg', 7.4, 'JBzlQ7bUtKk', array['1001']::text[], 778, null, 'segura', null),
(476, 'movie', 'Drugstore Cowboy', 'Drugstore Cowboy', 'Drugstore Cowboy', 1989, 'Gus Van Sant', 'Portland, Oregon, 1971. Bob Hughes es el carismático líder de un peculiar cuarteto, formado por su esposa, Dianne, y otra pareja, Rick y Nadine, que roban con suma habilidad en farmacias y hospitales con objeto de apaciguar su insaciable necesidad de drogas. Pero ni la diversión ni la suerte duran para siempre.', '/1URuvqnZcwL4wy8hIIwQ9p9AxVq.jpg', '/zf52xLEyao2xcVnpThmzW2Xl0aj.jpg', 7.1, '5_Rs8c08hM8', array['1001']::text[], 779, null, 'segura', null),
(7452, 'movie', 'El cocinero, el ladrón, su mujer y su amante', 'El cocinero, el ladrón, su mujer y su amante', 'The Cook, the Thief, His Wife & Her Lover', 1989, 'Peter Greenaway', 'Albert es el sádico dueño de un restaurante. Su fuerte carácter y las tiránicas formas que aplica en el trabajo hacen que todos los empleados estén sometidos a un continuo régimen de esclavitud, incluida su esposa, Giorgina, a quien ridiculiza.', '/dpkUfqxjSmGYQI2GOWhk7V9ii5C.jpg', '/rzaf3eCT8pVCGvuS7P8g2nPitqC.jpg', 7.3, 'gxpQomMfvIM', array['1001']::text[], 779, null, 'segura', null),
(10161, 'movie', 'Mi pie izquierdo', 'Mi pie izquierdo', 'My Left Foot: The Story of Christy Brown', 1989, 'Jim Sheridan', 'Christy Brown es un enfermo de parálisis cerebral, nacido en el seno de una numerosa y mísera familia irlandesa. Su madre es la única que lo ve como un chico con talento y sensibilidad. Con el tiempo, Christy se revela como un irascible pero talentoso escritor y pintor, que utiliza su pie izquierdo -la única parte de su cuerpo que tiene motricidad- como instrumento.', '/zhBhzNvUbIqjl2xDmwuTPmDNwYi.jpg', '/zjKg04EquTcnVZUfjHboXnXzjcF.jpg', 7.5, 'ckxjGhC90V0', array['1001']::text[], 780, null, 'segura', null),
(10835, 'movie', 'Los asesinos (Die xue shuang xiong)', 'The Killer (El asesino)', '喋血雙雄', 1989, '吴宇森', 'Sin abandonar su particular estilo que combina el melodrama al más puro estilo Douglas Sirk con la violencia de Peckinpah, el director asiático John Woo consigue su obra maestra dentro del género de acción "made in Hong Kong": una violencia desatada irrumpe tras momentos de calma.', '/8hTxlSqMAHBXAh1eB69ir0BXhzE.jpg', '/jetidiki3UjVJEpFwcK2kUrvoR5.jpg', 7.6, 'bdLwJ2-zxDA', array['1001']::text[], 781, null, 'probable', '[{"tmdb_id": 10835, "titulo": "The Killer (El asesino)", "original": "喋血雙雄", "anio": 1989, "votos": 960, "poster_path": "/8hTxlSqMAHBXAh1eB69ir0BXhzE.jpg", "sim": 0.432}, {"tmdb_id": 16296, "titulo": "Payasos asesinos del espacio exterior", "original": "Killer Klowns from Outer Space", "anio": 1988, "votos": 1244, "poster_path": "/vqQoDP43QNJaQFv0KMqilm62X3C.jpg", "sim": 0.356}, {"tmdb_id": 15482, "titulo": "El retorno de los tomates asesinos", "original": "Return of the Killer Tomatoes!", "anio": 1988, "votos": 259, "poster_path": "/6KSRdrlNekMaOxUzLxVh7JBoKPQ.jpg", "sim": 0.41}, {"tmdb_id": 26954, "titulo": "La venganza de los muñecos (Muñecos asesinos)", "original": "Puppet Master II", "anio": 1990, "votos": 226, "poster_path": "/iUUriLJPEhVAVPADGdIZktTrKQW.jpg", "sim": 0.333}]'::jsonb),
(925, 'movie', 'Haz lo que debas', 'Haz lo que debas', 'Do the Right Thing', 1989, 'Spike Lee', 'En uno de los barrios más humildes de Brooklyn, Bedford Stuyvesant, conviven atropelladamente varias familias de raza negra, algunos hispanos, una pareja de comerciantes vietnamitas y una familia de italoamericanos que tienen una pizzeria. Mookie, un chico que trabaja de repartidor de pizzas, es un testigo privilegiado de los personajes y de los hechos cotidianos que tienen lugar en el barrio, así como de las tensiones y las actitudes racistas de algunos de sus habitantes', '/fu5kXCAX9xcjpCSeEROYZ3iBdLb.jpg', '/xnLh9CNRxkpkSNikVhi5qLwcfUG.jpg', 7.8, 'yVAD4fYRcvA', array['1001']::text[], 782, null, 'segura', null),
(1779, 'movie', 'Roger & Me', 'Roger y yo', 'Roger & Me', 1989, 'Michael Moore', 'Aclamado documental que arremete contra el poder de las grandes corporaciones industriales, en las que el incorruptible Michael Moore trata de conseguir una entrevista con Roger B. Smith, presidente de General Motors, para poder preguntarle sobre las devastadoras consecuencias del cierre de una planta del gigante del automóvil.', '/vSi4YK4E63geptUAxtizRUeTCFu.jpg', '/1TFrt5rlgbAS7WdHfCp142NPt4s.jpg', 7.1, 'xPNmHPjkxdk', array['1001']::text[], 784, null, 'segura', null),
(9665, 'movie', 'Tiempos de gloria', 'Tiempos de gloria', 'Glory', 1989, 'Edward Zwick', 'A principios de la Guerra de Secesión, el ejército del norte se mostraba reticente a dar armas a los negros. El heroico comportamiento del regimiento de Massachusetts, formado por soldados afroamericanos y oficiales blancos, resultó decisivo para que la Unión abriera las puertas a 180.000 soldados negros.', '/f2sKUHfBLTCUuGogGKUR7zqlk7D.jpg', '/3yHddfnAwI1kWOGjoQXZoqhnU5Z.jpg', 7.5, '-OS-OE1EcHI', array['1001']::text[], 784, null, 'segura', null),
(97039, 'movie', 'Astenicheskij sindrom (Síndrome de astenia)', 'El síndrome asténico', 'Астенический синдром', 1989, 'Кіра Муратова', 'Retrato profundo e ingenioso de la «condición humana» que afligía a la sociedad rusa contemporánea.', '/h85XgN7xI2DJ71YDvTatNbspZ4h.jpg', '/r0Hee2zRc9glDDOHapwfbjH5aG2.jpg', 5.7, null, array['1001']::text[], 785, null, 'probable', null),
(1412, 'movie', 'Sexo, mentiras y cintas de vídeo', 'Sexo, mentiras y cintas de vídeo', 'sex, lies, and videotape', 1989, 'Steven Soderbergh', 'John, un abogado yuppie, con pocos escrúpulos, está casado con Ann, una mujer seria e introvertida. Ella, aunque muestra poco interés por el sexo, se siente segura de su matrimonio. John, en cambio, es un adicto al sexo y tiene una aventura con Cinthia, la extrovertida y desenfadada hermana de Ann. La llegada del enigmático Graham, un antiguo compañero de John en la universidad, alterará la vida de Ann.', '/8Qd8Q231kvgytjdLO1BV5ZG9bd9.jpg', '/wD95UmpUazo9820qnbbjRtbQ884.jpg', 7.0, '6BMZrfINaUk', array['1001']::text[], 786, null, 'segura', null),
(38545, 'movie', 'La increíble verdad', 'La increíble verdad', 'The Unbelievable Truth', 1990, 'Hal Hartley', 'Josh (Robert Burke) es un ex presidiario que, tras salir de la cárcel con las mejores intenciones, regresa a su hogar natal en Lindenhurst, Long Island. Allí es contratado como mecánico por Vic Hugo (Christopher Cooke), el dueño de un garaje, y se enamora de su hija Audry (Adrienne Shelly)... Película que supuso el debut de uno de los más admirados directores del cine independiente de los noventa. Rodada con poquísimo presupueto y apenas 11 días de rodaje.', '/36Gqgyh1nOguvnIH8RBfhj7EpjH.jpg', '/sKE6dfuO56T0xq88xuiHahuDDNA.jpg', 6.8, 'iZpuazT6MrA', array['1001']::text[], 787, null, 'segura', null),
(2028, 'movie', 'Un gran amor...', 'Un gran amor', 'Say Anything...', 1989, 'Cameron Crowe', 'Lloyd Dobler, un eterno optimista, busca conseguir el corazón de Diane Court, una inalcanzable belleza del instituto, además de una intachable estudiante. Todo el mundo se sorprende, incluido Lloyd, cuando ella demuestra que el sentimiento es recíproco. Pero el posesivo padre divorciado de Diane no aprueba esa relación, y hará falta algo más que el poder del amor para que consigan seguir juntos.', '/kUlRGwaY1xFhseehoCosSfoNKm8.jpg', '/bAdIO0Jt886Ad1eY9bDXXeCpXsV.jpg', 7.0, 'Se_eSeEAoX0', array['1001']::text[], 787, null, 'segura', null),
(49982, 'movie', 'Ciudad de la tristeza (Beiqing chengshi)', 'Ciudad doliente', '悲情城市', 1989, 'Hou Hsiao Hsien', 'Las tribulaciones de una familia en Taiwán -el padre y sus cuatro hijos-, tras la violenta represión china acontecida en febrero de 1947. Primera parte de la trilogía de la historia de Taiwan realizada por Hsiao-hsien Hou. Las siguientes entregas serían "The Puppetmaster" (1993) y "Good Men, Good Women" (1995).', '/vawQltR9OiAows3WEyKarHUM662.jpg', '/fClREI48zqOyESHlP5SZAgFfp3k.jpg', 7.5, 'caU7X7LV-5E', array['1001']::text[], 788, null, 'probable', '[{"tmdb_id": 49982, "titulo": "Ciudad doliente", "original": "悲情城市", "anio": 1989, "votos": 160, "poster_path": "/vawQltR9OiAows3WEyKarHUM662.jpg", "sim": 0.611}]'::jsonb),
(38718, 'movie', 'El misterio von Bülow', 'El misterio Von Bülow', 'Reversal of Fortune', 1990, 'Barbet Schroeder', 'Basada en hechos reales. Uno de los casos criminales más misteriosos de los últimos años fue la acusación y juicio del barón Claus von Bülow, en 1980, acusado de provocar el coma de su millonaria esposa por una sobredosis de insulina. Al enigmático aristócrata le defenderá un prestigioso abogado.', '/u4t5VSYdivg6Yvya3CwtKdMfriu.jpg', '/efFQxWf7EmhPwyXogl9JUXILgln.jpg', 6.7, 'KWWdt-NZwCA', array['1001']::text[], 789, null, 'segura', null),
(97041, 'movie', 'S''en fout la mort', 'S''en fout la mort', 'S''en fout la mort', 1990, 'Claire Denis', 'Dah and Jocelyn come from former French colonies to coach their rooster, "S''en fout la mort", for an illicit cock-fight in the basement of a restaurant.', '/bKB4tSBB0up9JuVi9AY9VmDsITh.jpg', '/oiDOntaJQyr9nSL0AwehUYAzrhh.jpg', 6.1, 'KeF1Gic2XVg', array['1001']::text[], 789, null, 'segura', null),
(769, 'movie', 'Uno de los nuestros', 'Uno de los nuestros', 'GoodFellas', 1990, 'Martin Scorsese', 'Henry, un niño de trece años de Brooklyn, vive fascinado con el mundo de los gángsters. Su sueño se hace realidad cuando entra a formar parte de la familia Pauline, dueña absoluta de la zona, que lo educan como un miembro más de la banda convirtiéndole en un destacado mafioso.', '/3Yy0zBO9AlyAZH1cTI8Ko2ouCi.jpg', '/gILte6Zd7m1YneIr6MVhh30S9pr.jpg', 8.5, 'Shj-QWYDn_M', array['1001']::text[], 790, null, 'segura', null),
(9558, 'movie', 'El rey de Nueva York', 'El rey de Nueva York', 'King of New York', 1990, 'Abel Ferrara', 'Violento film de gángsters que relata los intentos de un traficante de drogas por recuperar su "territorio" perdido mientras cumplía prisión. En Nueva York el crimen se hace a la manera de Frank o no se hace. Recién salido de la prisión, Frank White se reúne con su antigua banda para retomar su posición como "señor de la droga" de la ciudad. Se enfrentarán en sangrientas batallas al resto de capos de la ciudad y lucharán por estar en la cima. Incapaces de volver a poner a Frank entre rejas, la policía también les declara la guerra.', '/ogU1DgalBtVNNiKP4t6LPDjyaij.jpg', '/4SqkcTDow3cgXUsN2DC2RETbhAZ.jpg', 6.8, 'bt94pENFmjc', array['1001']::text[], 791, null, 'segura', null),
(2291, 'movie', 'La escalera de Jacob', 'La escalera de Jacob', 'Jacob''s Ladder', 1990, 'Adrian Lyne', 'El cartero neoyorkino Jacob Singer intenta evitar que los jirones de su vida terminen de deshilacharse. Lo acosan incesantes flashbacks de su primer matrimonio, de su hijo muerto y de su periodo de servicio en Vietnam. En su nueva esposa busca un asidero hacia la lucidez, pero la línea entre la realidad y el delirio se hace cada vez más delgada. Tim Robbins protagoniza una escalofriante historia de un hombre que desciende al infierno, brillantemente dirigida por Adrian Lyne.', '/1wSyCFk53Xx7kVU76bLEDWk6BgA.jpg', '/oubk1SEFtg3Q8eOncFvGQVa6OoP.jpg', 7.4, '2AiwCLI04PY', array['1001']::text[], 791, null, 'segura', null),
(581, 'movie', 'Bailando con lobos', 'Bailando con lobos', 'Dances with Wolves', 1990, 'Kevin Costner', 'En torno a 1860, en vísperas de la Guerra de Secesión y a punto de terminar el periodo de colonización del Oeste (1785-1890), el teniente John J. Dunbar se dirige a un lejano puesto fronterizo que ha sido abandonado por los soldados. Su soledad lo impulsa a entrar en contacto con los indios sioux y, gracias a ello, conoce a ''En pie con el puño en alto'', una mujer blanca que fue adoptada por la tribu cuando era niña. Poco a poco, entre Dunbar y los sioux se establece una relación de respeto y admiración mutuos.', '/NYzUSchNAs0Q3K2ebPRvkPrlrs.jpg', '/ywWva4trKw7f3wtbz81Fe3FnrtC.jpg', 7.8, 'g2P5QuLP7GE', array['1001']::text[], 792, null, 'segura', null),
(8996, 'movie', 'Europa, Europa', 'Europa, Europa', 'Europa Europa', 1990, 'Agnieszka Holland', 'Al estallar la Segunda Guerra Mundial, Solomon Perel, un joven judío polaco, fue internado en un orfanato soviético. Más tarde fue reclutado por los alemanes, que desconocían su identidad, y se convirtió, involuntariamente, en un héroe del ejército nazi.', '/9sAEpmmfpx74gh7IPdKVJ1rLupZ.jpg', '/puTxjGPJALnjxXsO2k5OEHzf1ME.jpg', 7.2, 'JqMBNCo7LPE', array['1001']::text[], 793, null, 'segura', null),
(114, 'movie', 'Pretty Woman', 'Pretty Woman', 'Pretty Woman', 1990, 'Garry Marshall', 'Un acaudalado y frío hombre de negocios conoce en Hollywood Boulevard a una joven y atractiva prostituta a la que alquila durante una semana para que sea su acompañante en sus cenas con los clientes. Para ello la chica se verá sometida a todo un cambio de look tras el que nadie podrá ver, a simple vista, que es una chica de la calle.', '/iKaKr8aUqOy1aojENu5XuwBI8Uj.jpg', '/rleTwPqymtOpeD2bR7asJGEmldV.jpg', 7.4, 'zZPnhcuXfL4', array['1001']::text[], 794, null, 'segura', null),
(85559, 'movie', 'Archangel', 'Arcángel', 'Archangel', 1990, 'Guy Maddin', 'Un combatiente de la I Guerra Mundial que ha perdido, además de una pierna, a su prometida durante la contienda, se dispone a desembarcar en Archangel, un apartado puerto ruso al que aún no ha llegado la noticia del fin de la guerra.', '/fatUPhfZZAs2f8zW6heo1C6yne.jpg', '/cdgRgfed3CYr7Q1JR8r32A0RXgS.jpg', 5.5, '-2bBKhWVpvg', array['1001']::text[], 795, null, 'segura', null),
(37291, 'movie', 'Trust', 'Trust (Confía en mí)', 'Trust', 1990, 'Hal Hartley', 'Es una comedia urbana y mordaz, ambientada en un barrio de clase media norteamericano, en el que confluyen la violencia, los milagros y toda clase de peripecias. María es una estudiante a la que su novio, que sólo piensa en triunfar en el deporte, ha dejado embarazada. Cuando su padre se entera, muere de un infarto. Mathew es un especialista en electrónica: fatalista, desilusionado y violento. Repudiada por su madre y por su novio, María se cruza con Mathew, cuando acaba de abandonar violentamente su trabajo y la casa de su padre, un hombre riguroso y obsesivo. En poco tiempo se convierten en una pareja estable, pero ya se encargará la vida de demostrarles que las cosas no son tan sencillas como parecen.', '/djwnVTSdCiVvHiV2iJzXLnAuJDJ.jpg', '/kclghqLepNi2ysevncFTUw0qglH.jpg', 6.8, 'pIgv4Tvx3V0', array['1001']::text[], 795, null, 'segura', null),
(30017, 'movie', 'Primer plano', 'Primer plano', 'کلوزآپ ، نمای نزدیک', 1990, 'Abbas Kiarostami', 'El iraní Abbas Kiarostami mezcla documental y drama a través de una historia en el que un fanático del cine finge ser el reputado director Mohsen Makmalbaf.', '/bqdgN0SE5qbRXFPoaOPRj0yNv9X.jpg', '/3t1qZqP1e17wQshpPKSqII1OogM.jpg', 8.0, 'YeFZ448yQ-0', array['1001']::text[], 796, null, 'segura', null),
(162, 'movie', 'Eduardo Manostijeras', 'Eduardo Manostijeras', 'Edward Scissorhands', 1990, 'Tim Burton', 'Érase una vez... un castillo donde vivía un inventor que dedicó parte de su vida a crear una criatura perfecta a la que llamó Edward. Pero el inventor murió de repente y dejó incompleta su creación, ya que en vez de dedos tenía unas horribles manos con hojas de tijera. El pobre Edward vivía sólo en el castillo hasta que una encantadora joven, que trabajaba para la firma Avon, lo llevó a su casa junto con su familia. Pero una criatura tan especial como Edward no estaba preparada para vivir en una ciudad tan extravagante y falsa como Suburbia.', '/vd8tCekihFx82bzmENaASvbhNmx.jpg', '/uNLIMPxknsV4n3IAEDpS1iqF5dm.jpg', 7.7, 'nfJPYIfT2-U', array['1001']::text[], 797, null, 'segura', null),
(11364, 'movie', 'Henry: retrato de un asesino', 'A propósito de Henry', 'Regarding Henry', 1991, 'Mike Nichols', 'Un abogado implacable y de mal carácter sufre un atraco y le disparan. A partir de ese momento, amnésico, deberá reconstruir su vida y sus recuerdos con la ayuda de su familia.', '/gnv0TC1xlXUiwtv3uiOyN1gduim.jpg', '/8QZMXIjksrlIQ5BZLtVpUnhh09Z.jpg', 6.5, 'PtipW0DoQBs', array['1001']::text[], 798, null, 'probable', '[{"tmdb_id": 11364, "titulo": "A propósito de Henry", "original": "Regarding Henry", "anio": 1991, "votos": 657, "poster_path": "/gnv0TC1xlXUiwtv3uiOyN1gduim.jpg", "sim": 0.5}, {"tmdb_id": 10705, "titulo": "Enrique V", "original": "Henry V", "anio": 1989, "votos": 425, "poster_path": "/1eyhVB5ZBSb7l95ptFmZ57hXxUA.jpg", "sim": 0.833}, {"tmdb_id": 17993, "titulo": "Henry y June (El diario íntimo de Anaïs Nin)", "original": "Henry & June", "anio": 1990, "votos": 243, "poster_path": "/8sxQBq9B1u9KUhNZkdqNIbiHA62.jpg", "sim": 0.667}, {"tmdb_id": 235202, "titulo": "Henry''s Romance", "original": "Der grüne Heinrich", "anio": 1993, "votos": 8, "poster_path": "/6xvWWzDdSD7yJzbohEnnkbhhdlQ.jpg", "sim": 0.5}]'::jsonb),
(861, 'movie', 'Desafío total', 'Desafío total', 'Total Recall', 1990, 'Paul Verhoeven', 'Tierra, año 2084. Doug Quaid, un hombre normal con una vida tranquila, está atormentado por una pesadilla que le lleva todas las noches hasta Marte. Decide entonces recurrir al laboratorio Memory-call, una empresa de vacaciones virtuales que le ofrece la oportunidad de materializar su sueño gracias a un fuerte alucinógeno. Sin embargo, su intento resulta en fracaso. La droga resucita de su memoria una estancia verdadera en Marte cuando era el más temido agente del cruel Coohagen.', '/v7DoneFNYIrCGeNFiPrqGiQlimN.jpg', '/x2wOlXuK4NzPDQ0OBZiJjNNOp6Y.jpg', 7.3, 'KfY3vF_HMBU', array['1001']::text[], 799, null, 'segura', null),
(812748, 'movie', 'Wong Fei-Hung', '소년 황비홍', '소년 황비홍', 1993, '김봉은', 'Children''s martial arts movie telling the story of young Wong Fei-Hung and the first sword in the world. Action direction by Won Jin, known widely for his performance as Sonny Wong in The Scorpion King.', '/sotsGFClodCNipvqAdjzzQ6UWHZ.jpg', null, 4.0, null, array['1001']::text[], 799, null, 'dudosa', '[{"tmdb_id": 812748, "titulo": "Boy Wong Fei-Hung", "original": "소년 황비홍", "anio": 1993, "votos": 1, "poster_path": "/sotsGFClodCNipvqAdjzzQ6UWHZ.jpg", "sim": 0.867}, {"tmdb_id": 10617, "titulo": "Once Upon a Time in China", "original": "黃飛鴻", "anio": 1991, "votos": 511, "poster_path": "/dkBQC0jmkmTOJJMgwsBdgkzZ6Ry.jpg", "sim": 0.421}, {"tmdb_id": 12780, "titulo": "El mono de hierro (Iron Monkey)", "original": "黃飛鴻之鐵馬騮", "anio": 1993, "votos": 342, "poster_path": "/x2ABL4L85wberIHaz2vyJ8Y1oNL.jpg", "sim": 0.359}, {"tmdb_id": 10618, "titulo": "Once Upon a Time in China II", "original": "黃飛鴻之二：男兒當自強", "anio": 1992, "votos": 301, "poster_path": "/jvrQXnpgSpKXQ3fkz5p6RV8jZJa.jpg", "sim": 0.39}]'::jsonb),
(650, 'movie', 'Los chicos del barrio', 'Los chicos del barrio', 'Boyz n the Hood', 1991, 'John Singleton', 'Sorprendente debut del jovencísimo John Singleton -nominado al Oscar al mejor director con sólo 21 años- en un drama que cuenta la historia de tres amigos de la infancia que viven en un peligroso barrio de Los Ángeles. Los tres deberán enfrentarse a difíciles dilemas para abrirse camino en la vida.', '/wcHEyW05V0PH4b1bLo47nTIp1oX.jpg', '/ojzo9tMl8ZLrQgdGApZJFLuS331.jpg', 7.6, '5WS77WptcxI', array['1001']::text[], 800, null, 'segura', null),
(892, 'movie', 'Delicatessen', 'Delicatessen', 'Delicatessen', 1991, 'Jean-Pierre Jeunet, Marc Caro', 'Esta comedia negra y surrealista nos cuenta acerca de un pequeño pueblo postapocalíptico, donde Clapet, el carnicero, alimenta a sus clientes con carne humana. Cuando su hija se enamora de su siguiente víctima, las cosas se empiezan a torcer.', '/cACoQdccxToUn0PRC1yW81bZHOG.jpg', '/A3qvUUd36LUF5sfPYOHEd3ahDp2.jpg', 7.3, 'GVL5_I4CvTc', array['1001']::text[], 802, null, 'segura', null),
(10404, 'movie', 'La linterna roja', 'La linterna roja', '大红灯笼高高挂', 1991, 'Zhang Yimou', 'La película nos muestra la vida de las cuatro esposas de un hombre rico que viven en una gran casa. El hombre es el dueño y señor y las mujeres son de su propiedad y cada día elige a una de ellas para pasar la noche, mediante la colocación de una gran linterna roja en la puerta de la habitación de la mujer escogida. Este rito da lugar al título y provoca las mejores situaciones de la película, al reflejar la tensión y la rivalidad producida en las mujeres cada atardecer, cuando esperan en las puertas de sus habitaciones ver en cúal de ellas lucirá esa noche la lámpara. Esas cuatro paredes, este patio interior, típico de las casas chinas, se convierten en un microuniverso -que no quiere saber que fuera hay otras alternativas- en el que hasta el más pequeño detalle adquiere la mayor relevancia.', '/dze5P1wHqxSH4vt98zVTbeUKugi.jpg', '/9UCHfC9tYojD4mMVBm0boyzYEQq.jpg', 8.0, 'tLYJzEtmavg', array['1001']::text[], 802, null, 'segura', null),
(15804, 'movie', 'Una radiante mañana estival (Guling jie shaonian sha ren shijian)', 'Un día de verano', '牯嶺街少年殺人事件', 1991, '楊德昌', 'Taiwan, años ''60. Los jóvenes taiwaneses, aunque dominados por China, se sienten deslumbrados por los Estados Unidos y organizan bandas para afirmar su identidad. La versión original duraba 237 minutos, pero por motivos comerciales Yang la recortó para su exhibición hasta los 188 minutos.', '/gXvyDspzokDAjG0C3rSrszTj12j.jpg', '/hypv7bDxzqdhJfEpjRKf1aQbdc.jpg', 8.2, 'nsiqbT5adO0', array['1001']::text[], 803, null, 'probable', '[{"tmdb_id": 15804, "titulo": "Un día de verano", "original": "牯嶺街少年殺人事件", "anio": 1991, "votos": 414, "poster_path": "/gXvyDspzokDAjG0C3rSrszTj12j.jpg", "sim": 0.25}]'::jsonb),
(2742, 'movie', 'El almuerzo desnudo', 'El almuerzo desnudo', 'Naked Lunch', 1991, 'David Cronenberg', 'Después del trágico accidente sufrido por su mujer, un escritor que cae en la adicción a ciertas drogas, empieza a sufrir horribles alucinaciones que lo transportan a un mundo de pesadilla absolutamente kafkiano.', '/HzpDsHbgJWqBlmN5bpnHAhCDMF.jpg', '/mBteXONDhdVyXRNxj54eMNGNqyT.jpg', 7.0, 'nj04OcONu2s', array['1001']::text[], 804, null, 'segura', null),
(1411, 'movie', 'El despertar de Sharon', 'El despertar de Sharon', 'The Rapture', 1991, 'Michael Tolkin', 'Sharon es una joven de Los Ángeles que trabaja en una aburrida oficina. Por la noche ella y un compañero se pasean por los bares para ligar con otras parejas y hacer intercambios, satisfaciendo así sus fantasías. Sharon renuncia a su monótona vida y se aferra al fundamentalismo con pasión. Se casa con uno de sus amantes, Randy, quien le traspasa el fervor evangélico que le ayuda a superar su pasado como asesino.', '/4EkFm13ecqO0eszr7OKT8vf1YjJ.jpg', '/ylXFsNIhzq8A5nEqLhPdDYPOnVo.jpg', 5.7, 'QuttvF_nf48', array['1001']::text[], 805, null, 'segura', null),
(12627, 'movie', 'La bella mentirosa', 'La bella mentirosa', 'La Belle Noiseuse', 1991, 'Jacques Rivette', 'Nicholas, un joven artista parisino, viaja con su novia Marianne a un pequeño pueblo de provincias para visitar a Edouard Frenhofer, un famoso pintor que vive allí aislado del mundo. Nicholas intenta persuadirlo para que pinte su último gran cuadro: "La bella mentirosa", con su novia como modelo.', '/rRQSSe6G7exoGs2pvJc2HIMvaIQ.jpg', '/bFXrPXV6GjWK5mQZYMncve0bisi.jpg', 7.3, 'wtfsLeDXlpg', array['1001']::text[], 805, null, 'segura', null),
(468, 'movie', 'Mi Idaho privado', 'Mi Idaho privado', 'My Own Private Idaho', 1991, 'Gus Van Sant', 'Mike Waters (River Phoenix) y Scott Favor (Keanu Reeves) son dos jóvenes chaperos que se ganan la vida prostituyéndose en las calles de Portland. Mike tiene una extraña enfermedad llamada narcolepsia, que le provoca un sueño repentino y profundo en cualquier parte.', '/7D08WRTWi5ZGJvBmMW64W4H6dE2.jpg', '/stSaFz5CtMXwIj3r4MDjqxqWRot.jpg', 7.0, 'cNENMVQfOus', array['1001']::text[], 806, null, 'segura', null),
(280, 'movie', 'Terminator 2: el día del juicio', 'Terminator 2: El juicio final', 'Terminator 2: Judgment Day', 1991, 'James Cameron', 'Ha pasado once años desde que Sarah Connor fue marcada como objetivo para ser eliminada por un cyborg del futuro. Ahora su hijo John, el futuro líder de la resistencia, es el objetivo de un Terminator más moderno, más mortífero. Una vez más, la resistencia se las ha ingeniado para enviar un protector de vuelta al pasado para intentar salvar a John y a su madre Sarah.', '/10xtoK2SFv6ADIeWxr3mcrjko72.jpg', '/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg', 8.2, 'VQd38bFMoIg', array['1001']::text[], 808, null, 'segura', null),
(1541, 'movie', 'Thelma y Louise', 'Thelma & Louise', 'Thelma & Louise', 1991, 'Ridley Scott', 'Thelma Dickinson, un ama de casa de vida vacía y anodina, está casada con un cretino detestable que la trata como a una niña. Por su parte, Louise Sawyer trabaja como camarera en una cafetería y sueña con que su novio Jimmy, que es músico, se case con ella. Un fin de semana deciden hacer un viaje juntas en el coche de Louise para alejarse de la mortal rutina de sus vidas y de todas sus frustraciones. Sin embargo, su escapada, que prometía ser divertida y, sobre todo, liberadora, acaba siendo una experiencia llena de episodios dramáticos.', '/zS4vosCL144152a1hlU2vbiv8cO.jpg', '/u49EZzHvGCNrHdQxkc3hhLmQEPP.jpg', 7.6, 'dZWffRsh_WI', array['1001']::text[], 808, null, 'segura', null),
(274, 'movie', 'El silencio de los corderos', 'El silencio de los corderos', 'The Silence of the Lambs', 1991, 'Jonathan Demme', 'Clarice Starling, del FBI, se aventura a una prisión de máxima seguridad para analizar el cerebro enfermo de Hannibal Lecter, un psiquiatra convertido en caníbal.', '/8FdQQ3cUCs9goEOr1qUFaHackoJ.jpg', '/mbOx1wxMLikzwWUO9TKAcFIy6op.jpg', 8.3, '5SKgu_gXPQ4', array['1001']::text[], 809, null, 'segura', null),
(820, 'movie', 'JFK, caso abierto', 'JFK: Caso abierto', 'JFK', 1991, 'Oliver Stone', 'El fiscal de Nueva Orleans, Jim Garrison, reabrió el caso del asesinato del presidente de los Estados Unidos John F. Kennedy y presentó cargos contra algunas personas. Después de entrevistar a numerosos testigos de Dallas y a personas relacionadas con los hechos, mantuvo la tesis de que el magnicidio fue fruto de una conspiración en la que podrían haber intervenido el FBI, la CIA y el propio vicepresidente Lindon B. Johnson.', '/14TrPHZxrrQfoIcmXpN7q9Y0WYP.jpg', '/77gjiDyD94aJfqZq6AJAcMLxZhd.jpg', 7.6, 's8az13Y1rUM', array['1001']::text[], 810, null, 'segura', null),
(14022, 'movie', 'Slacker', 'Slacker', 'Slacker', 1990, 'Richard Linklater', 'Richard Linklater y su cámara se pasean durante un día por la ciudad de Austin, en Texas, y aparece ante nuestros ojos toda una galería de personajes, aparentemente sin relación entre ellos; entre los que encontramos desocupados, intelectuales, músicos, delincuentes, viejos anarquistas o gente de la calle. (FILMAFFINITY)', '/f7Iov2nd0XX9bp2laQEPYPEhisc.jpg', '/1gjK6oZSQtvhFBbSgkBvn72dPLF.jpg', 6.7, 'EAdgIV7jDgU', array['1001']::text[], 812, null, 'segura', null),
(97049, 'movie', 'Lenguas desatadas', 'Lenguas desatadas', 'Tongues Untied', 1990, 'Marlon Riggs', 'Manifiesto-ensayo sobre la identidad afroamericana y gay que reivindica el amor entre hombres negros como un acto revolucionario. Convertido ya en un clásico de la no-ficción contemporánea por su estructura compleja, el uso de actores y de material de archivo, la inclusión de poemas recitados por el poeta Essex Hemphill y fragmentos autobiográficos del director, fue objeto de numerosos ataques en el Congreso de Estados Unidos y fue censurado en la televisión pública norteamericana.', '/wbrcRd695aB8D6pkWh0hSurKRbO.jpg', '/8Tvq2tkvr8LslXJpwjWPEap4BNa.jpg', 6.7, 'uut1FKNkvY4', array['1001']::text[], 813, null, 'segura', null),
(4539, 'movie', 'Hearts of Darkness: A Filmmaker''s Apocalypse', 'Corazones en tinieblas', 'Hearts of Darkness: A Filmmaker''s Apocalypse', 1991, 'George Hickenlooper, Fax Bahr, Eleanor Coppola', 'Documental que relata el largo y problemático rodaje de "Apocalypse Now", la obra maestra de Francis Ford Coppola sobre la guerra de Vietnam. Incluye abundante material inédito rodado por Eleanor Coppola, la mujer del director, con una cámara de 16 mm. El título alude a la novela de Conrad "Hearts of Darkness" (El corazón de las tinieblas), en la que se inspira la película. Obtuvo excelentes críticas.', '/oTHnI4vQAPOTyps8Al6r5kOWTtW.jpg', '/crw9RXI54qmSfc0tIiH5hip79uw.jpg', 7.9, 'NuxlYozLpeI', array['1001']::text[], 814, null, 'segura', null),
(1600, 'movie', 'La doble vida de Verónica', 'La doble vida de Verónica', 'La Double Vie de Véronique', 1991, 'Krzysztof Kieślowski', 'Weronika vive en Polonia y tiene una brillante carrera como cantante, pero padece una grave dolencia cardíaca. En Francia, a más de mil kilómetros, vive Véronique, otra joven idéntica que guarda muchas similitudes vitales con ella, como su enfermedad y su gran pasión por la música. Ambas, a pesar de la distancia y de no tener aparentemente ninguna relación, son capaces de sentir que no están solas.', '/6JlKQggwMaDy2lzDVb7dScninFM.jpg', '/vjsFyeCf5W5rxCFpS9MIAEZJkIG.jpg', 7.5, '_baGBH7_G4U', array['1001']::text[], 816, null, 'segura', null),
(10409, 'movie', 'Strictly Ballroom', 'El amor está en el aire', 'Strictly Ballroom', 1992, 'Baz Luhrmann', 'La Federación de Baile es una poderosa organización que no quiere que ninguno de sus miembros haga las cosas por su cuenta. Esta Federación tiene sus propias normas, entre las que estipula lo que se puede y lo que no se puede hacer en las salas de baile profesionales. Scott Hastings es un bailarín con mucho talento. Liz es su pareja de baile. Ambos se entienden a la perfección, y tienen muchas posibilidades de ganar el Gran Premio Pan Pacific. Pero todo se va al garete cuando a Scott se le ocurre improvisar con unos pasos que no están permitidos por la Federación. Por este motivo, Liz le abandona. Scott se queda sin pareja de baile a consecuencia de su atrevimiento. La salvación se presenta con Fran, una bailarina principiante, pero con una calidad indiscutible.', '/f6vs4DQGuNpLuA5Z7k69uuKpbVG.jpg', '/5gPUA8ABoBK4D1GUkL1NXTSS8Wq.jpg', 6.6, 'PLwfNOrIqSs', array['1001']::text[], 816, null, 'segura', null),
(10403, 'movie', 'El juego de Hollywood', 'El juego de Hollywood', 'The Player', 1992, 'Robert Altman', 'Griffin Mill, productor cinematográfico de Hollywood, recibe amenazas escritas de un guionista al que rechazó un proyecto. Intentan llegar a un acuerdo, pero tras una terrible discusión, Griffin lo mata. Dada la crisis económica por la que atraviesan los estudios, estos harán todo lo posible para que eluda la responsabilidad de los hechos.', '/bwEunuhDYLXsHzRDLz0aDBe1XoA.jpg', '/tKyxF6ZyxF65CcJKBKId1VavpGP.jpg', 7.2, 'HpDDTS08wPs', array['1001']::text[], 817, null, 'segura', null),
(500, 'movie', 'Reservoir Dogs', 'Reservoir Dogs', 'Reservoir Dogs', 1992, 'Quentin Tarantino', 'Una banda organizada formada por seis individuos es contratada para dar un golpe. Anteriormente varios de los miembros no se conocían entre sí, por lo que entre ellos usan nombres en clave. El objetivo: atracar una empresa para llevarse unos diamantes. Pero, antes de que suene la alarma, la policía ya está allí. Algunos mueren en el atraco, y el resto se reúne en el lugar convenido.', '/hxmJqXFFnXLlvPIdCW2k3UGLCgZ.jpg', '/jwt159hXWA9Q5xpBo8hWb3zwLi7.jpg', 8.1, 'KlDJKZ8kJ-A', array['1001']::text[], 818, null, 'segura', null),
(9504, 'movie', 'Glengarry Glen Ross', 'Glengarry Glen Ross (Éxito a cualquier precio)', 'Glengarry Glen Ross', 1992, 'James Foley', 'En una empresa inmobiliaria, de la ciudad de Chicago y en plena, depresión económica, Blake (Alec Baldwin) en vista que sus nuevas técnicas comerciales, no son bien acogidas, entre sus comerciales, les lanza un reto a todos sus empleados, el mejor vendedor será recompensado con un ''Cadillac'', al segundo con un ''juego de cuchillos'' y el último simplemente será ''despedido''. Desde entonces se irá abriendo una brecha entre ellos, cada uno reacciona de distinta forma a este reto, todos empiezan a tenderse trampas y en pensar la manera, de vender o no ser, el peor vendedor, incluyendo, el robo de las "fichas" o "tarjetas de presentación" de los clientes, para conseguir el éxito.', '/rQtRL2hIOrKNzBZEdTpOdpp2tgr.jpg', '/qukaw3P4MOFNdxjhNpClhT9unr8.jpg', 7.3, '_VrekKSuFto', array['1001']::text[], 819, null, 'segura', null),
(10412, 'movie', 'Romper Stomper', 'Romper Stomper', 'Romper Stomper', 1992, 'Geoffrey Wright', 'Hando es el líder de una banda de skinheads que impone el terror en el centro de Melbourne apaleando a la población local vietnamita, por considerarla un claro ejemplo de la impureza racial en Australia. Finalmente, los vietnamitas deciden hacer frente a sus agresores para demostrarles que no están dispuestos a sucumbir al miedo.', '/urE3Jzl3zuz2XUmAq2rXubYn3SD.jpg', '/cfGKEah2uUli5HPG1Ry3QK3lwDh.jpg', 6.5, 'Tu2JLPh4A40', array['1001']::text[], 819, null, 'segura', null),
(33, 'movie', 'Sin perdón', 'Sin perdón', 'Unforgiven', 1992, 'Clint Eastwood', 'William Munny es un pistolero retirado, viudo y padre de familia, que tiene dificultades económicas para sacar adelante a su hijos. Su única salida es hacer un último trabajo. En compañía de un viejo colega y de un joven inexperto, Munny tendrá que matar a dos hombres que cortaron la cara a una prostituta.', '/bhcVwMko4DbSELZapIQv4mmdPKY.jpg', '/rvRGFevvZK48onX0PYI1eQLbuJd.jpg', 7.9, 'Ex_VDI8RJH0', array['1001']::text[], 820, null, 'segura', null),
(97044, 'movie', 'Aileen Wuornos: The Selling of a Serial Killer', 'Aileen Wuornos: The Selling of a Serial Killer', 'Aileen Wuornos: The Selling of a Serial Killer', 1992, 'Nick Broomfield', 'Documental dirigido por Nick Broomfield, que examina paso a paso el perturbador caso de Aileen Wuornos, una prostituta de carretera acusada y condenada a muerte por asesinar a siete conductores, los cuales Aileen aseguró, intentaron violarla.', '/cRsTiPrgzWVFnSw14biZkrPEpY9.jpg', '/2X4rN11T056eHyYNt44p6eHQ6C7.jpg', 6.8, '7vd1K65fawU', array['1001']::text[], 821, null, 'segura', null),
(10241, 'movie', 'Cuento de invierno', 'Cuento de invierno', 'Conte d''hiver', 1992, 'Éric Rohmer', 'Durante unas vacaciones estivales, Felicia y Charles tienen un apasionado romance, pero debido a una confusión de direcciones pierden el contacto. Cinco años después, en Navidad, Felicia vive en París con su madre y con su hija nacida nueve meses después de aquel verano. En su vida sentimental, Felicia duda entre Maxence, un peluquero, y Loic, un joven librero intelectual, pero es incapaz de comprometerse con ninguno de ellos porque no puede olvidar a su antiguo amor.', '/dsAX65ms9cjubZ5RxDD6PHU0fD5.jpg', '/hfTKQGmXbaeOmiRmHdQ6A4vK95T.jpg', 7.0, 'lfhcwzO0VTk', array['1001']::text[], 821, null, 'segura', null),
(68004, 'movie', 'La actriz (Yuen ling-yuk)', 'Center Stage', '阮玲玉', 1991, '關錦鵬', 'Narra y homenajea la vida de Ruan Ling Yu, célebre actriz china de cine mudo de los años 30 que tras una vida privada y pública llena de dificultades y sinsabores se suicidó a la edad de 25 años y en la cima de su carrera. Según el prestigioso crítico norteamericano Jonathan Rosenbaum, una de sus diez películas preferidas de los 90.', '/oxeiEVNJDLwSGByC70gQULpXiKk.jpg', '/sZhMWwFYPpgnmhntFeg3jyL7nnR.jpg', 7.3, 'SzBtM0Zfckg', array['1001']::text[], 822, null, 'probable', '[{"tmdb_id": 68004, "titulo": "Center Stage", "original": "阮玲玉", "anio": 1991, "votos": 95, "poster_path": "/oxeiEVNJDLwSGByC70gQULpXiKk.jpg", "sim": 0.32}]'::jsonb),
(10086, 'movie', 'Ocurrió cerca de su casa', 'Ocurrió cerca de su casa', 'C''est arrivé près de chez vous', 1992, 'Rémy Belvaux, André Bonzel, Benoît Poelvoorde', 'Un asesino en serie y ladrón es seguido a todas horas por un equipo de televisión que registra todas sus reflexiones para mostrarlas en un documental, al tiempo que el psicópata prosigue con sus criminales actividades.', '/16atKAEkswOXoW3FkbJfw9MkbkL.jpg', '/7QLGk7qKm66dtjTtpVeAIRocoan.jpg', 7.2, '3HFuTY3HpV8', array['1001']::text[], 823, null, 'segura', null),
(10997, 'movie', 'Adiós a mi concubina', 'Adiós a mi concubina', '霸王别姬', 1993, '陈凯歌', 'China, 1925. Los militares gobiernan Pekín y, aunque en la ciudad la situación política es inestable, hay una constante en la vida cotidiana: la ópera, un espectáculo donde incluso los personajes femeninos deben ser representados por hombres. Entre los nuevos muchachos destinados a ser estrellas de la ópera de Pekín se encuentran el delicado Douzi y Shitou, que le toma bajo su protección. Ambos forjan una gran amistad, y Douzi se enamora profundamente del chico mayor. Como Douzi tiene la belleza de una mujer, le forman en papeles femeninos, mientras que al atlético Shitou le entrenan principalmente para papeles militares. Entre las óperas que estudian se encuentra "Adiós a mi concubina"...', '/pHe4sPQHlfWsYxPGW9A0lvMO0hn.jpg', '/bBiZN1epQTu3F8iFLBuMhc4TRzr.jpg', 8.0, 'FFiHfDBt9lE', array['1001']::text[], 824, null, 'segura', null),
(11386, 'movie', 'Juego de lágrimas', 'Juego de lágrimas', 'The Crying Game', 1992, 'Neil Jordan', 'La organización terrorista IRA secuestra a un soldado británico. Durante su confinamiento, el prisionero entabla amistad con Fergus, uno de los terroristas, y le pide que, si lo matan, vaya a ver a su novia. Más tarde, Fergus, huyendo de sus compañeros, acude al pub donde trabaja Dil, la novia del soldado británico.', '/lYxwV0lL28j7JjOPtKcxJ1Byiud.jpg', '/k4ZrvqTWADP1nzgXNSKDNk4xOEB.jpg', 6.8, 'FRxmK7Q3yF4', array['1001']::text[], 824, null, 'segura', null),
(137, 'movie', 'Atrapado en el tiempo', 'Atrapado en el tiempo', 'Groundhog Day', 1993, 'Harold Ramis', 'Phil, hombre del tiempo de una cadena de televisión, es enviado un año más a Punxstawnwey, a cubrir la información del festival de El día de la marmota. En el viaje de regreso, Phil y su equipo se ven sorprendidos por una tormenta que les obliga a regresar a la pequeña ciudad. A la mañana siguiente, al levantarse, Phil escucha en el radiodespertador el mismo programa que la mañana anterior.', '/j8ZRAOctUiw7YzrQGuyCRIAJPIW.jpg', '/4W6RYDNe4OByNryOCvJprrutm9h.jpg', 7.6, 'UFPjz8l2U8k', array['1001']::text[], 825, null, 'segura', null),
(20967, 'movie', 'Thirty Two Short Films About Glenn Gould', 'Sinfonía en soledad: un retrato de Glenn Gould', 'Thirty Two Short Films About Glenn Gould', 1993, 'François Girard', 'Una investigación en treinta y dos partes sobre la mente y el alma del internacionalmente reconocido virtuoso del piano Glenn Gould (1932-1982), para revelar su complejo y enigmático carácter al tomar la estructura de las Variaciones Goldberg de J.S. Bach. Glenn Gould, canadiense, fue un niño prodigio que componía a los 5 años y a los 15 daba conciertos. El film fue definido por la crítica como una cargante exaltación de la excentricidad.', '/3GTmkUpCb1uL7psLYqAHyIyld51.jpg', '/6srvLtwWhy4IvkNjxM3IfPDcRJL.jpg', 7.0, null, array['1001']::text[], 826, null, 'segura', null),
(695, 'movie', 'Vidas cruzadas', 'Vidas cruzadas', 'Short Cuts', 1993, 'Robert Altman', 'Adaptación de varios relatos del escritor norteamericano Raymond Carver (1939-1988). Retrato de la vida cotidiana de un grupo muy heterogéneo de personas que viven en Los Ángeles e intentan afrontar como pueden las dificultades de su vida laboral y personal, gentes que se cruzan indiferentes ignorando los dramas ajenos. Sin embargo, en medio de tanta cotidianeidad, late la presencia del terror.', '/djb04es37zyRLkBOOFyDDkZTNpo.jpg', '/j44XhCxpLTi8WnrX52H83Z86ovG.jpg', 7.2, 'ePyhGz9_RCI', array['1001']::text[], 826, null, 'segura', null),
(96712, 'movie', 'El maestro de marionetas', 'El maestro de marionetas', '戲夢人生', 1993, 'Hou Hsiao Hsien', 'Un famoso maestro de marionetas oriental narra la historia de su vida.', '/m1ibGb0qnxinBxG61SbLGGuJKu2.jpg', '/izWGOOsJJGS6ffd1oUFiQ4f1bN6.jpg', 6.6, 'GL22Cp6-lio', array['1001']::text[], 827, null, 'segura', null),
(9800, 'movie', 'Philadelphia', 'Philadelphia', 'Philadelphia', 1993, 'Jonathan Demme', 'Andrew Beckett, un joven y prometedor abogado de Philadelphia, es despedido del prestigioso bufete en el que trabaja cuando sus jefes se enteran de que ha contraído el sida. Decide entonces demandar a la empresa por despido improcedente, pero en un principio ningún abogado acepta defender su caso.', '/s3QaAaIkuLRpy0QF1vwTurKPgFN.jpg', '/nWO4sGqH950N2fij8X0Pwumqe9k.jpg', 7.7, 'qf49UApA88s', array['1001']::text[], 827, null, 'segura', null),
(329, 'movie', 'Parque Jurásico', 'Jurassic Park (Parque Jurásico)', 'Jurassic Park', 1993, 'Steven Spielberg', 'El multimillonario John Hammond tiene una idea para un espectacular parque temático: una isla retirada donde los visitantes puedan observar dinosaurios reales. Con la última tecnología en el desarrollo de ADN, los científicos pueden clonar braquiosaurios, triceratops, velociraptors y un tiranosaurio rex, utilizando para ello la sangre fosilizada en ámbar contenida en insectos que los mordieron hace millones de años. Los paleontólogos Alan Grant, Ellie Sattler y Ian Malcolm visitan el parque y quedan muy sorprendidos con los resultados obtenidos. Pero cuando un problemático empleado manipula el sofisticado sistema de seguridad los dinosaurios escapan, obligando a los visitantes a luchar por su supervivencia.', '/1r8TWaAExHbFRzyqT3Vcbq1XZQb.jpg', '/4SyDTF02R5BepqSdQmOaNCHObzF.jpg', 8.0, 'Rz_FvTXa_qY', array['1001']::text[], 828, null, 'segura', null),
(713, 'movie', 'El piano', 'El piano', 'The Piano', 1993, 'Jane Campion', 'Año 1851. Ada, que es muda desde niña, acaba de enviudar. Un matrimonio concertado la obliga a dejar su Escocia natal y viajar a Nueva Zelanda, acompañada de su hija y de su piano. Allí conoce a su futuro marido, un próspero granjero que se niega a llevar a casa el piano. Abandonado en la playa, el instrumento será rescatado por un vecino que establece un extraño pacto con Ada: él la dejará usar su piano a cambio de que ella se deje tocar.', '/6Dr3APk7mPUpiqbLrHXQG9nJ0R9.jpg', '/c2O99arhWcuLexMHiuRfSuDMpYm.jpg', 7.4, 'IeHHVJGrfpk', array['1001']::text[], 829, null, 'segura', null),
(108, 'movie', 'Tres colores: azul', 'Tres colores. Azul', 'Trois couleurs : Bleu', 1993, 'Krzysztof Kieślowski', 'En un accidente de coche, Julie pierde a su esposo Patrice, un prestigioso compositor, y a la hija de ambos, Anna. Al recuperarse de sus lesiones, Julie decide comenzar una nueva vida, independiente, solitaria y anónima, alejada de los privilegios que antes disfrutaba. En su propósito se cruza Sandrine, una periodista especializada en música que la persigue intentando probar que era Julie quien componía las piezas que hicieron famoso a su marido. También pretenderá entrar en su vida Olivier, el ayudante de Patrice, enamorado de Julie desde muchos años atrás, que la convence para terminar el «Concierto para Europa», una ambiciosa obra inacabada del músico.', '/acF0MZyMhe1svIxp17xxIstPIqi.jpg', '/pXvYw0QOPbHJVvwGbZfrSNY2vnB.jpg', 7.6, 'ZZcRioiaZAU', array['1001']::text[], 829, null, 'segura', null),
(9261, 'movie', 'El banquete de boda', 'El banquete de boda', '囍宴', 1993, 'Ang Lee', 'Simon y Wai-Tung son dos gays que viven juntos en Manhattan. Para disipar las sospechas de los padres de Wai-Tung, Simon sugiere que organice una boda de conveniencia con Wei-Wei, una joven inmigrante que necesita la carta verde de inmigración para poder permanecer en los Estados Unidos. Pero cuando los padres de Wai-Tung llegan a Nueva York insisten en organizar el banquete, lo que traerá muchas complicaciones.', '/nt7qIzjnVXCOKlsltuzKzjNddH3.jpg', '/AiADW9ru9v1DLbFo4Ac76CtlXjK.jpg', 7.2, '5kVkRhXt3S4', array['1001']::text[], 830, null, 'segura', null),
(44162, 'movie', 'La cometa azul (Lan feng zheng)', 'La cometa azul', '蓝风筝', 1994, '田壮壮', 'Viaje de aire intimista por los acontecimientos más tumultuosos de China. Una película que tuvo problemas en el rodaje, y que le impidió a su director, merced a una prohibición por parte de las autoridades chinas, el poder realizar más películas durante una década. (FILMAFFINITY)', '/xKaN23cz9WSpsAZlUK9UebhbTuV.jpg', '/8J2JCoSB0faP0QWOpAmDHGJ7YSG.jpg', 7.2, 'zwW0mr9K9L4', array['1001']::text[], 830, null, 'segura', null),
(424, 'movie', 'La lista de Schindler', 'La lista de Schindler', 'Schindler''s List', 1993, 'Steven Spielberg', 'Oskar Schindler, un hombre de enorme astucia y talento para las relaciones públicas, organiza un ambicioso plan para ganarse la simpatía de los nazis. Después de la invasión de Polonia por los alemanes, consigue, gracias a sus relaciones con los nazis, la propiedad de una fábrica de Cracovia. Allí emplea a cientos de operarios judíos, cuya explotación le hace prosperar rápidamente. Su gerente, también judío, es el verdadero director en la sombra, pues Schindler no tiene el menor conocimiento industrial.', '/3Ho0pXsnMxpGJWqdOi0KDNdaTkT.jpg', '/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 8.6, '0Z9cLiliBh0', array['1001']::text[], 831, null, 'segura', null),
(2759, 'movie', 'Las aventuras de Priscilla, reina del desierto', 'Las aventuras de Priscilla, reina del desierto', 'The Adventures of Priscilla, Queen of the Desert', 1994, 'Stephan Elliott', 'Tres artistas de cabaret que viven en Sidney son contratadas para actuar durante cuatro semanas en un hotel de Alice Springs, en medio del desierto rojo de Australia. Les espera una gran aventura, pero una cosa es atravesar el país en autobús, dejando atrás todos sus problemas, y otra llegar a su destino sanas y salvas. Sobre todo si Felicia y Mitzi son reinas del drag y Benardette transexual. Inician así un periplo de dos semanas, con música sonando a toda pastilla y el autocar repleto de un llamativo vestuario y zapatos de plataforma.', '/yuNpEhxRIE2fEj8ehJKrpcdNv4.jpg', '/q1PuySDtRiKSgxAZjpIbFvvLOus.jpg', 7.3, 'VFmwVI-5lfU', array['1001']::text[], 832, null, 'segura', null),
(110, 'movie', 'Tres colores: rojo', 'Tres colores: Rojo', 'Trois couleurs : Rouge', 1994, 'Krzysztof Kieślowski', 'Valentina, joven modelo que comienza a ser conocida, ha atropellado con su coche a Rita, una perra que esperaba cachorros. Después de curarla, intenta devolverla a su dueño. Asi conocerá a un hombre mayor, juez jubilado, que rechaza al animal. Valentina descubre que está obsesionado por una enfermiza afición: espiar a todo el mundo.', '/eePgjE6ZP381J77dUPVgJy9cIJ4.jpg', '/xkk7cqXFzY4aCCG5AYWZCFQFbIX.jpg', 7.9, 'BMm0goTX2qo', array['1001']::text[], 833, null, 'segura', null),
(14275, 'movie', 'Hoop Dreams', 'Hoop Dreams', 'Hoop Dreams', 1994, 'Steve James', 'Retrata las vidas de dos chicos afroamericanos y sus esfuerzos para ser jugadores de baloncesto en la universidad, y así poder llegar a ser profesionales de la NBA.', '/gLzHl2XBtVwycl8DxdOXRHPm8G3.jpg', '/pYeiEm55NySzK9ksKlQGlFQNapz.jpg', 7.6, '-TRIx7oD3lo', array['1001']::text[], 834, null, 'segura', null),
(13, 'movie', 'Forrest Gump', 'Forrest Gump', 'Forrest Gump', 1994, 'Robert Zemeckis', 'Forrest Gump es un chico con deficiencias mentales no muy profundas y con alguna incapacidad motora que, a pesar de todo, llegará a convertirse, entre otras cosas, en un héroe durante la Guerra del Vietnam. Su persistencia y bondad le llevarán a conseguir una gran fortuna, ser objeto del clamor popular y a codearse con las más altas esferas sociales y políticas del país. Siempre sin olvidar a Jenny, su gran amor desde que era niño.', '/oiqKEhEfxl9knzWXvWecJKN3aj6.jpg', '/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg', 8.5, 'aSEPD9w_dLM', array['1001']::text[], 835, null, 'segura', null),
(8587, 'movie', 'El rey león', 'El rey león', 'The Lion King', 1994, 'Roger Allers, Rob Minkoff', 'La sabana africana es el escenario en el que tienen lugar las aventuras de Simba, un pequeño león que es el heredero del trono. Sin embargo, se ve forzado a exiliarse al ser injustamente acusado de la muerte de su padre. Durante su destierro, hará buenas amistades y, finalmente, regresará para recuperar lo que legítimamente le corresponde.', '/b0MxU37dNmMwKtoPVYPKOZSIrIn.jpg', '/wXsQvli6tWqja51pYxXNG1LFIGV.jpg', 8.2, 'bjJvvrKl83M', array['1001']::text[], 836, null, 'segura', null),
(2292, 'movie', 'Clerks', 'Clerks', 'Clerks', 1994, 'Kevin Smith', 'Narra en clave de humor la vida, amores y excentricidades de dos jóvenes cajeros de New Jersey. Un joven se ve obligado a quedarse despachando en un supermercado en su día libre, ante la ausencia del jefe. Por la tienda pasan muchos personajes curiosos.', '/mY0PDi3ZiyExPzeW9rzYMe1fnDo.jpg', '/sjfbZVKRGh84lNxhqvuhdvovh18.jpg', 7.4, 'f8yqQkABBjY', array['1001']::text[], 837, null, 'segura', null),
(712, 'movie', 'Cuatro bodas y un funeral', 'Cuatro bodas y un funeral', 'Four Weddings and a Funeral', 1994, 'Mike Newell', 'Charles y sus amigos, todos ellos solteros y sin compromiso, han llegado a una edad en la que casi todos sus conocidos se han casado. En una de las bodas, a la que el grupo ha sido invitado, Charles conoce a Carrie, una americana de la que se enamora a primera vista. Esa noche la pasan juntos, pero no vuelven a verse. Tendrán que esperar a la siguiente boda, en la que Carrie le presenta a su prometido.', '/hpPe7zVnNuqfzDy3bzXnWnJWA83.jpg', '/ejFaHWnDP29z7ePw2cJVOsWvOvH.jpg', 6.8, 'tvdlnbfaJ3E', array['1001']::text[], 837, null, 'segura', null),
(241, 'movie', 'Asesinos natos', 'Asesinos natos', 'Natural Born Killers', 1994, 'Oliver Stone', 'Micky y Mallory son una poco convencional pareja de jovenes amantes que sienten que han nacido para matar: son dos despiadados criminales que tienen atemorizada a la población. Un presentador de un programa sensacionalista se aprovecha de la fascinación que su personalidad ejerce sobre el público y convierte a los asesinos en héroes televisivos.', '/77mhFCbANeAR1AuWpTZFLIe2icz.jpg', '/k3TOt50cHvTLXWYPnXP0szhiXB8.jpg', 7.0, 'vv7-39m08u0', array['1001']::text[], 838, null, 'segura', null),
(25284, 'movie', 'La última seducción', 'La última seducción', 'The Last Seduction', 1994, 'John Dahl', 'Bridget Gregory (Linda Fiorentino) es una mujer fría y calculadora que huye con un millón de dólares que ella y su marido (Bill Pullman) habían conseguido traficando con medicamentos. En un pequeño pueblo conoce a Mike Swale (Peter Berg), un hombre que se enamora perdidamente de ella, pero a Bridget él sólo le interesa como instrumento para librarse definitivamente de su marido y quedarse con el dinero.', '/q1s59C6cEbbMQvyn0k8xyafhMXp.jpg', '/8KbWuuthHkS7U1wntWCrgo36igG.jpg', 6.7, 'wBAZQ029TBQ', array['1001']::text[], 838, null, 'segura', null),
(680, 'movie', 'Pulp Fiction', 'Pulp Fiction', 'Pulp Fiction', 1994, 'Quentin Tarantino', 'Jules y Vincent, dos asesinos a sueldo con muy pocas luces, trabajan para Marsellus Wallace. Vincent le confiesa a Jules que Marsellus le ha pedido que cuide de Mia, su mujer. Jules le recomienda prudencia porque es muy peligroso sobrepasarse con la novia del jefe. Cuando llega la hora de trabajar, ambos deben ponerse manos a la obra. Su misión: recuperar un misterioso maletín.', '/hNcQAuquJxTxl2fJFs1R42DrWcf.jpg', '/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 8.5, 'Yydi7TMo5n0', array['1001']::text[], 839, null, 'segura', null),
(26933, 'movie', 'Los juncos salvajes', 'Los juncos salvajes', 'Les Roseaux sauvages', 1994, 'André Téchiné', 'Provenza, 1962. Con la guerra de Independencia de Argelia como telón de fondo, la trama se basa en las relaciones de un grupo de estudiantes de un internado. François, un chico de dieciocho años, descubre que es gay y que está enamorado de Serge, su compañero de cuarto. Éste al principio parece corresponderle, y una noche se acuestan juntos. Pero, a continuación, Serge no quiere saber nada de François y se interesa por Maité, una joven militante comunista, hija de una de las profesoras.', '/uLiupC1Lz6we3UI6CERvzpDwMod.jpg', '/9MbN03RE7vEn1trsdFaBdisFXPo.jpg', 7.0, 'HW_mUfpGjiI', array['1001']::text[], 840, null, 'segura', null),
(278, 'movie', 'Cadena perpetua', 'Cadena perpetua', 'The Shawshank Redemption', 1994, 'Frank Darabont', 'Acusado del asesinato de su mujer, Andrew Dufresne, tras ser condenado a cadena perpetua, es enviado a la prisión de Shawshank. Con el paso de los años conseguirá ganarse la confianza del director del centro y el respeto de sus compañeros presidiarios, especialmente de Red, el jefe de la mafia de los sobornos.', '/uRRTV7p6l2ivtODWJVVAMRrwTn2.jpg', '/pNjh59JSxChQktamG3LMp9ZoQzp.jpg', 8.7, '4u87tmlj4oE', array['1001']::text[], 840, null, 'segura', null),
(11104, 'movie', 'Chungking Express', 'Chungking Express', '重慶森林', 1994, 'Wong Kar-wai', 'Dos historias de amor independientes que se desarrollan en el popular barrio turístico de Tsimhatsui, en Hong Kong. La primera describe el fugaz encuentro entre un joven policía en plena crisis amorosa y una misteriosa mujer fatal traficante de drogas. La segunda se centra en el singular romance entre un solitario y sencillo agente de policia y la joven camarera del pobre bar donde aquél suele comer.', '/nl246bqCp6lmRF4mHF293F9w42O.jpg', '/8e6avmXiqurj5LHkmdHBq6rc5jm.jpg', 8.0, 'ZlkKGZsRKJg', array['1001']::text[], 841, null, 'segura', null),
(26564, 'movie', 'Crumb', 'Crumb', 'Crumb', 1995, 'Terry Zwigoff', 'Documental sobre la vida del dibujante de cómics underground por excelencia, Robert Crumb, autor entre otros de personajes como Fritz el Gato. Una persona excéntrica, a partes iguales entrañable y enfermiza, cuyo arte ha estado en boca de todos desde hace más de 30 años.', '/9ocTHdBCJdwJ65Tubg3lYlfMxEY.jpg', '/1mlfORlfu2PtZnlEB3gMKqJy7Qp.jpg', 7.6, '67uWAtFmjYI', array['1001']::text[], 842, null, 'segura', null),
(31414, 'movie', 'Sátántangó', 'Sátántangó', 'Sátántangó', 1994, 'Tarr Béla', 'La historia relata gradualmente los problemas de una granja colectiva durante unos pocos días de otoño en los años de la Hungría post-comunista, observada desde la perspectiva de distintos personajes. (FILMAFFINITY)', '/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg', '/5a4Gmk2HNeefI4Rmwdmbyoy79oy.jpg', 8.1, 'UuyznqAILAM', array['1001']::text[], 843, null, 'segura', null),
(47104, 'movie', 'A través de los olivos', 'A través de los olivos', 'زیر درختان زیتون', 1994, 'Abbas Kiarostami', 'Un equipo de rodaje llega a un pueblo del norte de Irán, en la región de Koker, devastado por un temblor de tierra, para realizar una película. Hossein, un muchacho del lugar, es contratado como ayudante del equipo y, además, se le asigna la interpretación de un pequeño papel. Casualmente, también colabora en la película una muchacha del vecindario, de la que Hossein está locamente enamorado, pero los padres de ella lo rechazan porque carece de recursos económicos.', '/lmPX2vG1Y4DhoacR3KIPRiCICsB.jpg', '/4BIIX7qiKYYJSm4cWTB2dHfCwZE.jpg', 7.5, 'T4Ue-t2XKnU', array['1001']::text[], 844, null, 'segura', null),
(1024, 'movie', 'Criaturas celestiales', 'Criaturas celestiales', 'Heavenly Creatures', 1994, 'Peter Jackson', 'Nueva Zelanda, mediados del siglo XX. La amistad entre dos compañeras de colegio adolescentes es tan intensa y estrecha que despierta el recelo de los padres de una de ellas. Las chicas crean un mundo imaginario y lleno de fantasía en el que se refugian para vivir de espaldas al resto del mundo. Basada en hechos reales.', '/sKuTsGjvagZdZATIu4tPkozKkN8.jpg', '/jHjOY9vgE7maH2HRk2fd9lOPg8.jpg', 6.9, '_bIUDcnHDlg', array['1001']::text[], 845, null, 'segura', null),
(25403, 'movie', 'Caro diario', 'Caro Diario (Querido diario)', 'Caro diario', 1993, 'Nanni Moretti', 'Film dividido en tres episodios, que refleja la vida y opiniones de Nanni Moretti. «En mi Vespa» es una aproximación a la vida cotidiana de Roma durante el mes de agosto; en "Islas" visita a Gerardo, un amigo que lleva once años viviendo en Lipari; juntos recorren otras íslas como Salina, Stromboli, Panarea y Alicudi. En "Médicos" el director rueda su propia quimioterapia y su recorrido por hospitales y especialistas incapaces de diagnosticarle la causa de unos insoportables picores.', '/jZQqFvrNEOMxC8B9XwHVdpEPyIB.jpg', '/dsMqUvdYGeXSky9cQO26JJOhFZa.jpg', 7.3, 'Qujgo5C09rM', array['1001']::text[], 846, null, 'segura', null),
(236, 'movie', 'La boda de Muriel', 'La boda de Muriel', 'Muriel''s Wedding', 1994, 'P.J. Hogan', 'Muriel es una chica con sobrepeso que vive en un mundo de fantasía, canciones de ABBA y catálogos nupciales. Sueña con un príncipe azul que algún día la liberará de su odiosa familia y de sus burlonas amigas. Cansada de esperar su llegada, decide irse a la ciudad y buscarlo. Uno de los mayores éxitos del cine australiano de los noventa.', '/ubKKOEaBHdmGWqAObbTjryKT1EX.jpg', '/x4sqnmV2nAKIG6cmt9WAF9xRA2M.jpg', 6.8, 'JJVWXHRDqec', array['1001']::text[], 846, null, 'segura', null),
(9732, 'movie', 'El reino', 'El rey león 2: El tesoro de Simba', 'The Lion King II: Simba''s Pride', 1998, 'Darrell Rooney', 'Kiara, la hija primogénita de Simba y heredera de los dominios del clan, va en busca de aventuras por el Serengeti. Escapando de sus cuidadores, Timón y Pumba, Kiara se adentra en las tierras oscuras, que se sitúan fuera de los límites establecidos para ella. Allí conoce a Kovu, un joven cachorro elegido para seguir las huellas de Scar. Alcanzar la paz entre los habitantes de las tierras oscuras y los del territorio de Simba depende de Kiara y Kovu. Pero... ¿llegará a encontrar el amor una manera de unir dos mundos tan diferentes?', '/zdD5VcvTD43p048ueswYdgLJZh.jpg', '/vyOFlV1afDHb9MMwJVyON4qXbvC.jpg', 6.9, '7Wq2R7-UqZ8', array['1001']::text[], 847, null, 'probable', '[{"tmdb_id": 9732, "titulo": "El rey león 2: El tesoro de Simba", "original": "The Lion King II: Simba''s Pride", "anio": 1998, "votos": 4797, "poster_path": "/zdD5VcvTD43p048ueswYdgLJZh.jpg", "sim": 0.176}, {"tmdb_id": 28302, "titulo": "La princesa Cisne III: El misterio del reino encantado", "original": "The Swan Princess: The Mystery of the Enchanted Kingdom", "anio": 1998, "votos": 250, "poster_path": "/kzmFrHuvxRXN8HWaOZMa6cOf0Yc.jpg", "sim": 0.182}, {"tmdb_id": 27303, "titulo": "Asesino del más allá", "original": "Hideaway", "anio": 1995, "votos": 178, "poster_path": "/c0GmHyUKYNd4QkOzCAetLfaErZY.jpg", "sim": 0.32}, {"tmdb_id": 75826, "titulo": "Hércules y el reino perdido", "original": "Hercules and the Lost Kingdom", "anio": 1994, "votos": 142, "poster_path": "/1ZeDv8ffdIqLxTV1glIKCTC1xLX.jpg", "sim": 0.312}]'::jsonb),
(9598, 'movie', 'Babe, el cerdito valiente', 'Babe: El cerdito valiente', 'Babe', 1995, 'Chris Noonan', 'En la granja Hogget vive toda clase de animales. Cada animal atiene un trabajo que sabe como hacer y cada uno intenta hacerlo bien, porque sabe cual es su sitio. A la granja llega Babe, un cerdito que el granjero ha ganado en un concurso. Hogget siente que hay algo especial en Babe y decide enseñarle el oficio de perro pastor y de esta forma tan peculiar, Babe evita ser la cena de Navidad.', '/6yy3Y03MF5hhliTYSKPTTvH34gT.jpg', '/agkZziO4ZPAsVfKUrJD68lys08P.jpg', 6.3, 'XTXupTzPOKU', array['1001']::text[], 848, null, 'segura', null),
(97046, 'movie', 'Deseret', 'Deseret', 'Deseret', 1996, 'James Benning', '"Deseret" es el nombre propuesto por los mormones al solicitar la declaración de estado del territorio donde se establecería más tarde Utah. La película combina 92 pasajes del "New York Times", desde 1852 hasra 1991, con tomas estáticas magníficamente compuestas recogidas por todo el territorio', '/jwmZxxNSKFUfmersZRfdl8kta2O.jpg', null, 5.6, null, array['1001']::text[], 849, null, 'segura', null),
(197, 'movie', 'Braveheart', 'Braveheart', 'Braveheart', 1995, 'Mel Gibson', '¿Qué clase de hombre desafiaría a un rey? ''Braveheart'' es una historia épica medieval sobre la independencia de Escocia en el siglo XIII, basada en la leyenda de William Wallace, un montañés escocés que arrastra a su clan a luchar contra la tiranía del rey Eduardo I de Inglaterra. Después del brutal asesinato de su joven esposa por los ingleses, Wallace sólo busca venganza. Hambrientos y en inferior número, Wallace lidera a los patriotas escoceses y consigue organizar un ejército de guerreros sedientos de libertad logrando recuperar con ello el espíritu que haría a Escocia libre para siempre.', '/cDMYybBU4COJfTwcPgnihwY5EiP.jpg', '/1m1c5gIWWkb1FEC9lzsoXHhhs7b.jpg', 7.9, 'GCwxOPpM8Xw', array['1001']::text[], 850, null, 'segura', null),
(32646, 'movie', 'Safe', 'Safe', 'Safe', 1995, 'Todd Haynes', 'Carol es una ama de casa (Julianne Moore) que, a pesar de llevar una vida idílica, empieza a tener los mismos síntomas de alguien conocido que tuvo una misteriosa enfermedad... y que murió a causa de ella.', '/2O71QsBkbqdLqQdx2yuNpJ4pFPq.jpg', '/p8O3WhMWumLrLp21BRW80kBND4d.jpg', 7.0, 'Qe_UmLAFuHE', array['1001']::text[], 850, null, 'segura', null),
(524, 'movie', 'Casino', 'Casino', 'Casino', 1995, 'Martin Scorsese', 'Las Vegas, 1973. Sam "Ace" Rothstein, un profesional de las apuestas, es el eficaz director de un importante casino que pertenece a un grupo de mafiosos. Su misión es controlar el funcionamiento del negocio y garantizar que la corriente de dinero que va a parar a manos de sus jefes siga fluyendo. Las Vegas es un lugar ideal para millonarios y políticos, pero es también lugar de paso de tahúres, prestamistas, traficantes de drogas y matones. Un día el violento Nicky Santoro, al que sus jefes han encargado que cuide de Sam, llega a Las Vegas con la intención de quedarse.', '/7x8lsyTB0G7OrLzQ7qxt3ywQ4OY.jpg', '/iZGiMD0p1M2AOmzKknFo5bkuz94.jpg', 8.0, 'aFP8CjozpkY', array['1001']::text[], 851, null, 'segura', null),
(862, 'movie', 'Toy Story', 'Toy Story', 'Toy Story', 1995, 'John Lasseter', 'Los juguetes de Andy, un niño de seis años, temen que haya llegado su hora y que un nuevo regalo de cumpleaños les sustituya en el corazón de su dueño. Woody, un vaquero que ha sido hasta ahora el juguete favorito de Andy, trata de tranquilizarlos hasta que aparece Buzz Lightyear, un héroe espacial dotado de todo tipo de avances tecnológicos. Woody es relegado a un segundo plano, pero su constante rivalidad se transformará en una gran amistad cuando ambos se pierden en la ciudad sin saber cómo volver a casa.', '/jvn7wy3RSNEXnFSXLpH2of2LcV6.jpg', '/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg', 8.0, 'CxwTLktovTU', array['1001']::text[], 851, null, 'segura', null),
(949, 'movie', 'Heat', 'Heat', 'Heat', 1995, 'Michael Mann', 'Neil McCauley es un experto ladrón. Su filosofía consiste en vivir sin ataduras que puedan constituir un obstáculo, si las cosas se complican. Su banda la forman criminales profesionales tan cualificados que pueden impresionar incluso al detective Vincent Hanna. Pero Hannah vive tan obsesionado con su trabajo que llega incluso a poner en peligro su relación sentimental. Cuando la banda de McCauley prepara el golpe definitivo y el equipo de Hannah intenta evitarlo, cada uno de ellos comprende que tiene que vérselas con una de las mentes más brillantes a la que se ha enfrentado en su carrera.', '/kRfh1NCkDXGFrWzL6zDmVnHjRKh.jpg', '/uI22JkEMediWyiRqhllNqeeGtW0.jpg', 7.9, '14oNcFxiVaQ', array['1001']::text[], 852, null, 'segura', null),
(85589, 'movie', 'Kjærlighetens kjøtere', 'Zero Kelvin', 'Kjærlighetens kjøtere', 1995, 'Hans Petter Moland', 'La historia gira en torno a una casa deprimente en Groenlandia, donde tres hombres contratados para cazar focas enloquecen.', '/iYoM7eHo7o6Y5sbpKhFetENNaTu.jpg', '/3OldHa5lfPTOgQVt23HDGoCZRwM.jpg', 6.5, 'icwDnDtR-U8', array['1001']::text[], 852, null, 'segura', null),
(12582, 'movie', 'Sin pistas', 'Sin pistas', 'Without a Clue', 1988, 'Thom Eberhardt', 'El Dr. Watson busca a un actor que interprete a Holmes, pero sólo encuentra a uno que es mujeriego, bebedor y vago. Aunque celoso de la atención que recibe el falso detective, deberá contar con él porque pronto llega un caso: el robo de las planchas de la casa del tesoro del reino Británico.', '/arv9FRvFwh9y29qbnrgSLyBS4A6.jpg', '/xQQsgdVRBqM8zwWTxWMCOiNiw9x.jpg', 6.8, 'lWXw-QZDdNo', array['1001']::text[], 853, null, 'dudosa', '[{"tmdb_id": 12582, "titulo": "Sin pistas", "original": "Without a Clue", "anio": 1988, "votos": 273, "poster_path": "/arv9FRvFwh9y29qbnrgSLyBS4A6.jpg", "sim": 1.0}]'::jsonb),
(46785, 'movie', 'El globo blanco', 'El globo blanco', 'بادکنک سفید', 1995, 'Jafar Panahi', 'El 21 de marzo, primer día de la primavera, se celebra en Irán el Año Nuevo. Razieh, una niña de ocho años, sueña con conseguir el tradicional pez dorado de esas fiestas. Con la ayuda de su hermano Ali, convence a su madre de que le dé dinero para comprarlo. Pero el camino hasta la tienda donde venden peces dorados es muy largo y está lleno de peligros. Razieh, sola y desamparada, vive toda clase de peripecias antes de conseguir lo que quiere: pierde y recupera el dinero, se lo roban, se le cae por una cloaca, llega tarde a la tienda. Celebrada cinta escrita por Kiarostami y premiada en Cannes.', '/4Glw8ZsSREDOUIHZY1qKR69OQkf.jpg', '/jRLhcuyTPgcaCzrTKVTVrFDWrYo.jpg', 7.5, 'bltXpgXuUp8', array['1001']::text[], 854, null, 'segura', null),
(10149, 'movie', 'Smoke', 'Smoke', 'Smoke', 1995, 'Wayne Wang', 'Brooklyn, verano de 1987. Un grupo de personas frecuenta el estanco de su barrio. Auggie Wren (Harvey Keitel), el estanquero, es el gran confidente de todos ellos. La rocambolesca historia de cómo consiguió su cámara fotográfica y de por qué se decidió a elaborar su singular colección de fotografías -el mismo encuadre de la casa de enfrente a lo largo de 14 años- le dará por fin un argumento a Paul Benjamin (William Hurt), prestigioso novelista en crisis. Paul, a su vez, ayudará a Rashid (Harold Perrineaud Jr.), un adolescente negro algo desorientado, en la búsqueda de su padre, que resulta ser un modesto mecánico (Whitaker) que intenta rehacer su vida. El círculo vital se cierra cuando estos contactos humanos implican de tal modo al propio Auggie que le obligan a asumir su olvidada responsabilidad respecto a Ruby (Stockard Channing), una antigua novia con la que tuvo una hija (Ashley Judd), que ahora, ya adolescente, pasa por un momento muy difícil.', '/qXlMABbkiwlmHWFifOjyskEfOJu.jpg', '/dkg2DcGg6cjDia20yLWDaNLBRIb.jpg', 7.2, '3v8r-ec4V2M', array['1001']::text[], 854, null, 'segura', null),
(807, 'movie', 'Seven', 'Seven', 'Se7en', 1995, 'David Fincher', 'El teniente Somerset, del departamento de homicidios, está a punto de jubilarse y ser reemplazado por el ambicioso y brillante detective David Mills. Ambos tendrán que colaborar en la resolución de una serie de asesinatos cometidos por un psicópata que toma como base la relación de los siete pecados capitales: gula, pereza, soberbia, avaricia, envidia, lujuria e ira. Los cuerpos de las víctimas, sobre los que el asesino se ensaña de manera impúdica, se convertirán para los policías en un enigma que les obligará a viajar al horror y la barbarie más absoluta.', '/uVPcVz4b2hnSGrXYLdIGRXwcivs.jpg', '/i5H7zusQGsysGQ8i6P361Vnr0n2.jpg', 8.4, 'KPOuJGkpblk', array['1001']::text[], 855, null, 'segura', null),
(19404, 'movie', 'Dilwale dulhania le jayenge', 'Un amor contra viento y marea', 'दिलवाले दुल्हनिया ले जायेंगे', 1995, 'Aditya Chopra', 'Los Singh son una familia india con grandes convicciones culturales de su nación de origen, que emigraron a Reino Unido antes de nacer sus primeros hijos. Uno de ellos querrá casarse con una mujer ajena a su cultura y para ello deberá hacer todos los esfuerzos por convencer a su familia.', '/2CAL2433ZeIihfX1Hb2139CX0pW.jpg', '/7VDLEHli74eLsYLNcq9djn1Gw76.jpg', 8.5, 'oIZ4U21DRlM', array['1001']::text[], 856, null, 'segura', null),
(11902, 'movie', 'Underground', 'Underground', 'Подземље', 1995, 'Emir Kusturica', 'En Belgrado, Yugoslavia, durante la Segunda Guerra Mundial, un poeta, Marko Dren (Miki Manojlovic), esconde a su amigo Petar Popara (Lazar Ristovski) y a su familia en un sótano para esconderse de los nazis. Allí ocultos deben fabricar armas para la guerra. Marko los engaña para que sigan fabricando armas 20 años después de la guerra y haciéndoles creer que aún no termina y que sólo han pasado 15 años. La película está llena de simbolismos y metáforas. Por ejemplo, tras el bombardeo a Belgrado, Blaky se limpia el zapato con un gato; al final, Petar, en la búsqueda de su hijo y tras descubrir que Marko y Natalija (Mirjana Jokovic) murieron, se apoya en una cruz que tiene a Cristo invertido. Además, en medio del fuego y la destrucción, hay un caballo blanco y un ganso volando.', '/qlYP9HpToAluL0swuHUL4SYDEZY.jpg', '/6ETx15gNiiAjpBjwIUqN1LdJMKH.jpg', 7.7, 'rYTvmLvLchs', array['1001']::text[], 856, null, 'segura', null),
(36266, 'movie', 'Triciclo (Xich Lo)', 'Cyclo', 'Xích lô', 1995, 'Trần Anh Hùng', 'En la superpoblada y frenética ciudad de Ho Chi Minh -antigua Saigón-, un joven adolescente, conductor de un ciclomotor que transporta a los turistas a través de las calles, trata de ganarse la vida para mantener a sus dos hermanas y a su anciano abuelo. Cuando le roban su medio de locomoción y de vida, el joven se adentrará en una espiral de crimen y violencia.', '/mdOsnSVTLwHMEH1juOLMiwXcO5o.jpg', '/bcSj4j8CfPRCHetc3pHhE1cHXU8.jpg', 6.9, 'xqPxeyfzOd4', array['1001']::text[], 857, null, 'segura', null),
(629, 'movie', 'Sospechosos habituales', 'Sospechosos habituales', 'The Usual Suspects', 1995, 'Bryan Singer', 'Dave Kujan (Chazz Palminteri), un agente especial que trabaja para el servicio de aduanas de EEUU, está investigando las consecuencias de un incendio a bordo de un barco en el puerto de San Pedro de Los Ángeles, con un balance de 27 víctimas mortales -todas aparentemente asesinadas-. La única fuente de información de Kujan es Roger Kint (Kevin Spacey), un estafador lisiado que sobrevivió al incendio. En comisaría, Kint cuenta que todo comenzó 6 semanas atrás en Nueva York, cuando 5 delincuentes, 5 "sospechosos habituales", fueron detenidos para una rueda de reconocimiento referente al robo de un camión de armas...', '/zI2ESVtVBJTo68aWuwCku78q4dZ.jpg', '/hy0Hx9fMPk2fmw26Li60z1S2giU.jpg', 8.2, 'jM3jrHGAsIE', array['1001']::text[], 858, null, 'segura', null);
